package com.bankstand;

/**
 * Change gate: the last account type the server acknowledged. The type rarely changes, so a
 * missed ack is never corrected by a later value; the server must name it in {@code
 * storedBlocks} exactly when it stored it. Holds the plain value, since it is one short string.
 */
public class AccountTypeBaseline {
  private String acked;

  public boolean changedSince(String current) {
    return current != null && !current.equals(acked);
  }

  /**
   * The read, or null while it may be the unloaded varbit: regular soon after login, unless regular
   * is what was acked. An iron type cannot come from an unloaded varbit, so it is never held.
   */
  String unlessHeld(int ticksSinceLogin, String read) {
    boolean held =
        ticksSinceLogin < DiaryBaseline.HOLD_TICKS
            && "regular".equals(read)
            && !"regular".equals(acked);
    return held ? null : read;
  }

  public void advance(String ackedNow) {
    acked = ackedNow;
  }

  /** Null means nothing is known. */
  public void restore(String value) {
    acked = value;
  }

  public String ackedValue() {
    return acked;
  }

  public void reset() {
    acked = null;
  }
}

package com.bankstand;

import net.runelite.api.Varbits;

/**
 * Maps the game's account type varbit to Bankstand's type keys. Needed because Group Ironman
 * accounts are invisible to public hiscores. Client-asserted, so never the public account type.
 */
public final class AccountTypes {

  private AccountTypes() {}

  /** Varbit 1777 ({@code IRONMAN} in {@code VarbitID}). */
  public static final int ACCOUNT_TYPE_VARBIT = Varbits.ACCOUNT_TYPE;

  /**
   * Server type keys (wire contract), indexed by varbit value. RuneLite's enum stops at 5; the
   * value 6 (unranked group) was measured on a real account.
   */
  private static final String[] BY_VALUE = {
    "regular",
    "ironman",
    "ultimate",
    "hardcore",
    "group",
    "hardcore_group",
    "unranked_group",
  };

  /** Null for an unknown value, never a fallback to {@code regular}. */
  public static String keyFor(int varbitValue) {
    if (varbitValue < 0 || varbitValue >= BY_VALUE.length) {
      return null;
    }
    return BY_VALUE[varbitValue];
  }

  /** Includes the raw value, since the varbit never changes in a session to be inspected. */
  public static String describe(int varbitValue) {
    String key = keyFor(varbitValue);
    if (key == null) {
      return "Account type: unrecognised (varbit "
          + ACCOUNT_TYPE_VARBIT
          + " = "
          + varbitValue
          + "). Please report this value.";
    }
    return "Account type: " + key + " (varbit " + ACCOUNT_TYPE_VARBIT + " = " + varbitValue + ").";
  }
}

package com.bankstand;

import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * Per-character state that survives a restart: what the server has accepted, and what the client
 * has observed. Digests are cheap to lose (one redundant submit); collection log observations are
 * not, since the game reveals the log only while the player looks at it.
 *
 * <p>{@code collectionLogAcked} and {@code collectionLogItems} must persist together: the acked
 * count is only valid against the set it counted.
 *
 * <p>Gson populates this by field, so the field names are the on-disk format.
 */
public class AckedState {

  private String skills;
  private String quests;
  private String diaries;
  private String combatAchievements;

  // The value itself, not a digest: one short word, readable in a bug report.
  private String accountType;
  private Set<Integer> collectionLogItems;
  private int collectionLogAcked;

  /**
   * Epoch millis of each capability's last fresh server acknowledgement, keyed by capability
   * name. Never stamped on a resend of already-acked data.
   */
  private Map<String, Long> lastSyncedAt;

  /** Digest of the raw per-task diary values the server last stored. */
  private String diaryTaskVars;

  // The acked diary values, not digests: a later read below them is too early to send.
  private Map<String, String> diaryFlags;
  private Map<String, Integer> diaryCounts;
  private Map<String, Map<String, Integer>> diaryTaskVarValues;

  public Map<String, String> getDiaryFlags() {
    return diaryFlags;
  }

  public Map<String, Integer> getDiaryCounts() {
    return diaryCounts;
  }

  public Map<String, Map<String, Integer>> getDiaryTaskVarValues() {
    return diaryTaskVarValues;
  }

  public void setDiaryFloor(
      Map<String, String> flags,
      Map<String, Integer> counts,
      Map<String, Map<String, Integer>> varValues) {
    diaryFlags = flags;
    diaryCounts = counts;
    diaryTaskVarValues = varValues;
  }

  /** The state of a character nothing is known about yet: everything resends once. */
  public static AckedState empty() {
    AckedState state = new AckedState();
    state.collectionLogItems = new LinkedHashSet<>();
    state.collectionLogAcked = -1;
    state.lastSyncedAt = new LinkedHashMap<>();
    return state;
  }

  public String getDiaryTaskVars() {
    return diaryTaskVars;
  }

  public void setDiaryTaskVars(String diaryTaskVars) {
    this.diaryTaskVars = diaryTaskVars;
  }

  public String getSkills() {
    return skills;
  }

  public void setSkills(String skills) {
    this.skills = skills;
  }

  public String getQuests() {
    return quests;
  }

  public void setQuests(String quests) {
    this.quests = quests;
  }

  public String getDiaries() {
    return diaries;
  }

  public void setDiaries(String diaries) {
    this.diaries = diaries;
  }

  public String getCombatAchievements() {
    return combatAchievements;
  }

  public void setCombatAchievements(String combatAchievements) {
    this.combatAchievements = combatAchievements;
  }

  public String getAccountType() {
    return accountType;
  }

  public void setAccountType(String accountType) {
    this.accountType = accountType;
  }

  // Never null, even if the stored file omits the field.
  public Set<Integer> getCollectionLogItems() {
    if (collectionLogItems == null) {
      collectionLogItems = new LinkedHashSet<>();
    }
    return collectionLogItems;
  }

  public void setCollectionLogItems(Set<Integer> items) {
    this.collectionLogItems = new LinkedHashSet<>(items);
  }

  /** The observed count the server last acknowledged, or -1 for none. */
  public int getCollectionLogAcked() {
    return collectionLogAcked;
  }

  public void setCollectionLogAcked(int acked) {
    this.collectionLogAcked = acked;
  }

  // Never null, even if the stored file omits the field.
  public Map<String, Long> getLastSyncedAt() {
    if (lastSyncedAt == null) {
      lastSyncedAt = new LinkedHashMap<>();
    }
    return lastSyncedAt;
  }

  public void setLastSyncedAt(Map<String, Long> lastSyncedAt) {
    this.lastSyncedAt = new LinkedHashMap<>(lastSyncedAt);
  }
}

package com.bankstand;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Persists what the server acknowledged, per character, in a local file (not {@code
 * ConfigManager}, which syncs to RuneLite's servers). A read failure means "nothing known", which
 * re-sends everything once. Background executor only.
 */
public class AckedStateStore {

  private static class Document {
    Map<String, AckedState> accounts;
  }

  private final File file;
  // Whether the last read hit a file it could not read, as opposed to no file at all.
  private volatile boolean lastReadFailed;
  // While the file cannot be read, saves wait here: writing would erase every other character.
  private final Map<String, AckedState> held = new LinkedHashMap<>();
  private boolean forgetHeld;
  private final Gson gson;

  public AckedStateStore(File file, Gson gson) {
    this.file = file;
    this.gson = gson;
  }

  /** Never null. */
  public synchronized AckedState load(long accountHash) {
    Document document = document();
    AckedState stored =
        document == null
            ? held.get(Long.toString(accountHash))
            : document.accounts.get(Long.toString(accountHash));
    if (stored == null) {
      return AckedState.empty();
    }
    // A copy, so a caller's mutation cannot leak into the next read.
    AckedState copy = AckedState.empty();
    copy.setSkills(stored.getSkills());
    copy.setQuests(stored.getQuests());
    copy.setDiaries(stored.getDiaries());
    copy.setAccountType(stored.getAccountType());
    copy.setDiaryTaskVars(stored.getDiaryTaskVars());
    copy.setDiaryFloor(
        stored.getDiaryFlags(), stored.getDiaryCounts(), stored.getDiaryTaskVarValues());
    copy.setCombatAchievements(stored.getCombatAchievements());
    copy.setCollectionLogItems(stored.getCollectionLogItems());
    copy.setCollectionLogAcked(stored.getCollectionLogAcked());
    copy.setLastSyncedAt(stored.getLastSyncedAt());
    return copy;
  }

  /** Leaves every other character's state untouched. */
  public synchronized void save(long accountHash, AckedState state) {
    Document document = document();
    if (document == null) {
      held.put(Long.toString(accountHash), state);
      return;
    }
    document.accounts.put(Long.toString(accountHash), state);
    write(document);
  }

  /** For a new pairing, which may be another account or server: keeps the browsed log, not acks. */
  public synchronized void forgetAcks() {
    Document document = document();
    if (document == null) {
      forget(held);
      forgetHeld = true;
      return;
    }
    forget(document.accounts);
    write(document);
  }

  private static void forget(Map<String, AckedState> accounts) {
    for (Map.Entry<String, AckedState> entry : accounts.entrySet()) {
      AckedState kept = AckedState.empty();
      kept.setCollectionLogItems(entry.getValue().getCollectionLogItems());
      entry.setValue(kept);
    }
  }

  /** The file with anything held merged in, or null while it cannot be read. */
  private Document document() {
    Document document = read();
    if (document == null || (held.isEmpty() && !forgetHeld)) {
      return document;
    }
    if (forgetHeld) {
      forget(document.accounts);
    }
    document.accounts.putAll(held);
    // Cleared by write() on success, so a failed write cannot lose them.
    write(document);
    return document;
  }

  /** One read's state and whether that read failed, taken under one lock. */
  static final class Loaded {
    final AckedState state;
    final boolean failed;

    Loaded(AckedState state, boolean failed) {
      this.state = state;
      this.failed = failed;
    }
  }

  synchronized Loaded loadChecked(long accountHash) {
    AckedState state = load(accountHash);
    return new Loaded(state, lastReadFailed);
  }

  private Document read() {
    Document document = null;
    lastReadFailed = false;
    if (file.exists()) {
      try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
        document = gson.fromJson(reader, Document.class);
      } catch (IOException | RuntimeException e) {
        // Maybe passing: never treated as empty, or a save would erase every other character.
        if (!ReadFailures.isDamaged(e)) {
          lastReadFailed = true;
          return null;
        }
        // Damaged for good: kept aside, and read as "nothing known", so the next save replaces it.
        document = null;
        try {
          Files.move(
              file.toPath(),
              file.toPath().resolveSibling(file.getName() + ".unreadable"),
              StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException | RuntimeException moveFailure) {
          // The next save replaces it anyway.
        }
      }
    }
    if (document == null) {
      document = new Document();
    }
    if (document.accounts == null) {
      document.accounts = new HashMap<>();
    }
    return document;
  }

  private void write(Document document) {
    Path target = file.toPath();
    Path directory = target.getParent();
    try {
      if (directory != null) {
        Files.createDirectories(directory);
      }
      // Temp then move, so a crash midway leaves the previous document intact.
      Path temp = Files.createTempFile(directory, "acked", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(document, writer);
      }
      try {
        Files.move(
            temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
      // Every write carries what was held, merged in by document().
      held.clear();
      forgetHeld = false;
    } catch (IOException | RuntimeException e) {
      // A failed save costs one resend next start.
    }
  }
}

package com.bankstand;

import com.bankstand.dto.PairResponse;
import com.bankstand.dto.PresenceResponse;
import com.bankstand.dto.SubmitLootResponse;
import com.bankstand.dto.SubmitEventsResponse;
import com.bankstand.dto.SubmitResponse;
import com.bankstand.dto.SubmitSnapshotResponse;
import com.bankstand.http.HttpResponse;
import com.bankstand.http.HttpTransport;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.function.BiPredicate;
import java.util.function.Supplier;

/**
 * HTTP client for the Bankstand plugin API. Pairing failures collapse into one generic
 * {@link PairingException} and are never retried. Never log the device token or account hash.
 */
public class BankstandClient {

  private static final String PAIR_PATH = "/api/plugin/v1/pair";
  private static final String SUBMIT_PATH = "/api/plugin/v1/submit";
  private static final String EVENTS_PATH = "/api/plugin/v1/events";
  private static final String MANIFEST_PATH = "/api/plugin/v1/manifest";
  private static final String PRESENCE_PATH = "/api/plugin/v1/presence";
  private static final String LOOT_PATH = "/api/plugin/v1/loot";
  private static final String UNPAIR_PATH = "/api/plugin/v1/unpair";
  // Disconnect never waits on the server, so a slow one only delays the "could not reach" notice.
  private static final long UNPAIR_TIMEOUT_MILLIS = 5_000L;
  private static final String USER_AGENT = "bankstand-runelite/" + PluginVersion.VERSION;
  private static final String GENERIC_FAILURE = "Pairing failed. Check the code and try again.";
  // Redirects are never followed, so the token and body never reach a host they were not sent to.
  static final String REDIRECTED = "The server redirected the request, so it was not sent. Check the Server URL.";

  // The pause for a 429 without a Retry-After.
  static final long DEFAULT_RETRY_AFTER_MILLIS = 60_000L;

  private final HttpTransport transport;
  private final Gson gson;
  // Keeps explicit nulls: the server rejects a body missing a nullable field.
  private final Gson wire;
  private final ScheduledExecutorService executor;
  private final Supplier<Instant> clock;

  /** @param executor schedules retries; never blocked on, so it may be the caller's own. */
  public BankstandClient(HttpTransport transport, Gson gson, ScheduledExecutorService executor) {
    this(transport, gson, executor, Instant::now);
  }

  /** @param clock stamps {@code sentAt} on the requests that carry one; a test fixes it. */
  BankstandClient(
      HttpTransport transport,
      Gson gson,
      ScheduledExecutorService executor,
      Supplier<Instant> clock) {
    this.transport = transport;
    this.gson = gson;
    this.wire = gson.newBuilder().serializeNulls().create();
    this.executor = executor;
    this.clock = clock;
  }

  public PairResponse exchangePairingCode(String baseUrl, String rawCode) throws PairingException {
    String code = PairingCodes.normalize(rawCode);
    if (!PairingCodes.isValid(code)) {
      // Fail locally so a malformed code never burns a rate-limit slot.
      throw new PairingException("Enter the 8-character code shown in Bankstand.");
    }

    String url = trimTrailingSlash(baseUrl) + PAIR_PATH;
    Map<String, String> body = new LinkedHashMap<>();
    body.put("code", code);
    Map<String, String> headers = new LinkedHashMap<>();
    headers.put("Content-Type", "application/json");
    headers.put("Accept", "application/json");
    headers.put("User-Agent", USER_AGENT);

    HttpResponse response;
    try {
      response = transport.post(url, wire.toJson(body), headers);
    } catch (IOException e) {
      throw new PairingException("Could not reach Bankstand. Check your connection and try again.");
    }

    if (response.getStatus() != 200) {
      throw new PairingException(response.getStatus() / 100 == 3 ? REDIRECTED : GENERIC_FAILURE);
    }

    PairResponse parsed;
    try {
      parsed = gson.fromJson(response.getBody(), PairResponse.class);
    } catch (JsonSyntaxException e) {
      throw new PairingException(GENERIC_FAILURE);
    }
    if (parsed == null || isBlank(parsed.getDeviceToken())) {
      throw new PairingException(GENERIC_FAILURE);
    }
    return parsed;
  }

  public SubmitResponse submitIdentity(
      String baseUrl, String deviceToken, long accountHash, String displayName)
      throws SubmitException {
    Map<String, Object> body = new LinkedHashMap<>();
    // Sent as a decimal string: a 64-bit account hash does not fit a JSON number safely.
    body.put("accountHash", Long.toString(accountHash));
    if (!isBlank(displayName)) {
      body.put("displayName", displayName);
    }
    return parse(authorizedPost(baseUrl, SUBMIT_PATH, deviceToken, body), SubmitResponse.class);
  }

  /** Retries network, 429 and 5xx failures with backoff; other failures fail fast. */
  public CompletableFuture<SubmitResponse> submitIdentityWithRetry(
      String baseUrl,
      String deviceToken,
      long accountHash,
      String displayName,
      int maxAttempts,
      long baseDelayMillis) {
    return withRetry(
        baseUrl,
        deviceToken,
        () -> submitIdentity(baseUrl, deviceToken, accountHash, displayName),
        maxAttempts,
        baseDelayMillis);
  }

  public SubmitSnapshotResponse submitSnapshot(
      String baseUrl, String deviceToken, Map<String, Object> envelopeBody)
      throws SubmitException {
    return parse(
        authorizedPost(baseUrl, SUBMIT_PATH, deviceToken, envelopeBody),
        SubmitSnapshotResponse.class);
  }

  public CompletableFuture<SubmitSnapshotResponse> submitSnapshotWithRetry(
      String baseUrl,
      String deviceToken,
      Map<String, Object> envelopeBody,
      int maxAttempts,
      long baseDelayMillis) {
    return withRetry(
        baseUrl,
        deviceToken,
        () -> submitSnapshot(baseUrl, deviceToken, envelopeBody),
        maxAttempts,
        baseDelayMillis);
  }

  /** Wire field names are a server contract; do not rename them. */
  public SubmitEventsResponse submitEvents(
      String baseUrl, String deviceToken, long accountHash, List<TransientEvent> events)
      throws SubmitException {
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("accountHash", Long.toString(accountHash));
    List<Map<String, Object>> wireEvents = new ArrayList<>(events.size());
    for (TransientEvent event : events) {
      Map<String, Object> wire = new LinkedHashMap<>();
      wire.put("id", event.getId());
      wire.put("type", event.getType());
      wire.put("occurredAt", event.getOccurredAt());
      wire.put("payload", event.getPayload());
      wireEvents.add(wire);
    }
    body.put("events", wireEvents);
    // Stamped per attempt so the server can correct for this machine's clock.
    body.put("sentAt", clock.get().toString());
    return parse(authorizedPost(baseUrl, EVENTS_PATH, deviceToken, body), SubmitEventsResponse.class);
  }

  public CompletableFuture<SubmitEventsResponse> submitEventsWithRetry(
      String baseUrl,
      String deviceToken,
      long accountHash,
      List<TransientEvent> events,
      int maxAttempts,
      long baseDelayMillis) {
    return withRetry(
        baseUrl,
        deviceToken,
        () -> submitEvents(baseUrl, deviceToken, accountHash, events),
        maxAttempts,
        baseDelayMillis);
  }

  /**
   * Sends one presence signal, single attempt. {@code elapsedMs} is how long it waited in
   * memory. {@code loot} says whether full loot is on; null leaves it out.
   */
  public PresenceResponse submitPresence(
      String baseUrl,
      String deviceToken,
      long accountHash,
      String state,
      long elapsedMs,
      Boolean loot)
      throws SubmitException {
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("accountHash", Long.toString(accountHash));
    body.put("state", state);
    body.put("elapsedMs", elapsedMs);
    if (loot != null) {
      body.put("loot", loot);
    }
    HttpResponse response = authorizedPost(baseUrl, PRESENCE_PATH, deviceToken, body);
    return parse(response, PresenceResponse.class);
  }

  /** Sends one account's loot records, single attempt; a 429 carries its Retry-After. */
  public SubmitLootResponse submitLoot(
      String baseUrl, String deviceToken, long accountHash, List<LootEvent> events)
      throws SubmitException {
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("accountHash", Long.toString(accountHash));
    body.put("sentAt", clock.get().toString());
    body.put("events", new ArrayList<>(events));
    HttpResponse response = authorizedPost(baseUrl, LOOT_PATH, deviceToken, body);
    return parse(response, SubmitLootResponse.class);
  }

  private HttpResponse authorizedPost(
      String baseUrl, String path, String deviceToken, Map<String, Object> body)
      throws SubmitException {
    if (isBlank(deviceToken)) {
      throw new SubmitException("Not paired.");
    }
    String url = trimTrailingSlash(baseUrl) + path;
    Map<String, String> headers = new LinkedHashMap<>();
    headers.put("Content-Type", "application/json");
    headers.put("Accept", "application/json");
    headers.put("User-Agent", USER_AGENT);
    headers.put("Authorization", "Bearer " + deviceToken);

    HttpResponse response;
    try {
      response = transport.post(url, wire.toJson(body), headers);
    } catch (IOException e) {
      throw new SubmitException("Could not reach Bankstand.", true);
    }
    int status = response.getStatus();
    if (status == 200) {
      return response;
    }
    if (status == 401 || status == 403) {
      throw new SubmitException(
          "Bankstand rejected the device token. Pair again with a new code from bankstand.gg/account/connection.", false, true);
    }
    if (status == 429) {
      throw new SubmitException(
          "Bankstand is busy.", true, false, retryAfterMillis(response.getRetryAfter()));
    }
    if (status >= 500) {
      throw new SubmitException("Bankstand is busy.", true);
    }
    throw new SubmitException(status / 100 == 3 ? REDIRECTED : "Bankstand rejected the update.", false);
  }

  /**
   * Revokes this device on the server, single attempt. True when the server confirms the token
   * is gone: 204, or 401 for a token it already does not know. False when it could not say.
   */
  public boolean unpair(String baseUrl, String deviceToken) {
    if (isBlank(deviceToken)) {
      return true;
    }
    Map<String, String> headers = new LinkedHashMap<>();
    headers.put("Accept", "application/json");
    headers.put("User-Agent", USER_AGENT);
    headers.put("Authorization", "Bearer " + deviceToken);
    try {
      String url = trimTrailingSlash(baseUrl) + UNPAIR_PATH;
      int status = transport.post(url, "", headers, UNPAIR_TIMEOUT_MILLIS).getStatus();
      // 401 and 403: the token is already dead, which is what a revoke wants.
      return status == 204 || status == 401 || status == 403;
    } catch (IOException e) {
      return false;
    }
  }

  /** {@link #unpair} on the executor; runs {@code onUnreachable} when the server could not say. */
  private volatile boolean closed;
  private volatile BiPredicate<String, String> current = (url, token) -> true;

  /** On plugin shutdown: a retry that is still scheduled fails instead of dispatching. */
  public void close() {
    closed = true;
  }

  public void unpairInBackground(String baseUrl, String deviceToken, Runnable onUnreachable) {
    executor.submit(
        () -> {
          if (!unpair(baseUrl, deviceToken)) {
            onUnreachable.run();
          }
        });
  }

  private <T> T parse(HttpResponse response, Class<T> type) throws SubmitException {
    try {
      T parsed = gson.fromJson(response.getBody(), type);
      if (parsed == null) {
        throw new SubmitException("Unexpected response from Bankstand.");
      }
      return parsed;
    } catch (JsonSyntaxException e) {
      throw new SubmitException("Unexpected response from Bankstand.");
    }
  }

  /** A {@code Retry-After} in seconds as millis, capped at an hour, else the default. */
  static long retryAfterMillis(String header) {
    if (header == null) {
      return DEFAULT_RETRY_AFTER_MILLIS;
    }
    try {
      long seconds = Long.parseLong(header.trim());
      if (seconds <= 0) {
        return DEFAULT_RETRY_AFTER_MILLIS;
      }
      return Math.min(seconds, 3600L) * 1000L;
    } catch (NumberFormatException e) {
      return DEFAULT_RETRY_AFTER_MILLIS;
    }
  }

  private interface SubmitCall<T> {
    T call() throws SubmitException;
  }

  static final long MAX_BACKOFF_MILLIS = 8_000L;

  /**
   * Full jitter over a doubling window, so clients that failed together do not retry
   * together. The randomness is a parameter so the backoff is testable.
   *
   * @param randomFraction a value in {@code [0, 1)}
   */
  static long backoffMillis(int attempt, long baseDelayMillis, double randomFraction) {
    long window = Math.min(MAX_BACKOFF_MILLIS, baseDelayMillis << (attempt - 1));
    return (long) (window * randomFraction);
  }

  /** Checked before every attempt, retries included, so a replaced token is never sent. */
  public void setCurrentPairing(BiPredicate<String, String> current) {
    this.current = current;
  }

  // Retries are scheduled on the executor, never slept (Plugin Hub rejects Thread.sleep).
  // The first attempt runs on the calling thread, which must not be the client thread.
  private <T> CompletableFuture<T> withRetry(
      String baseUrl, String deviceToken, SubmitCall<T> call, int maxAttempts, long baseDelayMillis) {
    SubmitCall<T> guarded =
        () -> {
          if (!current.test(baseUrl, deviceToken)) {
            throw new SubmitException("Pairing changed.");
          }
          return call.call();
        };
    CompletableFuture<T> result = new CompletableFuture<>();
    attempt(guarded, 1, maxAttempts, baseDelayMillis, result);
    return result;
  }

  private <T> void attempt(
      SubmitCall<T> call,
      int attemptNumber,
      int maxAttempts,
      long baseDelayMillis,
      CompletableFuture<T> result) {
    if (closed) {
      result.completeExceptionally(new SubmitException("Stopped."));
      return;
    }
    try {
      result.complete(call.call());
    } catch (SubmitException e) {
      // A Retry-After is the server asking for quiet, so it is never retried here.
      if (!e.isRetryable() || e.getRetryAfterMillis() > 0 || attemptNumber == maxAttempts) {
        result.completeExceptionally(e);
        return;
      }
      long delay =
          backoffMillis(attemptNumber, baseDelayMillis, ThreadLocalRandom.current().nextDouble());
      executor.schedule(
          () -> attempt(call, attemptNumber + 1, maxAttempts, baseDelayMillis, result),
          delay,
          TimeUnit.MILLISECONDS);
    } catch (RuntimeException e) {
      // A scheduled retry has no caller to throw to; left open, the future would never finish.
      result.completeExceptionally(new SubmitException("Unexpected error."));
    }
  }

  private static boolean isBlank(String value) {
    return value == null || value.trim().isEmpty();
  }

  /**
   * Returns null on any failure, never throws: a manifest outage must not break a paired
   * client, which falls back to its last good copy. Unauthenticated, since it may be needed
   * before pairing.
   */
  public CapabilityManifest.RawManifest fetchManifest(String baseUrl) {
    Map<String, String> headers = new LinkedHashMap<>();
    headers.put("Accept", "application/json");
    headers.put("User-Agent", USER_AGENT);
    try {
      HttpResponse response = transport.get(trimTrailingSlash(baseUrl) + MANIFEST_PATH, headers);
      if (response.getStatus() != 200) {
        return null;
      }
      return gson.fromJson(response.getBody(), CapabilityManifest.RawManifest.class);
    } catch (IOException | JsonSyntaxException e) {
      return null;
    }
  }

  private static String trimTrailingSlash(String url) {
    String trimmed = url == null ? "" : url.trim();
    while (trimmed.endsWith("/")) {
      trimmed = trimmed.substring(0, trimmed.length() - 1);
    }
    return trimmed;
  }
}

