package com.bankstand;

import java.util.Locale;
import okhttp3.HttpUrl;

/**
 * Storage keys and defaults. Config keys must match {@link BankstandConfig}, since the plugin
 * also writes some back through {@code ConfigManager}.
 *
 * <p>Device credentials are never config items: {@link DeviceCredentialStore} keeps them in a
 * local file under {@code RUNELITE_DIR}, unencrypted (a key would live on the same machine).
 * Never log the token.
 */
public final class BankstandKeys {
  private BankstandKeys() {}

  public static final String GROUP = "bankstand";

  /**
   * The chat command. Never start it with "bank": the game matches its own {@code ::bank} on
   * the prefix and posts a message in public chat.
   */
  public static final String COMMAND = "bstand";

  public static final String COMMAND_ALIAS = "stand";

  // Never rename: an existing pairing depends on these keys.
  public static final String KEY_SERVER_URL = "serverBaseUrl";
  public static final String KEY_PAIRING_CODE = "pairingCode";
  public static final String KEY_DISCONNECT = "disconnect";

  // "collect", not "share": the client decides what is read; the website decides who sees it.
  public static final String KEY_COLLECT_SKILLS = "collectSkills";
  public static final String KEY_COLLECT_QUESTS = "collectQuests";
  public static final String KEY_COLLECT_DIARIES = "collectDiaries";
  public static final String KEY_COLLECT_COLLECTION_LOG = "collectCollectionLog";
  public static final String KEY_COLLECT_COMBAT_ACHIEVEMENTS = "collectCombatAchievements";
  public static final String KEY_COLLECT_ACCOUNT_TYPE = "collectAccountType";

  public static final String KEY_COLLECT_NOTABLE_DROPS = "collectNotableDrops";
  public static final String KEY_NOTABLE_DROP_THRESHOLD = "notableDropThreshold";
  public static final String KEY_COLLECT_PET_DROPS = "collectPetDrops";

  // Live sessions: three separate toggles, none turns another on.
  public static final String KEY_COLLECT_SESSIONS = "collectSessions";
  public static final String KEY_COLLECT_LOOT = "collectLoot";
  public static final String KEY_COLLECT_SLAYER = "collectSlayer";

  // Credentials, never surfaced as config items.
  public static final String KEY_DEVICE_TOKEN = "deviceToken";
  public static final String KEY_DEVICE_ID = "deviceId";
  public static final String KEY_TOKEN_EXPIRES_AT = "tokenExpiresAt";

  /** Changing this reaches new installs only; a paired client keeps its stored URL. */
  public static final String DEFAULT_SERVER_URL = "https://bankstand.gg";

  /**
   * Trimmed, or the default when unset, blank or unusable. Every caller must use this. Plain http
   * is allowed only for localhost; any other http address is upgraded to https so the token is
   * never sent in the clear.
   */
  public static String normaliseServerUrl(String raw) {
    if (raw == null || raw.trim().isEmpty()) {
      return DEFAULT_SERVER_URL;
    }
    String url = raw.trim();
    String lower = url.toLowerCase(Locale.ROOT);
    if (lower.startsWith("https://")) {
      return url;
    }
    if (!lower.startsWith("http://")) {
      return DEFAULT_SERVER_URL;
    }
    // OkHttp picks the host, so text around an "@" cannot pass for localhost.
    HttpUrl parsed = HttpUrl.parse(url);
    boolean local = parsed != null && isLocalhost(parsed.host());
    return local ? url : "https://" + url.substring("http://".length());
  }

  /**
   * "scheme://host:port" of a URL, or null if unusable. Parsed by OkHttp, the same parser that
   * picks the host a request actually goes to.
   */
  public static String originOf(String url) {
    HttpUrl parsed = url == null ? null : HttpUrl.parse(url.trim());
    return parsed == null ? null : parsed.scheme() + "://" + parsed.host() + ":" + parsed.port();
  }

  private static boolean isLocalhost(String host) {
    return host.equals("localhost") || host.equals("127.0.0.1") || host.equals("::1");
  }
}

package com.bankstand;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel showing sync status. Renders only from a {@link PanelModel} snapshot and
 * holds no reference to the plugin or client.
 */
class BankstandPanel extends PluginPanel {

  private final Runnable onSyncNow;
  private final Runnable onOpenBankstand;
  private final Runnable onRequestRefresh;
  private final Runnable onTurnOnSessions;

  BankstandPanel(
      Runnable onSyncNow,
      Runnable onOpenBankstand,
      Runnable onRequestRefresh,
      Runnable onTurnOnSessions) {
    super();
    this.onSyncNow = onSyncNow;
    this.onOpenBankstand = onOpenBankstand;
    this.onRequestRefresh = onRequestRefresh;
    this.onTurnOnSessions = onTurnOnSessions;
    render(PanelModel.empty(""));
  }

  @Override
  public void onActivate() {
    onRequestRefresh.run();
  }

  /** Must be called on the Swing event dispatch thread. */
  void render(PanelModel model) {
    removeAll();

    add(buildHeader(model));
    add(buildCapabilityList(model));
    if (model.offerSessions) {
      add(buildSessionsPrompt());
    }
    add(buildRecentActivity(model));
    add(buildActions(model));

    revalidate();
    repaint();
  }

  private JPanel buildHeader(PanelModel model) {
    JPanel header = new JPanel();
    header.setLayout(new javax.swing.BoxLayout(header, javax.swing.BoxLayout.Y_AXIS));
    header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    header.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    JComponent dot = statusDot(dotColor(model.dot), dotTooltip(model));

    JLabel title = new JLabel(headerText(model));
    title.setFont(FontManager.getRunescapeBoldFont());
    title.setForeground(Color.WHITE);

    JPanel titleRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
    titleRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    titleRow.add(dot);
    titleRow.add(title);
    header.add(leftAligned(titleRow));

    // A stale server address otherwise fails every sync silently.
    if (model.paired) {
      JLabel serverLine = new JLabel("Paired with " + model.serverUrl);
      serverLine.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
      serverLine.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
      header.add(leftAligned(serverLine));
    }

    return header;
  }

  private static String headerText(PanelModel model) {
    if (!model.paired) {
      return "Bankstand: not paired";
    }
    return model.linkedName == null ? "Bankstand" : "Bankstand: " + model.linkedName;
  }

  private static String dotTooltip(PanelModel model) {
    switch (model.dot) {
      case GREEN:
        return "Paired, last sync succeeded";
      case AMBER:
        return "Paired, the last sync attempt failed";
      case GREY:
      default:
        return model.paired ? "Paired, nothing has synced yet" : "Not paired";
    }
  }

  private static Color dotColor(PanelPresentation.SyncDot dot) {
    switch (dot) {
      case GREEN:
        return ColorScheme.PROGRESS_COMPLETE_COLOR;
      case AMBER:
        return Color.ORANGE;
      case GREY:
      default:
        // MEDIUM_GRAY_COLOR is under WCAG's 3:1 contrast on this background.
        return ColorScheme.LIGHT_GRAY_COLOR;
    }
  }

  // Painted rather than a Unicode glyph, which some client fonts render as nothing.
  private static JComponent statusDot(Color color, String tooltip) {
    JComponent dot =
        new JComponent() {
          @Override
          protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(color);
            g2.fillOval(0, 3, 9, 9);
            g2.dispose();
          }
        };
    dot.setOpaque(false);
    dot.setPreferredSize(new Dimension(11, 16));
    dot.setToolTipText(tooltip);
    return dot;
  }

  private JPanel buildCapabilityList(PanelModel model) {
    JPanel section = new JPanel();
    section.setLayout(new javax.swing.BoxLayout(section, javax.swing.BoxLayout.Y_AXIS));
    section.setBackground(ColorScheme.DARK_GRAY_COLOR);
    section.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    section.add(leftAligned(sectionTitle("Capabilities")));

    if (model.capabilities.isEmpty()) {
      section.add(leftAligned(mutedLabel("Nothing switched on")));
    } else {
      long now = System.currentTimeMillis();
      for (PanelModel.CapabilityRow row : model.capabilities) {
        section.add(buildCapabilityRow(row, now));
      }
    }
    return section;
  }

  private JPanel buildCapabilityRow(PanelModel.CapabilityRow row, long now) {
    JPanel line = new JPanel(new BorderLayout());
    line.setBackground(ColorScheme.DARK_GRAY_COLOR);
    line.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));

    JLabel name = new JLabel(row.name);
    name.setForeground(Color.WHITE);

    JLabel synced = new JLabel(PanelPresentation.capabilityStatus(row, now));
    synced.setToolTipText(PanelPresentation.capabilityTooltip(row));
    synced.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
    synced.setHorizontalAlignment(SwingConstants.RIGHT);

    line.add(name, BorderLayout.WEST);
    line.add(synced, BorderLayout.EAST);
    return line;
  }

  /** One line and a button; ignoring it leaves sessions off. */
  private JPanel buildSessionsPrompt() {
    JPanel section = new JPanel();
    section.setLayout(new javax.swing.BoxLayout(section, javax.swing.BoxLayout.Y_AXIS));
    section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    section.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    JLabel question = new JLabel("Also turn on the Session log?");
    question.setForeground(Color.WHITE);
    section.add(leftAligned(question));

    JButton turnOn = new JButton("Turn on");
    turnOn.setFocusable(false);
    turnOn.addActionListener(e -> onTurnOnSessions.run());
    JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 4));
    row.setOpaque(false);
    row.add(turnOn);
    section.add(leftAligned(row));
    return section;
  }

  private JPanel buildRecentActivity(PanelModel model) {
    JPanel section = new JPanel();
    section.setLayout(new javax.swing.BoxLayout(section, javax.swing.BoxLayout.Y_AXIS));
    section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    section.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    section.add(leftAligned(sectionTitle("Recent activity")));

    List<PanelModel.ActivityRow> recent = model.recentActivity;
    if (recent.isEmpty()) {
      section.add(leftAligned(mutedLabel("Nothing sent yet this session")));
    } else {
      long now = System.currentTimeMillis();
      for (PanelModel.ActivityRow row : recent) {
        JLabel label =
            new JLabel(row.description + " (" + PanelPresentation.formatAge(now - row.atMs) + ")");
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
        section.add(leftAligned(label));
      }
    }
    return section;
  }

  private JPanel buildActions(PanelModel model) {
    JPanel section = new JPanel();
    section.setLayout(new javax.swing.BoxLayout(section, javax.swing.BoxLayout.Y_AXIS));
    section.setBackground(ColorScheme.DARK_GRAY_COLOR);
    section.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    JButton syncButton = new JButton("Sync now");
    syncButton.setFocusable(false);
    syncButton.addActionListener(e -> onSyncNow.run());

    JButton openButton = new JButton("Open Bankstand");
    openButton.setFocusable(false);
    openButton.addActionListener(e -> onOpenBankstand.run());

    JPanel buttons = new JPanel();
    buttons.setLayout(new javax.swing.BoxLayout(buttons, javax.swing.BoxLayout.Y_AXIS));
    buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
    buttons.add(syncButton);
    buttons.add(javax.swing.Box.createVerticalStrut(4));
    buttons.add(openButton);
    section.add(leftAligned(buttons));

    if (model.lastFailureReason != null) {
      JLabel failure = new JLabel("<html>" + escapeHtml(model.lastFailureReason) + "</html>");
      failure.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
      failure.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
      section.add(leftAligned(failure));
    }

    return section;
  }

  private static JLabel sectionTitle(String text) {
    JLabel label = new JLabel(text);
    label.setFont(FontManager.getRunescapeBoldFont());
    label.setForeground(Color.WHITE);
    label.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
    return label;
  }

  private static JLabel mutedLabel(String text) {
    JLabel label = new JLabel(text);
    label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
    return label;
  }

  // BorderLayout.WEST: BoxLayout alignmentX did not reliably left-align on a real client.
  private static JPanel leftAligned(JComponent inner) {
    JPanel wrapper = new JPanel(new BorderLayout());
    wrapper.setOpaque(false);
    wrapper.add(inner, BorderLayout.WEST);
    return wrapper;
  }

  // The failure text reaches an html-rendering JLabel, so escape markup characters.
  private static String escapeHtml(String text) {
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
  }
}

