package com.bankstand;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

/**
 * Stores the pairing credentials in a local file, never {@code ConfigManager}: a synced profile
 * uploads all config to RuneLite's servers, and the token is a bearer credential. Per-install
 * storage also keeps each machine its own device.
 *
 * <p>A read failure means "not paired" (fail closed) and is never cached. Called from the client
 * thread and the executor: {@link #cached} is volatile, and each read returns its own result.
 */
public class DeviceCredentialStore {

  private final File file;
  private final Gson gson;

  // Read on nearly every game event, so cached. Null means "not loaded yet", not "not paired".
  private volatile DeviceCredentials cached;

  public DeviceCredentialStore(File file, Gson gson) {
    this.file = file;
    this.gson = gson;
  }

  /** One read: the credentials, and whether the file could not be read ("not paired" is a guess). */
  public static final class Read {
    public final DeviceCredentials credentials;
    public final boolean unreadable;

    Read(DeviceCredentials credentials, boolean unreadable) {
      this.credentials = credentials;
      this.unreadable = unreadable;
    }
  }

  /** Never null. */
  public DeviceCredentials load() {
    return read().credentials;
  }

  public Read read() {
    DeviceCredentials current = cached;
    if (current != null) {
      return new Read(current, false);
    }
    Read read = readFromDisk();
    if (!read.unreadable) {
      cached = read.credentials;
    }
    return read;
  }

  private Read readFromDisk() {
    if (!file.exists()) {
      return new Read(DeviceCredentials.none(), false);
    }
    try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
      DeviceCredentials stored = gson.fromJson(reader, DeviceCredentials.class);
      return new Read(stored == null ? DeviceCredentials.none() : stored, false);
    } catch (IOException | RuntimeException e) {
      // Not logged, at any level: this file holds a credential.
      return new Read(DeviceCredentials.none(), true);
    }
  }

  /** False when the file could not be written; the cache then keeps the previous pairing. */
  public boolean save(DeviceCredentials credentials) {
    Path target = file.toPath();
    Path directory = target.getParent();
    Path temp = null;
    try {
      if (directory != null) {
        Files.createDirectories(directory);
      }
      // Temp then move, so a crash midway leaves the previous pairing intact.
      temp = Files.createTempFile(directory, "device", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(credentials, writer);
      }
      try {
        Files.move(
            temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
      // Only on success, so the cache always matches disk.
      cached = credentials;
      return true;
    } catch (IOException | RuntimeException e) {
      // The temp file holds the token; unpair only deletes the real file.
      if (temp != null) {
        try {
          Files.deleteIfExists(temp);
        } catch (IOException | RuntimeException ignored) {
          // Nothing more to do; the save already reports failure.
        }
      }
      // Not logged: the message can carry the path, and the caller reports the outcome.
      return false;
    }
  }

  /**
   * Unpairs this process at once, whatever the disk does. False when the file could not be
   * removed or emptied, so the pairing comes back on the next start.
   */
  public boolean clear() {
    cached = DeviceCredentials.none();
    try {
      Files.deleteIfExists(file.toPath());
      return true;
    } catch (IOException | RuntimeException e) {
      // If the delete fails, overwrite with an empty document so no credential remains.
      boolean emptied = save(DeviceCredentials.none());
      cached = DeviceCredentials.none();
      return emptied;
    }
  }
}

package com.bankstand;

import com.bankstand.dto.PairResponse;
import lombok.Data;
import lombok.ToString;

/**
 * This install's pairing: bearer token, device id, expiry and the server it was paired with. Per
 * install, not per account, since the server treats each token as one device.
 */
@Data
public class DeviceCredentials {

  // Never in toString(), so logging this object cannot leak the token.
  @ToString.Exclude private String token;
  private String deviceId;
  private String expiresAt;
  // Null in a pairing stored before this was recorded; those are taken as the default server.
  private String serverUrl;
  // Made here at pairing and never sent: tags every queued capture with the pairing it belongs to.
  private String pairingId;

  public static DeviceCredentials none() {
    return new DeviceCredentials();
  }

  public static DeviceCredentials of(PairResponse res, String serverUrl) {
    DeviceCredentials credentials = new DeviceCredentials();
    credentials.setToken(res.getDeviceToken());
    credentials.setDeviceId(res.getDeviceId());
    credentials.setExpiresAt(res.getExpiresAt());
    credentials.setServerUrl(serverUrl);
    credentials.setPairingId(java.util.UUID.randomUUID().toString());
    return credentials;
  }

  public boolean isPaired() {
    return token != null && !token.trim().isEmpty();
  }

  public String pairedServerUrl() {
    return serverUrl == null ? BankstandKeys.DEFAULT_SERVER_URL : serverUrl;
  }

  /**
   * The token, but only for the origin it was paired with, so changing the Server URL never
   * sends it to another host. Null when unpaired or when the origins differ.
   */
  public String tokenFor(String serverUrl) {
    String origin = BankstandKeys.originOf(serverUrl);
    boolean same = origin != null && origin.equals(BankstandKeys.originOf(pairedServerUrl()));
    return isPaired() && same ? token : null;
  }
}

package com.bankstand;

import java.util.Map;

/**
 * Change gate: the digest of the last diary-state vector the server acknowledged. Advances only on
 * an ack, so a dropped submit is retried. Also keeps the acked values themselves: diary progress
 * never goes back, so a read below them is one the game has not finished sending.
 */
public class DiaryBaseline {
  /** About two minutes. A login's values arrive well within it; a lower read after it is real. */
  static final int HOLD_TICKS = 200;

  private String acked;
  private Map<String, String> flags;
  private Map<String, Integer> counts;
  private Map<String, Map<String, Integer>> vars;

  public boolean changedSince(Map<String, String> current) {
    return !CapabilityDigest.of(current).equals(acked);
  }

  /** Counts too, so a tier's count rising without its flag still resends. Unknown counts never do. */
  public boolean changedSince(Map<String, String> current, Map<String, Integer> currentCounts) {
    return changedSince(current)
        || (currentCounts != null && counts != null && !currentCounts.equals(counts));
  }

  public void advance(Map<String, String> ackedNow) {
    advance(ackedNow, null);
  }

  public void advance(Map<String, String> ackedFlags, Map<String, Integer> ackedCounts) {
    acked = CapabilityDigest.of(ackedFlags);
    flags = ackedFlags;
    counts = ackedCounts;
  }

  @SuppressWarnings("unchecked")
  public void advanceVars(Map<String, Object> ackedVars) {
    vars = (Map<String, Map<String, Integer>>) (Map<String, ?>) ackedVars;
  }

  /** Null means nothing is known. */
  public void restore(String digest) {
    acked = digest;
  }

  public void restore(AckedState state) {
    restore(state.getDiaries());
    flags = state.getDiaryFlags();
    counts = state.getDiaryCounts();
    vars = state.getDiaryTaskVarValues();
  }

  public void saveTo(AckedState state) {
    state.setDiaries(acked);
    state.setDiaryFloor(flags, counts, vars);
  }

  public String ackedDigest() {
    return acked;
  }

  public void reset() {
    acked = null;
    flags = null;
    counts = null;
    vars = null;
  }

  /** True when no tier is complete and no count is above zero, as before the game sends them. */
  static boolean isAllZero(Map<String, String> flags, Map<String, Integer> counts) {
    return flags != null
        && !flags.containsValue("COMPLETE")
        && (counts == null || counts.values().stream().allMatch(n -> n == 0));
  }

  /**
   * Whether a read soon after login may not have fully arrived: below the acked values, or with
   * nothing acked to compare against (a new pairing or device). A time bound, not a comparison.
   */
  boolean holds(
      int ticksSinceLogin,
      Map<String, String> readFlags,
      Map<String, Integer> readCounts,
      Map<String, Object> readVars) {
    return ticksSinceLogin < HOLD_TICKS
        && (acked == null || isBelowAcked(readFlags, readCounts, readVars));
  }

  /** Whether any part of a read is below what the server took. Unknown parts never are. */
  @SuppressWarnings("unchecked")
  boolean isBelowAcked(
      Map<String, String> readFlags, Map<String, Integer> readCounts, Map<String, Object> readVars) {
    if (readFlags != null && flags != null) {
      for (Map.Entry<String, String> e : flags.entrySet()) {
        if ("COMPLETE".equals(e.getValue()) && !"COMPLETE".equals(readFlags.get(e.getKey()))) {
          return true;
        }
      }
    }
    if (readCounts != null && below(counts, readCounts, false)) {
      return true;
    }
    if (readVars == null || vars == null) {
      return false;
    }
    // Varps are task bitfields, so a lost bit is a regression; varbits are counts and flags.
    return below(vars.get("varps"), (Map<String, Integer>) readVars.get("varps"), true)
        || below(vars.get("varbits"), (Map<String, Integer>) readVars.get("varbits"), false);
  }

  private static boolean below(
      Map<String, Integer> acked, Map<String, Integer> read, boolean bits) {
    if (acked == null || read == null) {
      return false;
    }
    for (Map.Entry<String, Integer> e : acked.entrySet()) {
      int was = e.getValue();
      int now = read.getOrDefault(e.getKey(), was);
      if (bits ? (was & ~now) != 0 : now < was) {
        return true;
      }
    }
    return false;
  }
}

package com.bankstand;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Captures a diary task completion (tier and area) from its per-task chat broadcast. Which task
 * it was is the server's to work out from the raw values the snapshot carries.
 */
public class DiaryTaskCompletionCapture extends BaseCapture {

  private static final Pattern COMPLETION_PATTERN =
      Pattern.compile(
          "^Well done! You have completed an? (\\w+) task in the (.+) area\\. Your Achievement"
              + " Diary has been updated\\.$");

  // Not CombatAchievementVarbits' tiers, which add "master" and "grandmaster".
  private static final Set<String> DIARY_TIERS = Set.of("easy", "medium", "hard", "elite");

  // Matches the server's bound; one oversized event makes the server reject the whole batch.
  private static final int MAX_AREA_NAME_LENGTH = 128;

  public DiaryTaskCompletionCapture(
      EventOutbox outbox, BooleanSupplier enabled, LongSupplier accountHash) {
    this(outbox, enabled, accountHash, null);
  }

  public DiaryTaskCompletionCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
  }

  @Subscribe
  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.GAMEMESSAGE) {
      return;
    }
    handleMessage(Text.removeTags(event.getMessage()));
  }

  void handleMessage(String message) {
    if (!isEnabled()) {
      return;
    }
    Matcher matcher = COMPLETION_PATTERN.matcher(message);
    if (!matcher.matches()) {
      return;
    }
    String tier = matcher.group(1).toLowerCase(Locale.ROOT);
    if (!DIARY_TIERS.contains(tier)) {
      return;
    }
    String area = matcher.group(2).trim();
    if (area.isEmpty() || area.length() > MAX_AREA_NAME_LENGTH) {
      return;
    }
    emit(TransientEvent.TYPE_DIARY_TASK_COMPLETED, payload(tier, area));
  }

  static Map<String, Object> payload(String tier, String area) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("tier", tier);
    payload.put("area", area);
    return payload;
  }
}

