    VarbitID.KANDARIN_EASY_REWARD, VarbitID.KANDARIN_MEDIUM_REWARD,
    VarbitID.KANDARIN_HARD_REWARD, VarbitID.KANDARIN_ELITE_REWARD,
    VarbitID.ATJUN_EASY_REWARD, VarbitID.ATJUN_MED_REWARD,
    VarbitID.ATJUN_HARD_REWARD, VarbitID.KARAMJA_ELITE_REWARD,
    VarbitID.KOUREND_EASY_REWARD, VarbitID.KOUREND_MEDIUM_REWARD,
    VarbitID.KOUREND_HARD_REWARD, VarbitID.KOUREND_ELITE_REWARD,
    VarbitID.LUMBRIDGE_EASY_REWARD, VarbitID.LUMBRIDGE_MEDIUM_REWARD,
    VarbitID.LUMBRIDGE_HARD_REWARD, VarbitID.LUMBRIDGE_ELITE_REWARD,
    VarbitID.MORYTANIA_EASY_REWARD, VarbitID.MORYTANIA_MEDIUM_REWARD,
    VarbitID.MORYTANIA_HARD_REWARD, VarbitID.MORYTANIA_ELITE_REWARD,
    VarbitID.VARROCK_EASY_REWARD, VarbitID.VARROCK_MEDIUM_REWARD,
    VarbitID.VARROCK_HARD_REWARD, VarbitID.VARROCK_ELITE_REWARD,
    VarbitID.WESTERN_EASY_REWARD, VarbitID.WESTERN_MEDIUM_REWARD,
    VarbitID.WESTERN_HARD_REWARD, VarbitID.WESTERN_ELITE_REWARD,
    VarbitID.WILDERNESS_EASY_REWARD, VarbitID.WILDERNESS_MEDIUM_REWARD,
    VarbitID.WILDERNESS_HARD_REWARD, VarbitID.WILDERNESS_ELITE_REWARD,
              }),
              DiaryTaskVarbits.ALL.values().stream().mapToInt(Integer::intValue))
          .toArray();

  /** The wire block, every key read. Sorted, so its digest is stable. Client thread. */
  static Map<String, Object> read(IntUnaryOperator varp, IntUnaryOperator varbit) {
    Map<String, Object> block = new TreeMap<>();
    block.put("varps", values(VARPS, varp));
    block.put("varbits", values(VARBITS, varbit));
    return block;
  }

  /** True when every value reads zero, as it does before the game has sent them. */
  @SuppressWarnings("unchecked")
  static boolean isAllZero(Map<String, Object> block) {
    for (Object part : block.values()) {
      for (Integer value : ((Map<String, Integer>) part).values()) {
        if (value != 0) {
          return false;
        }
      }
    }
    return true;
  }

  private static Map<String, Integer> values(int[] ids, IntUnaryOperator reader) {
    Map<String, Integer> values = new TreeMap<>();
    for (int id : ids) {
      values.put(Integer.toString(id), reader.applyAsInt(id));
    }
    return values;
  }
}

package com.bankstand;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Varbits;

/**
 * Maps each diary tier's wire key to its completion varbit (every task done). Not the
 * {@code *_REWARD} flag, which only tracks whether rewards were claimed.
 *
 * <p>Wire keys are the server's, so KOUREND, LUMBRIDGE and WESTERN become KOUREND_KEBOS,
 * LUMBRIDGE_DRAYNOR and WESTERN_PROVINCES.
 */
public final class DiaryVarbits {
  private DiaryVarbits() {}

  private static final Map<String, Integer> BY_WIRE_KEY = build();

  /** Ordered: wire key (server contract) to varbit id. */
  public static final Map<String, Integer> ALL = Collections.unmodifiableMap(BY_WIRE_KEY);

  private static Map<String, Integer> build() {
    Map<String, Integer> m = new LinkedHashMap<>();
    region(m, "ARDOUGNE", Varbits.DIARY_ARDOUGNE_EASY, Varbits.DIARY_ARDOUGNE_MEDIUM,
        Varbits.DIARY_ARDOUGNE_HARD, Varbits.DIARY_ARDOUGNE_ELITE);
    region(m, "DESERT", Varbits.DIARY_DESERT_EASY, Varbits.DIARY_DESERT_MEDIUM,
        Varbits.DIARY_DESERT_HARD, Varbits.DIARY_DESERT_ELITE);
    region(m, "FALADOR", Varbits.DIARY_FALADOR_EASY, Varbits.DIARY_FALADOR_MEDIUM,
        Varbits.DIARY_FALADOR_HARD, Varbits.DIARY_FALADOR_ELITE);
    region(m, "FREMENNIK", Varbits.DIARY_FREMENNIK_EASY, Varbits.DIARY_FREMENNIK_MEDIUM,
        Varbits.DIARY_FREMENNIK_HARD, Varbits.DIARY_FREMENNIK_ELITE);
    region(m, "KANDARIN", Varbits.DIARY_KANDARIN_EASY, Varbits.DIARY_KANDARIN_MEDIUM,
        Varbits.DIARY_KANDARIN_HARD, Varbits.DIARY_KANDARIN_ELITE);
    region(m, "KOUREND_KEBOS", Varbits.DIARY_KOUREND_EASY, Varbits.DIARY_KOUREND_MEDIUM,
        Varbits.DIARY_KOUREND_HARD, Varbits.DIARY_KOUREND_ELITE);
    region(m, "LUMBRIDGE_DRAYNOR", Varbits.DIARY_LUMBRIDGE_EASY, Varbits.DIARY_LUMBRIDGE_MEDIUM,
        Varbits.DIARY_LUMBRIDGE_HARD, Varbits.DIARY_LUMBRIDGE_ELITE);
    region(m, "MORYTANIA", Varbits.DIARY_MORYTANIA_EASY, Varbits.DIARY_MORYTANIA_MEDIUM,
        Varbits.DIARY_MORYTANIA_HARD, Varbits.DIARY_MORYTANIA_ELITE);
    region(m, "VARROCK", Varbits.DIARY_VARROCK_EASY, Varbits.DIARY_VARROCK_MEDIUM,
        Varbits.DIARY_VARROCK_HARD, Varbits.DIARY_VARROCK_ELITE);
    region(m, "WESTERN_PROVINCES", Varbits.DIARY_WESTERN_EASY, Varbits.DIARY_WESTERN_MEDIUM,
        Varbits.DIARY_WESTERN_HARD, Varbits.DIARY_WESTERN_ELITE);
    region(m, "WILDERNESS", Varbits.DIARY_WILDERNESS_EASY, Varbits.DIARY_WILDERNESS_MEDIUM,
        Varbits.DIARY_WILDERNESS_HARD, Varbits.DIARY_WILDERNESS_ELITE);
    // Karamja's ids sit outside the other regions' block (older diary) but are still
    // completion flags, not task counts.
    region(m, "KARAMJA", Varbits.DIARY_KARAMJA_EASY, Varbits.DIARY_KARAMJA_MEDIUM,
        Varbits.DIARY_KARAMJA_HARD, Varbits.DIARY_KARAMJA_ELITE);
    return m;
  }

  private static void region(
      Map<String, Integer> m, String prefix, int easy, int medium, int hard, int elite) {
    m.put(prefix + "_EASY", easy);
    m.put(prefix + "_MEDIUM", medium);
    m.put(prefix + "_HARD", hard);
    m.put(prefix + "_ELITE", elite);
  }
}

package com.bankstand;

import com.bankstand.dto.EventAck;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Append-only, ordered outbox for {@link TransientEvent}s. Each event is a one-shot fact, so
 * nothing coalesces. Capped at {@link #MAX_PENDING}: overflow drops the OLDEST entry, logged.
 *
 * <p>Stored in a file, not {@code ConfigManager}, because a synced RuneLite profile uploads its
 * whole config and this is captured game data.
 *
 * <p>Synchronized: {@link #add} runs on the client thread while {@link #pending} and
 * {@link #ack} run on the executor, and each is a read-modify-write of the same file.
 */
@Slf4j
public class EventOutbox {

  static final int MAX_PENDING = 200;

  private static final Type LIST_TYPE = new TypeToken<ArrayList<OutboxEntry>>() {}.getType();

  private final File file;
  // Far above a full queue's size, so only a damaged file is ever this large.
  private static final long MAX_FILE_BYTES = 4L * 1024 * 1024;
  // For the status report: counts and states only, never content.
  private volatile boolean setAside;
  private volatile boolean unsaved;
  private volatile int dropped;
  // What should be on disk but is not yet, cleared only by a successful write. Full when built
  // from a successful read; otherwise only what changed while the file could not be read.
  private List<OutboxEntry> unwritten;
  private boolean unwrittenIsFull;
  private volatile boolean readFailing;
  private final Gson gson;
  private volatile Supplier<String> pairing = () -> null;

  public EventOutbox(File file, Gson gson) {
    this.file = file;
    // Keep null payload fields on disk: the server rejects an event missing one.
    this.gson = gson.newBuilder().serializeNulls().create();
  }

  /** Appends one event, evicting the oldest pending entry (logged) if this overflows the cap. */
  public synchronized void add(long accountHash, TransientEvent event) {
    List<OutboxEntry> entries = current();
    entries.add(new OutboxEntry(accountHash, event, pairing.get()));
    while (entries.size() > MAX_PENDING) {
      OutboxEntry dropped = entries.remove(0);
      this.dropped++;
      log.warn(
          "event outbox full ({} pending): dropped oldest entry, type={}",
          MAX_PENDING,
          dropped.getEvent().getType());
    }
    write(entries);
  }

  /** Every pending entry, oldest first. A snapshot: mutating the result does not persist. */
  public synchronized List<OutboxEntry> pending() {
    return current();
  }

  /**
   * Removes the entries whose id is in {@code ids} (stored, or judged permanently undeliverable)
   * and keeps the rest in order.
   */
  public synchronized void ack(Set<String> ids) {
    if (ids.isEmpty()) return;
    List<OutboxEntry> entries = current();
    entries.removeIf(entry -> ids.contains(entry.getEvent().getId()));
    write(entries);
  }

  /**
   * Forgets every pending event. Not called on an account switch: each entry is tagged with its
   * own account, so a relog must not lose it.
   */
  public synchronized void clear() {
    // Nothing is pending, so this is the full list whatever the last read did.
    readFailing = false;
    write(Collections.emptyList());
  }

  /** Where the current pairing id is read; entries tagged with another one are never sent. */
  public void setPairing(Supplier<String> pairing) {
    this.pairing = pairing;
  }

  // Fails closed: if a clear on re-pair could not write, the old pairing's entries still never
  // leave. They are dropped here, and from disk whenever a write succeeds.
  private List<OutboxEntry> current() {
    List<OutboxEntry> entries;
    boolean flush = unwritten != null;
    if (flush && unwrittenIsFull) {
      entries = new ArrayList<>(unwritten);
    } else {
      List<OutboxEntry> fromDisk = read();
      readFailing = fromDisk == null;
      entries = fromDisk == null ? new ArrayList<>() : fromDisk;
      if (flush) {
        entries.addAll(unwritten);
      }
    }
    String now = pairing.get();
    // An unreadable pairing is not "another pairing": nothing is purged until it is known.
    boolean purged =
        !PairingQueues.UNKNOWN.equals(now)
            && entries.removeIf(entry -> !Objects.equals(now, entry.getPairingId()));
    if (purged || flush) {
      write(entries);
    }
    return entries;
  }



  private List<OutboxEntry> read() {
    if (!file.exists()) {
      return new ArrayList<>();
    }
    if (file.length() > MAX_FILE_BYTES) {
      return setAside();
    }
    try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
      List<OutboxEntry> stored = gson.fromJson(reader, LIST_TYPE);
      if (stored == null) {
        return new ArrayList<>();
      }
      // Valid JSON can still lack what every reader of an entry needs.
      for (OutboxEntry entry : stored) {
        if (entry == null || entry.getEvent() == null || entry.getEvent().getId() == null) {
          return setAside();
        }
      }
      return new ArrayList<>(stored);
    } catch (IOException | RuntimeException e) {
      log.debug("event outbox unreadable: {}", e.getMessage());
      // Damaged for good: kept aside. Maybe passing (a lock, a permission): left in place.
      return ReadFailures.isDamaged(e) ? setAside() : null;
    }
  }

  // Moved aside, never overwritten, so a damaged queue can still be inspected or recovered.
  private <T> List<T> setAside() {
    setAside = true;
    try {
      Files.move(
          file.toPath(),
          file.toPath().resolveSibling(file.getName() + ".unreadable"),
          StandardCopyOption.REPLACE_EXISTING);
    } catch (IOException | RuntimeException e) {
      log.debug("event outbox could not be set aside: {}", e.getMessage());
    }
    return new ArrayList<>();
  }

  /** What is wrong with the queue file, or null. Never its content. */
  String problem() {
    if (readFailing) {
      return "could not be read right now; it is kept and read again later";
    }
    if (unsaved) {
      return "could not be saved, so new items may be lost";
    }
    return setAside ? "was unreadable and was set aside" : null;
  }

  /** Oldest items dropped this session because the queue was full. */
  int dropped() {
    return dropped;
  }

  private void write(List<OutboxEntry> entries) {
    unwritten = new ArrayList<>(entries);
    unwrittenIsFull = !readFailing;
    // Writing now would replace the unread file with only what is in memory.
    if (readFailing) {
      return;
    }
    Path target = file.toPath();
    Path directory = target.getParent();
    try {
      if (directory != null) {
        Files.createDirectories(directory);
      }
      // Temp then move, so a crash mid-write leaves the previous outbox intact.
      Path temp = Files.createTempFile(directory, "events", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(entries, LIST_TYPE, writer);
      }
      try {
        Files.move(
            temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
      unsaved = false;
      unwritten = null;
    } catch (IOException | RuntimeException e) {
      unsaved = true;
      // Swallowed: throwing out of a capture handler would break every detector on the tick.
      log.debug("event outbox write failed: {}", e.getMessage());
    }
  }

  /**
   * The ids the outbox should stop retrying: stored or duplicate, plus {@code "stale"}
   * rejections, which only get truer with time. {@code "not_applied"} stays pending, since the
   * capability flag can be turned on later.
   */
  static Set<String> idsToAck(List<EventAck> acks) {
    Set<String> ids = new HashSet<>();
    for (EventAck ack : acks) {
      if (ack.isStored() || isPermanentlyRejected(ack)) {
        ids.add(ack.getId());
      }
    }
    return ids;
  }

  private static boolean isPermanentlyRejected(EventAck ack) {
    // An invalid event fails the same check on every resend.
    return "rejected".equals(ack.getOutcome())
        && ("stale".equals(ack.getReason()) || "invalid".equals(ack.getReason()));
  }

  static Set<String> toIdSet(Iterable<String> ids) {
    Set<String> set = new HashSet<>();
    for (String id : ids) set.add(id);
    return set;
  }
}

package com.bankstand;

import com.bankstand.dto.SubmitEventsResponse;
import java.util.HashMap;
import java.util.Map;

/**
 * Pauses every event send after a 429, and holds back an account whose batch came back
 * unrouted (no saved character) until the identity changes or {@link #UNROUTED_BACKOFF_MS}
 * passes. The events stay queued either way.
 */
final class EventSendPacer {

  static final long UNROUTED_BACKOFF_MS = 30 * 60_000L;

  private long pausedUntilMs;
  private final Map<Long, Long> unroutedUntilMs = new HashMap<>();

  synchronized boolean maySend(long accountHash, long nowMs) {
    return nowMs >= pausedUntilMs && nowMs >= unroutedUntilMs.getOrDefault(accountHash, 0L);
  }

  /** Records one chunk's outcome; true when its acks should be applied to the outbox. */
  synchronized boolean record(
      long accountHash, long nowMs, SubmitEventsResponse response, Throwable failure) {
    if (failure != null) {
      if (failure instanceof SubmitException) {
        pauseFor(nowMs, ((SubmitException) failure).getRetryAfterMillis());
      }
      return false;
    }
    if (!response.isRouted()) {
      unrouted(accountHash, nowMs);
      return false;
    }
    return true;
  }

  synchronized void pauseFor(long nowMs, long retryAfterMs) {
    pausedUntilMs = Math.max(pausedUntilMs, nowMs + retryAfterMs);
  }

  synchronized void unrouted(long accountHash, long nowMs) {
    unroutedUntilMs.put(accountHash, nowMs + UNROUTED_BACKOFF_MS);
  }

  /** A relog or re-pair may route what did not before. */
  synchronized void forgetUnrouted() {
    unroutedUntilMs.clear();
  }
}

package com.bankstand;

import com.bankstand.dto.SubmitSnapshotResponse;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.LongSupplier;

/**
 * Blocks the server received but kept back, because they would lower progress it already has.
 * Not an ack: a held read is never a baseline. It only stops the same read being uploaded on
 * every capture. Memory only, per login, so a restart, relog or re-pair offers it again.
 * Client thread.
 */
final class HeldBlocks {

  /** The diary task vars rider, which is not a capability of its own. */
  static final String DIARY_TASK_VARS = "diaryTaskVars";

  // Bounds stale suppression after a removal on the server the plugin cannot see.
  static final long EXPIRY_MS = 30 * 60 * 1000L;

  private static final class Held {
    final long accountHash;
    final int generation;
    final String digest;
    final long atMs;

    Held(long accountHash, int generation, String digest, long atMs) {
      this.accountHash = accountHash;
      this.generation = generation;
      this.digest = digest;
      this.atMs = atMs;
    }
  }

  private final Map<String, Held> held = new HashMap<>();
  private final LongSupplier clock;

  HeldBlocks(LongSupplier clock) {
    this.clock = clock;
  }

  /** The capability keys (and the vars rider) a response held. A wider block wins over stored. */
  static Set<String> heldKeys(SubmitSnapshotResponse res) {
    List<String> blocks = res.getHeldBlocks();
    Set<String> keys = new HashSet<>();
    if (blocks.contains("quests")) {
      keys.add(Capability.QUESTS.key);
    }
    // The diaries capability carries the flags and counts together.
    if (blocks.contains("diaries") || blocks.contains("diaryTasks")) {
      keys.add(Capability.DIARIES.key);
    }
    if (blocks.contains(DIARY_TASK_VARS)) {
      keys.add(DIARY_TASK_VARS);
    }
    if (blocks.contains("combatAchievementLampClaimed")) {
      keys.add(Capability.COMBAT_ACHIEVEMENTS.key);
    }
    return keys;
  }

  /** Whether this read is the one last held for this login, so sending it again is pointless. */
  @SafeVarargs
  final boolean suppresses(String key, long accountHash, int generation, Map<String, ?>... read) {
    Held h = held.get(key);
    if (h == null || h.accountHash != accountHash || h.generation != generation) {
      return false;
    }
    if (clock.getAsLong() - h.atMs >= EXPIRY_MS) {
      held.remove(key);
      return false;
    }
    return h.digest.equals(digest(read));
  }

  /**
   * Applies the server's verdict on one block and returns whether it may be acked: held wins over
   * stored, a held block records what was sent, and a stored one clears its hold.
   */
  @SafeVarargs
  final boolean settle(
      String key,
      SubmitSnapshotResponse res,
      boolean stored,
      long accountHash,
      int generation,
      Map<String, ?>... sent) {
    if (sent[0] != null && heldKeys(res).contains(key)) {
      held.put(key, new Held(accountHash, generation, digest(sent), clock.getAsLong()));
      return false;
    }
    if (stored) {
      held.remove(key);
    }
    return stored;
  }

  /** The keys held for this login, for the panel. */
  Set<String> current(long accountHash, int generation) {
    Set<String> keys = new HashSet<>();
    held.forEach(
        (key, h) -> {
          if (h.accountHash == accountHash && h.generation == generation) {
            keys.add(key);
          }
        });
    return keys;
  }

  void clear() {
    held.clear();
  }

  private static String digest(Map<String, ?>[] blocks) {
    StringBuilder all = new StringBuilder();
    for (Map<String, ?> block : blocks) {
      all.append(block == null ? "-" : CapabilityDigest.of(block)).append('/');
    }
    return all.toString();
  }
}

package com.bankstand;

import net.runelite.client.config.ConfigManager;

/**
 * Pairings made before the device file kept the token in ConfigManager. The unset matters most:
 * it is what deletes the token from RuneLite's config sync on a synced profile.
 */
final class LegacyCredentials {

  private LegacyCredentials() {}

  /**
   * Moves credentials from ConfigManager to the device file. A no-op after the first run. The file
   * wins if both exist, so a stale synced value never overwrites a newer pairing.
   */
  static void migrate(ConfigManager configManager, DeviceCredentialStore deviceStore) {
    String legacyToken =
        configManager.getConfiguration(BankstandKeys.GROUP, BankstandKeys.KEY_DEVICE_TOKEN);
    if (legacyToken == null || legacyToken.trim().isEmpty()) {
      return;
    }
    if (!deviceStore.load().isPaired()) {
      DeviceCredentials migrated = new DeviceCredentials();
      migrated.setToken(legacyToken);
      migrated.setDeviceId(
          configManager.getConfiguration(BankstandKeys.GROUP, BankstandKeys.KEY_DEVICE_ID));
      migrated.setExpiresAt(
          configManager.getConfiguration(BankstandKeys.GROUP, BankstandKeys.KEY_TOKEN_EXPIRES_AT));
      deviceStore.save(migrated);
    }
    forget(configManager);
  }

  /** Clears the pre-file credential keys, and on a synced profile the upstream copy. */
  static void forget(ConfigManager configManager) {
    configManager.unsetConfiguration(BankstandKeys.GROUP, BankstandKeys.KEY_DEVICE_TOKEN);
    configManager.unsetConfiguration(BankstandKeys.GROUP, BankstandKeys.KEY_DEVICE_ID);
    configManager.unsetConfiguration(BankstandKeys.GROUP, BankstandKeys.KEY_TOKEN_EXPIRES_AT);
  }
}

package com.bankstand;

import java.time.Instant;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import net.runelite.api.NPC;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemStack;

/**
 * Captures loot from {@link NpcLootReceived} only: never {@code PlayerLootReceived}, which
 * names another player. The gate is checked before any read.
 */
public class LootCapture {

  /** The item lookups this needs, behind a seam so the logic is testable without a client. */
  interface Items {
    /** The base id for a noted or placeholder variant, so the server joins on one id. */
    int canonical(int itemId);

    /** Whether this stack would count as a notable drop under the player's own rule. */
    boolean isNotable(int itemId, int quantity);
  }

  private final BooleanSupplier enabled;
  private final LongSupplier accountHash;
  private final Items items;
  private final LootLedger ledger;
  private final LootOutbox outbox;
  private final Runnable onNotable;
  private final Supplier<Instant> clock;

  LootCapture(
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Items items,
      LootLedger ledger,
      LootOutbox outbox,
      Runnable onNotable,
      Supplier<Instant> clock) {
    this.enabled = enabled;
    this.accountHash = accountHash;
    this.items = items;
    this.ledger = ledger;
    this.outbox = outbox;
    this.onNotable = onNotable;
    this.clock = clock;
  }

  @Subscribe
  public void onNpcLootReceived(NpcLootReceived event) {
    if (!enabled.getAsBoolean()) {
      return;
    }
    NPC npc = event.getNpc();
    if (npc == null) {
      return;
    }
    handleKill(npc.getId(), npc.getName(), event.getItems());
  }

  /** Package-private so a test can drive one kill without a live client. */
  void handleKill(int npcId, String npcName, Collection<ItemStack> stacks) {
    if (!enabled.getAsBoolean()) {
      return;
    }
    Map<Integer, Integer> kill = new LinkedHashMap<>();
    boolean notable = false;
    for (ItemStack stack : stacks) {
      if (stack.getQuantity() < 1) {
        continue;
      }
      notable |= items.isNotable(stack.getId(), stack.getQuantity());
      kill.merge(items.canonical(stack.getId()), stack.getQuantity(), LootCapture::addCapped);
    }
    long hash = accountHash.getAsLong();
    List<LootEntry> closed = ledger.record(hash, npcId, npcName, kill, clock.get());
    if (notable) {
      closed.addAll(ledger.close(hash, npcId));
    }
    outbox.addAll(closed);
    if (notable) {
      onNotable.run();
    }
  }

  private static int addCapped(int a, int b) {
    long sum = (long) a + b;
    return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
  }
}

