package com.bankstand;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;

/**
 * Aggregates loot per NPC into windows closed on each drain. A window closes before a kill
 * would break a server bound, so every record is valid and holds at least one kill.
 * Thread-safe.
 */
final class LootLedger {

  static final int MAX_KILLS_PER_RECORD = 1_000;
  static final int MAX_ITEMS_PER_RECORD = 64;
  static final int MAX_QUANTITY = 1_000_000;
  static final int MAX_NPC_NAME_LENGTH = 64;
  // Under the server's ten-minute bound; only reached when drains stall.
  static final Duration MAX_WINDOW = Duration.ofMinutes(5);

  private final Map<Key, Window> open = new LinkedHashMap<>();
  private volatile Supplier<String> pairing = () -> null;

  /** Where a new window reads the pairing its record is tagged with. */
  void setPairing(Supplier<String> pairing) {
    this.pairing = pairing;
  }

  /**
   * Records one kill and returns any window it closed to make room.
   *
   * @param items canonical item id to quantity for this kill alone
   */
  synchronized List<LootEntry> record(
      long accountHash, int npcId, String npcName, Map<Integer, Integer> items, Instant at) {
    List<LootEntry> closed = new ArrayList<>();
    String name = cleanName(npcName);
    Map<Integer, Integer> kill = boundedKill(items);
    if (name == null || kill.isEmpty() || npcId < 0) {
      return closed;
    }
    Key key = new Key(accountHash, npcId);
    Window window = open.get(key);
    if (window != null && !window.accepts(kill, at)) {
      closed.add(window.close(accountHash));
      open.remove(key);
      window = null;
    }
    if (window == null) {
      window = new Window(npcId, name, at, pairing.get());
      open.put(key, window);
    }
    window.add(kill, at);
    return closed;
  }

  /** Closes one NPC's window, for a notable kill that should not wait for the drain. */
  synchronized List<LootEntry> close(long accountHash, int npcId) {
    List<LootEntry> closed = new ArrayList<>();
    Window window = open.remove(new Key(accountHash, npcId));
    if (window != null) {
      closed.add(window.close(accountHash));
    }
    return closed;
  }

  /** Closes every open window: on each drain, and before a logout is sent. */
  synchronized List<LootEntry> closeAll() {
    List<LootEntry> closed = new ArrayList<>();
    for (Iterator<Map.Entry<Key, Window>> it = open.entrySet().iterator(); it.hasNext(); ) {
      Map.Entry<Key, Window> entry = it.next();
      closed.add(entry.getValue().close(entry.getKey().accountHash));
      it.remove();
    }
    return closed;
  }

  /** Forgets every open window without sending it, for when the player turns loot off. */
  synchronized void discard() {
    open.clear();
  }

  private static String cleanName(String npcName) {
    if (npcName == null) {
      return null;
    }
    String trimmed = npcName.trim();
    if (trimmed.isEmpty()) {
      return null;
    }
    return trimmed.length() > MAX_NPC_NAME_LENGTH
        ? trimmed.substring(0, MAX_NPC_NAME_LENGTH)
        : trimmed;
  }

  /** Trims one kill's loot to the per-record bounds; only a corrupt event ever hits them. */
  private static Map<Integer, Integer> boundedKill(Map<Integer, Integer> items) {
    Map<Integer, Integer> kept = new LinkedHashMap<>();
    if (items == null) {
      return kept;
    }
    for (Map.Entry<Integer, Integer> e : items.entrySet()) {
      Integer id = e.getKey();
      Integer qty = e.getValue();
      if (id == null || id < 0 || qty == null || qty < 1 || qty > MAX_QUANTITY) {
        continue;
      }
      if (kept.size() == MAX_ITEMS_PER_RECORD) {
        break;
      }
      kept.put(id, qty);
    }
    return kept;
  }

  private static final class Key {
    final long accountHash;
    final int npcId;

    Key(long accountHash, int npcId) {
      this.accountHash = accountHash;
      this.npcId = npcId;
    }

    @Override
    public boolean equals(Object o) {
      if (!(o instanceof Key)) {
        return false;
      }
      Key other = (Key) o;
      return accountHash == other.accountHash && npcId == other.npcId;
    }

    @Override
    public int hashCode() {
      return Objects.hash(accountHash, npcId);
    }
  }

  private static final class Window {
    final int npcId;
    final String npcName;
    final Instant start;
    final String pairingId;
    Instant last;
    int kills;
    final Map<Integer, Long> items = new LinkedHashMap<>();

    Window(int npcId, String npcName, Instant start, String pairingId) {
      this.pairingId = pairingId;
      this.npcId = npcId;
      this.npcName = npcName;
      this.start = start;
      this.last = start;
    }

    boolean accepts(Map<Integer, Integer> kill, Instant at) {
      if (kills + 1 > MAX_KILLS_PER_RECORD) {
        return false;
      }
      if (at.isBefore(start) || Duration.between(start, at).compareTo(MAX_WINDOW) > 0) {
        return false;
      }
      int distinct = items.size();
      for (Map.Entry<Integer, Integer> e : kill.entrySet()) {
        Long held = items.get(e.getKey());
        if (held == null) {
          distinct++;
        } else if (held + e.getValue() > MAX_QUANTITY) {
          return false;
        }
      }
      return distinct <= MAX_ITEMS_PER_RECORD;
    }

    void add(Map<Integer, Integer> kill, Instant at) {
      kills++;
      if (at.isAfter(last)) {
        last = at;
      }
      for (Map.Entry<Integer, Integer> e : kill.entrySet()) {
        items.merge(e.getKey(), (long) e.getValue(), Long::sum);
      }
    }

    LootEntry close(long accountHash) {
      List<LootEvent.Item> list = new ArrayList<>(items.size());
      for (Map.Entry<Integer, Long> e : items.entrySet()) {
        list.add(new LootEvent.Item(e.getKey(), (int) (long) e.getValue()));
      }
      return new LootEntry(
          accountHash,
          new LootEvent(
              UuidV7.generate(), npcId, npcName, kills, start.toString(), last.toString(), list),
          pairingId);
    }
  }
}

package com.bankstand;

import com.bankstand.dto.EventAck;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * The on-disk loot queue, separate from the event outbox so loot can never evict a pet or
 * achievement. Capped at {@link #MAX_PENDING}, oldest evicted first.
 */
@Slf4j
public class LootOutbox {

  static final int MAX_PENDING = 500;

  /** Rejections that resending the same record can never fix, so it is dropped. A {@code quota}
   *  rejection stays pending: the daily quota resets at UTC midnight. */
  private static final Set<String> TERMINAL_REJECTIONS =
      new HashSet<>(Arrays.asList("invalid", "stale"));

  private static final Type LIST_TYPE = new TypeToken<ArrayList<LootEntry>>() {}.getType();

  private final File file;
  // Far above a full queue's size, so only a damaged file is ever this large.
  private static final long MAX_FILE_BYTES = 4L * 1024 * 1024;
  // For the status report: counts and states only, never content.
  private volatile boolean setAside;
  private volatile boolean unsaved;
  private volatile int dropped;
  // What should be on disk but is not yet, cleared only by a successful write. Full when built
  // from a successful read; otherwise only what changed while the file could not be read.
  private List<LootEntry> unwritten;
  private boolean unwrittenIsFull;
  private volatile boolean readFailing;
  private final Gson gson;
  private volatile Supplier<String> pairing = () -> null;

  public LootOutbox(File file, Gson gson) {
    this.file = file;
    this.gson = gson;
  }

  /** Appends closed records, evicting the oldest pending ones past the cap. */
  public synchronized void addAll(Collection<LootEntry> added) {
    if (added.isEmpty()) {
      return;
    }
    List<LootEntry> entries = current();
    entries.addAll(added);
    int evicted = 0;
    while (entries.size() > MAX_PENDING) {
      entries.remove(0);
      evicted++;
      dropped++;
    }
    if (evicted > 0) {
      log.warn("loot outbox full ({} pending): dropped {} oldest records", MAX_PENDING, evicted);
    }
    write(entries);
  }

  /** Every pending entry, oldest first. A snapshot: mutating it does not persist. */
  public synchronized List<LootEntry> pending() {
    return current();
  }

  /** Removes exactly the entries whose record id is in {@code ids}. */
  public synchronized void ack(Set<String> ids) {
    if (ids.isEmpty()) {
      return;
    }
    List<LootEntry> entries = current();
    entries.removeIf(entry -> ids.contains(entry.getEvent().getId()));
    write(entries);
  }

  /** Forgets every pending record, on disk too, so a restart cannot send them either. */
  public synchronized void clear() {
    // Nothing is pending, so this is the full list whatever the last read did.
    readFailing = false;
    write(new ArrayList<>());
  }

  /** Stored, duplicate and unfixable rejections are dropped; anything else is resent. */
  static Set<String> idsToAck(List<EventAck> acks) {
    Set<String> ids = new HashSet<>();
    for (EventAck ack : acks) {
      if (ack.getId() == null) {
        continue;
      }
      boolean terminal =
          "rejected".equals(ack.getOutcome()) && TERMINAL_REJECTIONS.contains(ack.getReason());
      if (ack.isStored() || terminal) {
        ids.add(ack.getId());
      }
    }
    return ids;
  }

  /** Where the current pairing id is read; entries tagged with another one are never sent. */
  public void setPairing(Supplier<String> pairing) {
    this.pairing = pairing;
  }

  // Fails closed: if a clear on re-pair could not write, the old pairing's entries still never
  // leave. They are dropped here, and from disk whenever a write succeeds.
  private List<LootEntry> current() {
    List<LootEntry> entries;
    boolean flush = unwritten != null;
    if (flush && unwrittenIsFull) {
      entries = new ArrayList<>(unwritten);
    } else {
      List<LootEntry> fromDisk = read();
      readFailing = fromDisk == null;
      entries = fromDisk == null ? new ArrayList<>() : fromDisk;
      if (flush) {
        entries.addAll(unwritten);
      }
    }
    String now = pairing.get();
    // An unreadable pairing is not "another pairing": nothing is purged until it is known.
    boolean purged =
        !PairingQueues.UNKNOWN.equals(now)
            && entries.removeIf(entry -> !Objects.equals(now, entry.getPairingId()));
    if (purged || flush) {
      write(entries);
    }
    return entries;
  }



  private List<LootEntry> read() {
    if (!file.exists()) {
      return new ArrayList<>();
    }
    if (file.length() > MAX_FILE_BYTES) {
      return setAside();
    }
    try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
      List<LootEntry> stored = gson.fromJson(reader, LIST_TYPE);
      if (stored == null) {
        return new ArrayList<>();
      }
      // Valid JSON can still lack what every reader of an entry needs.
      for (LootEntry entry : stored) {
        if (entry == null || entry.getEvent() == null || entry.getEvent().getId() == null) {
          return setAside();
        }
      }
      return new ArrayList<>(stored);
    } catch (IOException | RuntimeException e) {
      log.debug("loot outbox unreadable: {}", e.getMessage());
      // Damaged for good: kept aside. Maybe passing (a lock, a permission): left in place.
      return ReadFailures.isDamaged(e) ? setAside() : null;
    }
  }

  // Moved aside, never overwritten, so a damaged queue can still be inspected or recovered.
  private <T> List<T> setAside() {
    setAside = true;
    try {
      Files.move(
          file.toPath(),
          file.toPath().resolveSibling(file.getName() + ".unreadable"),
          StandardCopyOption.REPLACE_EXISTING);
    } catch (IOException | RuntimeException e) {
      log.debug("loot outbox could not be set aside: {}", e.getMessage());
    }
    return new ArrayList<>();
  }

  /** What is wrong with the queue file, or null. Never its content. */
  String problem() {
    if (readFailing) {
      return "could not be read right now; it is kept and read again later";
    }
    if (unsaved) {
      return "could not be saved, so new items may be lost";
    }
    return setAside ? "was unreadable and was set aside" : null;
  }

  /** Oldest items dropped this session because the queue was full. */
  int dropped() {
    return dropped;
  }

  private void write(List<LootEntry> entries) {
    unwritten = new ArrayList<>(entries);
    unwrittenIsFull = !readFailing;
    // Writing now would replace the unread file with only what is in memory.
    if (readFailing) {
      return;
    }
    Path target = file.toPath();
    Path directory = target.getParent();
    try {
      if (directory != null) {
        Files.createDirectories(directory);
      }
      // Temp then move, so a crash mid-write leaves the previous file intact.
      Path temp = Files.createTempFile(directory, "loot", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(entries, LIST_TYPE, writer);
      }
      try {
        Files.move(
            temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
      unsaved = false;
      unwritten = null;
    } catch (IOException | RuntimeException e) {
      unsaved = true;
      log.debug("loot outbox write failed: {}", e.getMessage());
    }
  }
}

package com.bankstand;

/**
 * Pauses loot sends after a 429 and spaces a notable drop's early send by {@link
 * #FAST_SEND_SPACING_MS}.
 */
final class LootSendPacer {

  static final long FAST_SEND_SPACING_MS = 30_000L;

  private long pausedUntilMs;
  private long lastFastSendMs = Long.MIN_VALUE;

  synchronized boolean mayDrain(long nowMs) {
    return nowMs >= pausedUntilMs;
  }

  /** True, and consumes the slot, when an early send may go now. */
  synchronized boolean tryFastSend(long nowMs) {
    if (!mayDrain(nowMs)) {
      return false;
    }
    if (lastFastSendMs != Long.MIN_VALUE && nowMs - lastFastSendMs < FAST_SEND_SPACING_MS) {
      return false;
    }
    lastFastSendMs = nowMs;
    return true;
  }

  synchronized void pauseFor(long nowMs, long retryAfterMs) {
    pausedUntilMs = Math.max(pausedUntilMs, nowMs + retryAfterMs);
  }
}

package com.bankstand;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

/**
 * Caches the last valid manifest in a local file (not {@code ConfigManager}, which syncs to
 * RuneLite's servers). Fallback order: fetched, else cached, else bundled. Read failures mean
 * "nothing cached"; write failures are swallowed. Background executor only.
 */
public class ManifestStore {

  private final File file;
  private final Gson gson;

  public ManifestStore(File file, Gson gson) {
    this.file = file;
    this.gson = gson;
  }

  /** Null when there is none. Re-validated on load, since the file can be edited. */
  public CapabilityManifest load() {
    if (!file.isFile()) {
      return null;
    }
    try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
      return CapabilityManifest.validate(
          gson.fromJson(reader, CapabilityManifest.RawManifest.class));
    } catch (IOException | JsonSyntaxException e) {
      return null;
    }
  }

  /** Only for a manifest that already validated. */
  public void save(CapabilityManifest.RawManifest raw) {
    if (raw == null) {
      return;
    }
    try {
      Path target = file.toPath();
      Path parent = target.getParent();
      if (parent != null) {
        Files.createDirectories(parent);
      }
      // Temp then move, so a crash midway leaves the previous file intact.
      Path temp = Files.createTempFile(parent, "manifest", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(raw, writer);
      }
      try {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
    } catch (IOException e) {
      // Caching is an optimisation; losing it costs one fetch.
    }
  }

  /** The entry point: the freshest usable manifest, never null. */
  public CapabilityManifest current(CapabilityManifest fetched) {
    if (fetched != null) {
      return fetched;
    }
    CapabilityManifest cached = load();
    return cached != null ? cached : CapabilityManifest.bundled();
  }
}

