package com.bankstand;

import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Predicate;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Captures a quest completion by name from the quest-complete scroll, so a quest RuneLite's
 * Quest list does not have yet still reaches the server. A quest the list does know is skipped:
 * the quests snapshot already reports it.
 */
public class QuestCompletionCapture extends BaseCapture {

  // "You have completed The Corsair Curse!"
  private static final Pattern TITLE_PATTERN_1 =
      Pattern.compile(
          ".+?ve\\.*? (?<verb>been|rebuilt|.+?ed)? ?(?:the )?'?(?<quest>.+?)'?(?: [Qq]uest)?[!.]?$");
  // "'One Small Favour' completed!"
  private static final Pattern TITLE_PATTERN_2 =
      Pattern.compile("'?(?<quest>.+?)'?(?: [Qq]uest)? (?<verb>[a-z]\\w+?ed)?(?: f.*?)?[!.]?$");
  private static final List<String> RFD_TAGS =
      List.of("Another Cook", "freed", "defeated", "saved");
  private static final List<String> WORD_QUEST_IN_NAME_TAGS =
      List.of("Another Cook", "Doric", "Heroes", "Legends", "Observatory", "Olaf", "Waterfall");
  private static final Map<String, String> NAME_FIXES =
      Map.of(
          "Lumbridge Cook... again", "Another Cook's",
          "Skrach 'Bone Crusher' Uglogwee", "Skrach Uglogwee");

  // Matches the server's bound.
  private static final int MAX_QUEST_NAME_LENGTH = 128;

  private final Client client;
  private final LongSupplier accountHash;
  private final Predicate<String> knownToRuneLite;
  private final Set<String> sent = new HashSet<>();

  public QuestCompletionCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Client client,
      Predicate<String> knownToRuneLite,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
    this.client = client;
    this.accountHash = accountHash;
    this.knownToRuneLite = knownToRuneLite;
  }

  @Subscribe
  public void onWidgetLoaded(WidgetLoaded event) {
    if (event.getGroupId() != InterfaceID.QUESTSCROLL) {
      return;
    }
    Widget title = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
    if (title != null && title.getText() != null) {
      handleTitle(Text.removeTags(title.getText()));
    }
  }

  void handleTitle(String text) {
    if (!isEnabled()) {
      return;
    }
    String quest = parseScrollTitle(text);
    if (quest == null || quest.length() > MAX_QUEST_NAME_LENGTH || knownToRuneLite.test(quest)) {
      return;
    }
    // One per quest per account per run; the server also dedupes.
    if (sent.add(accountHash.getAsLong() + ":" + quest.toLowerCase(Locale.ROOT))) {
      emit(TransientEvent.TYPE_QUEST_COMPLETED, Map.of("questName", quest));
    }
  }

  /** The quest a scroll title names, or null when it is not a full completion. */
  static String parseScrollTitle(String text) {
    if (text == null) {
      return null;
    }
    Matcher match = TITLE_PATTERN_1.matcher(text);
    if (!match.matches()) {
      match = TITLE_PATTERN_2.matcher(text);
      if (!match.matches()) {
        return null;
      }
    }
    String quest = match.group("quest");
    quest = NAME_FIXES.getOrDefault(quest, quest);
    String verb = match.group("verb") == null ? "" : match.group("verb");
    if (verb.contains("kind of")) {
      return null;
    }
    if (verb.contains("completely")) {
      quest += " II";
    }
    String questAndVerb = quest + verb;
    if (RFD_TAGS.stream().anyMatch(questAndVerb::contains)) {
      quest = "Recipe for Disaster - " + quest;
    }
    if (WORD_QUEST_IN_NAME_TAGS.stream().anyMatch(quest::contains)) {
      quest += " Quest";
    }
    quest = quest.trim();
    return quest.isEmpty() ? null : quest;
  }
}

package com.bankstand;

import com.google.gson.JsonParseException;
import com.google.gson.stream.MalformedJsonException;
import java.io.EOFException;
import java.io.IOException;
import java.nio.charset.CharacterCodingException;

/**
 * Tells a damaged local file from one that could not be read right now. Gson wraps a reader's
 * IOException as a syntax error, so the cause decides, not the exception type.
 */
final class ReadFailures {

  private ReadFailures() {}

  static boolean isDamaged(Throwable failure) {
    for (Throwable t = failure; t != null; t = t.getCause()) {
      // Bad JSON, bytes that are not UTF-8, or a file that ends mid-document or mid-character.
      if (t instanceof MalformedJsonException
          || t instanceof EOFException
          || t instanceof CharacterCodingException) {
        return true;
      }
      if (t instanceof IOException) {
        return false;
      }
    }
    return failure instanceof JsonParseException;
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * The panel's session-only "recent activity" list, newest first. Descriptions are built when the
 * event is emitted, since there is no lookup table to rebuild them from ids later.
 *
 * <p>Synchronized: written on the client thread, read on the Swing EDT.
 */
final class RecentActivityLog {

  static final int MAX_ENTRIES = 10;

  private final LinkedList<PanelModel.ActivityRow> entries = new LinkedList<>();

  synchronized void record(String description) {
    entries.addFirst(new PanelModel.ActivityRow(description, System.currentTimeMillis()));
    while (entries.size() > MAX_ENTRIES) {
      entries.removeLast();
    }
  }

  /** A copy, newest first. */
  synchronized List<PanelModel.ActivityRow> recent() {
    return new ArrayList<>(entries);
  }

  /** Called on an account switch. */
  synchronized void clear() {
    entries.clear();
  }

  /** Null for an unknown type, which the panel skips. */
  static String describe(String type, Map<String, Object> payload) {
    switch (type) {
      case TransientEvent.TYPE_COLLECTION_LOG_UNLOCK:
        return "Collection log: " + payload.get("itemName");
      case TransientEvent.TYPE_COMBAT_ACHIEVEMENT_COMPLETED:
        return "Combat achievements: " + payload.get("taskName") + " completed";
      case TransientEvent.TYPE_DIARY_TASK_COMPLETED:
        return "Diaries: "
            + capitalize(String.valueOf(payload.get("tier")))
            + " task completed in "
            + payload.get("area");
      case TransientEvent.TYPE_QUEST_COMPLETED:
        return "Quests: " + payload.get("questName") + " completed";
      case TransientEvent.TYPE_NOTABLE_DROP:
        return "Notable drop: " + payload.get("itemName");
      case TransientEvent.TYPE_PET_DROP:
        return "Pet drop: " + payload.get("petName");
      case TransientEvent.TYPE_SLAYER_TASK_COMPLETED:
        Object creature = payload.get("creature");
        return creature == null ? "Slayer task completed" : "Slayer task completed: " + creature;
      default:
        return null;
    }
  }

  private static String capitalize(String word) {
    if (word.isEmpty()) {
      return word;
    }
    return word.substring(0, 1).toUpperCase(Locale.ROOT) + word.substring(1);
  }
}

