/** The last stored slayer task. In memory, reset on an account switch. */
final class SlayerTaskBaseline {
  private SlayerTask acked;

  boolean changedSince(SlayerTask current) {
    return current != null && !current.equals(acked);
  }

  /** The read, or null while no task may be varps not yet sent: as {@link AccountTypeBaseline}. */
  SlayerTask unlessHeld(int ticksSinceLogin, SlayerTask read) {
    boolean held =
        ticksSinceLogin < DiaryBaseline.HOLD_TICKS
            && read != null
            && !read.active
            && (acked == null || acked.active);
    return held ? null : read;
  }

  void advance(SlayerTask ackedNow) {
    acked = ackedNow;
  }

  void reset() {
    acked = null;
  }
}

package com.bankstand;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Captures a finished slayer task from the game's completion line, using RuneLite's Slayer
 * plugin pattern. The game clears the task on completion, so creature and assigned count
 * come from the task as last seen; that bookkeeping runs even with the toggle off.
 */
public class SlayerTaskCompletionCapture extends BaseCapture {

  static final Pattern COMPLETE =
      Pattern.compile(
          "You've completed (?:at least )?(?<tasks>[\\d,]+) (?:Wilderness )?tasks?(?: and received"
              + " (?<awarded>[\\d,]+) points, giving you a total of (?<points>[\\d,]+)| and reached"
              + " the maximum amount of Slayer points \\((?<points2>[\\d,]+)\\))?");

  private final Supplier<SlayerTask> currentTask;
  private SlayerTask lastSeen;

  public SlayerTaskCompletionCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Supplier<SlayerTask> currentTask,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
    this.currentTask = currentTask;
  }

  /**
   * Remembers the running task each time its kill count moves. Reads at zero too, so the task is
   * seen ending and the next one counts as seen starting.
   */
  @Subscribe
  public void onVarbitChanged(VarbitChanged event) {
    // Off, or on a world that is not read: the task there is not this character's to remember.
    if (event.getVarpId() != VarPlayerID.SLAYER_COUNT || !isEnabled()) {
      return;
    }
    SlayerTask task = currentTask.get();
    if (event.getValue() > 0 && task != null && task.active) {
      lastSeen = task;
    }
  }

  @Subscribe
  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) {
      return;
    }
    onMessage(Text.removeTags(event.getMessage()));
  }

  /** Package-private so a test can feed a line without a {@link ChatMessage}. */
  void onMessage(String message) {
    if (!isCompletionLine(message)) {
      return;
    }
    SlayerTask task = lastSeen;
    lastSeen = null;
    if (!isEnabled()) {
      return;
    }
    Matcher m = COMPLETE.matcher(message);
    if (!m.find()) {
      return;
    }
    String totalPoints = m.group("points") != null ? m.group("points") : m.group("points2");
    emit(
        TransientEvent.TYPE_SLAYER_TASK_COMPLETED,
        payload(
            task == null ? null : task.creature,
            task == null ? null : task.assigned,
            task == null ? null : task.master,
            parseCount(m.group("awarded")),
            parseCount(totalPoints),
            parseCount(m.group("tasks")),
            task == null ? null : task.startedAt));
  }

  /** Forgets the remembered task, on an account switch. */
  void reset() {
    lastSeen = null;
  }

  static boolean isCompletionLine(String message) {
    return message != null
        && message.startsWith("You've completed")
        && (message.contains("Slayer master") || message.contains("Slayer Master"));
  }

  static Map<String, Object> payload(
      String creature,
      Integer killed,
      String master,
      Integer pointsAwarded,
      Integer pointsTotal,
      Integer streak) {
    return payload(creature, killed, master, pointsAwarded, pointsTotal, streak, null);
  }

  static Map<String, Object> payload(
      String creature,
      Integer killed,
      String master,
      Integer pointsAwarded,
      Integer pointsTotal,
      Integer streak,
      String startedAt) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("creature", creature);
    payload.put("killed", killed);
    payload.put("master", master);
    payload.put("pointsAwarded", pointsAwarded);
    payload.put("pointsTotal", pointsTotal);
    payload.put("streak", streak);
    // Omitted when unknown, which the server reads as not observed.
    if (startedAt != null) {
      payload.put("startedAt", startedAt);
    }
    return payload;
  }

  private static Integer parseCount(String digits) {
    if (digits == null) {
      return null;
    }
    try {
      return Integer.parseInt(digits.replace(",", ""));
    } catch (NumberFormatException e) {
      return null;
    }
  }
}

package com.bankstand;

import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads the current slayer task the way RuneLite's Slayer plugin does. Never the location,
 * block list or unlocks. Client thread only.
 */
final class SlayerTaskReader {

  // "A boss of your choice": the real target is in a second table.
  private static final int BOSS_TASK_ID = 98;
  // Extended or shortened assignment.
  private static final int COUNT_MODIFIER_ID = 2;
  // Masters whose streak has its own counter.
  private static final int KRYSTILIA = 7;
  private static final int MORTIMER = 10;
  // SLAYER_MASTER values 1 to 10, per the OSRS Wiki. Paired masters share a value: Turael and
  // Aya, Duradel and Kuradal, Nieve and Steve.
  private static final String[] MASTER_KEYS = {
    "turael", "mazchna", "vannaka", "chaeldar", "duradel",
    "nieve", "krystilia", "konar", "spria", "mortimer"
  };
  static final int MAX_STREAK = 1_000_000;
  // Slayer varps read zero until the game sends them, a few ticks after login.
  static final int READ_DELAY_TICKS = 10;

  private SlayerTaskReader() {}

  /** Whether the slayer values have had time to arrive since the last {@code LOGGED_IN}. */
  static boolean isReadable(int ticksSinceLoggedIn) {
    return ticksSinceLoggedIn >= READ_DELAY_TICKS;
  }

  /** The current task. Reads zero until the game sends the varps after login. */
  static SlayerTask read(Client client) {
    int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
    if (remaining <= 0) {
      return SlayerTask.NONE;
    }
    int assigned = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
    if (client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID) == COUNT_MODIFIER_ID) {
      int modifier = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
      boolean negative = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1;
      assigned += negative ? -modifier : modifier;
    }
    return new SlayerTask(
        true,
        creatureName(client),
        remaining,
        assigned > 0 ? assigned : null,
        masterKey(client.getVarbitValue(VarbitID.SLAYER_MASTER)),
        client.getVarbitValue(VarbitID.SLAYER_POINTS),
        streak(client),
        SlayerTask.streaks(
            bounded(client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED)),
            bounded(client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED)),
            bounded(client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED))));
  }

  /** The master's key, or null for 0 or a value the game added later. */
  static String masterKey(int value) {
    return value >= 1 && value <= MASTER_KEYS.length ? MASTER_KEYS[value - 1] : null;
  }

  private static Integer bounded(int value) {
    return value >= 0 && value <= MAX_STREAK ? value : null;
  }

  private static String creatureName(Client client) {
    int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
    Integer row;
    if (taskId == BOSS_TASK_ID) {
      List<Integer> bossRows =
          client.getDBRowsByValue(
              DBTableID.SlayerTaskSublist.ID,
              DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
              0,
              client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
      if (bossRows.isEmpty()) {
        return null;
      }
      Object[] task =
          client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
      row = task.length > 0 && task[0] instanceof Integer ? (Integer) task[0] : null;
    } else {
      List<Integer> rows =
          client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
      row = rows.isEmpty() ? null : rows.get(0);
    }
    if (row == null) {
      return null;
    }
    Object[] name = client.getDBTableField(row, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
    return name.length > 0 && name[0] instanceof String && !((String) name[0]).isEmpty()
        ? (String) name[0]
        : null;
  }

  private static Integer streak(Client client) {
    switch (client.getVarbitValue(VarbitID.SLAYER_MASTER)) {
      case KRYSTILIA:
        return client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
      case MORTIMER:
        return client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED);
      default:
        return client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
    }
  }
}

package com.bankstand;

import com.bankstand.session.AccountSession;
import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executor;
import net.runelite.api.Client;

/**
 * When the current slayer task started, as far as this client saw it. Only a change seen live (no
 * task, or another task, then this one) stamps a start; a task already running when the client
 * first looked has none. Kept per character in a local file (not {@code ConfigManager}) so a
 * restart keeps it. {@link #read} runs on the client thread; file IO goes to {@code io}.
 */
final class SlayerTaskStart {

  static final class Record {
    String creature;
    Integer assigned;
    String startedAt;
  }

  private static class Document {
    Map<String, Record> accounts;
  }

  private static final String NONE = "none";

  private final File file;
  private final Gson gson;
  private final Executor io;
  private final Client client;
  private final AccountSession session;
  private final Map<String, Record> records = new HashMap<>();
  private long lastSeenAccount = -1;
  private int lastSeenGeneration = -1;
  private String lastSeen;

  SlayerTaskStart(File file, Gson gson, Executor io, Client client, AccountSession session) {
    this.file = file;
    this.gson = gson;
    this.io = io;
    this.client = client;
    this.session = session;
    io.execute(this::load);
  }

  /**
   * The current task. {@code observable}: capture is on and the values have arrived, so this
   * read counts as seeing the task.
   */
  SlayerTask read(boolean observable) {
    SlayerTask task = SlayerTaskReader.read(client);
    if (!observable || !session.isActive()) {
      // Whatever changes while capture is off is not seen live; the next read is a baseline.
      forgetLive();
      return task;
    }
    return observe(session.getAccountHash(), session.getGeneration(), task, Instant.now());
  }

  private synchronized void forgetLive() {
    lastSeen = null;
  }

  /** Reads the file. A read failure means nothing is known. Never on the client thread. */
  synchronized void load() {
    if (!file.isFile()) {
      return;
    }
    try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
      Document document = gson.fromJson(reader, Document.class);
      if (document != null && document.accounts != null) {
        // What this session already saw wins over the file.
        document.accounts.forEach(records::putIfAbsent);
      }
    } catch (IOException | RuntimeException e) {
      // Not logged: the file holds account hashes.
    }
  }

  /** The task with its start, or with none when it was not seen starting. */
  synchronized SlayerTask observe(long accountHash, int generation, SlayerTask task, Instant now) {
    // A task whose name has not arrived yet is a partial read, not a new task.
    if (task.active && task.creature == null) {
      return task;
    }
    String seen = identity(task);
    // A new login (or account) starts unseen: the task can change while the client is away.
    boolean changedLive =
        accountHash == lastSeenAccount
            && generation == lastSeenGeneration
            && lastSeen != null
            && !lastSeen.equals(seen);
    lastSeenAccount = accountHash;
    lastSeenGeneration = generation;
    lastSeen = seen;
    String key = Long.toString(accountHash);
    Record stored = records.get(key);
    if (!task.active) {
      if (records.remove(key) != null) {
        save();
      }
      return task;
    }
    if (changedLive) {
      Record record = new Record();
      record.creature = task.creature;
      record.assigned = task.assigned;
      record.startedAt = now.toString();
      records.put(key, record);
      save();
      return task.withStartedAt(record.startedAt);
    }
    if (stored != null && seen.equals(identity(stored))) {
      return task.withStartedAt(stored.startedAt);
    }
    // A task the client did not see starting; an older record no longer applies.
    if (records.remove(key) != null) {
      save();
    }
    return task;
  }

  // shortcut: two back-to-back tasks of the same creature and count look like one when the end
  // between them was missed (client closed); add the task's varps to the identity if that matters.
  private static String identity(SlayerTask task) {
    return task.active ? task.creature + "|" + task.assigned : NONE;
  }

  private static String identity(Record record) {
    return record.creature + "|" + record.assigned;
  }

  private void save() {
    Document document = new Document();
    document.accounts = new HashMap<>(records);
    io.execute(() -> write(document));
  }

  private void write(Document document) {
    Path target = file.toPath();
    Path directory = target.getParent();
    try {
      if (directory != null) {
        Files.createDirectories(directory);
      }
      // Temp then move, so a crash midway leaves the previous file intact.
      Path temp = Files.createTempFile(directory, "slayer", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(document, writer);
      }
      try {
        Files.move(
            temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
    } catch (IOException | RuntimeException e) {
      // A failed save loses the start after a restart, nothing more.
    }
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.List;

/** The lines the {@code ::bstand} commands print, built from plain values so they are testable. */
public final class StatusReport {

  private StatusReport() {}

  /** What is waiting to be sent and whether its file is healthy. Counts only, never content. */
  static List<String> queueLines(String name, int pending, int dropped, String problem) {
    List<String> out = new ArrayList<>();
    out.add("Queued " + name + ": " + pending + ".");
    if (dropped > 0) {
      out.add("Queue full: " + dropped + " oldest " + name + " dropped this session.");
    }
    if (problem != null) {
      out.add("The " + name + " queue file " + problem + ".");
    }
    return out;
  }

  /**
   * @param paired whether a device token is stored
   * @param serverUrl where submissions go; shown because a wrong one is silent otherwise
   * @param linkedName the character bound to this pairing, or null if none has been linked
   * @param lastSubmitDescription e.g. "4 minutes ago", or null when nothing has been submitted
   * @param lastFailure the last failure reason, or null when the last attempt succeeded
   * @param enabled which capability names are switched on, in display order
   * @param collectionLogSlots how many slots the last guided read saw, or -1 when never read
   * @param accountTypeLine what the game reports this account to be, or null when logged out
   * @param manifestLine the capability manifest in use, so it is never a guess in a bug report
   */
  public static List<String> lines(
      boolean paired,
      String serverUrl,
      String linkedName,
      String lastSubmitDescription,
      String lastFailure,
      List<String> enabled,
      int collectionLogSlots,
      String accountTypeLine,
      String manifestLine) {
    List<String> out = new ArrayList<>();

    if (!paired) {
      out.add("Not paired. Paste a pairing code in the Bankstand settings to link this client.");
      return out;
    }

    out.add("Paired with " + serverUrl + ".");
    out.add(
        linkedName == null
            ? "No character linked yet. Log in and it links on the next tick, or run ::bstand link."
            : "Linked character: " + linkedName + ".");

    out.add(
        enabled.isEmpty()
            ? "No capabilities switched on, so nothing is being sent."
            : "Sending: " + String.join(", ", enabled) + ".");

    out.add(
        lastSubmitDescription == null
            ? "Nothing submitted yet this session."
            : "Last submitted " + lastSubmitDescription + ".");

    if (lastFailure != null) {
      out.add("Last failure: " + lastFailure);
    }

    // Always shown: a manual sync cannot refresh the log. Says "items", not "entries": it counts
    // distinct item ids, which can exceed the game's entry count because of variant ids.
    out.add(
        collectionLogSlots < 0
            ? "Collection log not read yet. Open it in game and use its Search to read the whole log."
            : "Collection log: "
                + collectionLogSlots
                + " items from the last read. Use the log's own Search to read it again.");

    // From the game, not the hiscores (which cannot see Group Ironman). Null while logged out,
    // where the varbit reads 0 and would wrongly print "regular".
    if (accountTypeLine != null) {
      out.add(accountTypeLine);
    }

    // Gates are this manifest intersected with the player's toggles.
    if (manifestLine != null) {
      out.add(manifestLine);
    }

    return out;
  }

  /**
   * What {@code ::bstand export} prints. Toggles only: never the pairing code, device token or
   * server URL, since the output is meant to be shared.
   */
  public static List<String> exportLines(
      boolean skills,
      boolean quests,
      boolean diaries,
      boolean collectionLog,
      boolean combatAchievements,
      boolean accountType,
      boolean notableDrops,
      int notableDropThreshold,
      boolean petDrops,
      boolean sessions,
      boolean loot,
      boolean slayer) {
    List<String> out = new ArrayList<>();
    out.add("Bankstand collect/events config:");
    out.add(onOff("Skill XP", skills));
    out.add(onOff("Quest progress", quests));
    out.add(onOff("Diary progress", diaries));
    out.add(onOff("Collection log", collectionLog));
    out.add(onOff("Combat achievements", combatAchievements));
    out.add(onOff("Account type", accountType));
    out.add(onOff("Notable drops", notableDrops) + " (threshold " + notableDropThreshold + " gp)");
    out.add(onOff("Pet drops", petDrops));
    out.add(onOff("Play sessions", sessions));
    out.add(onOff("Full loot", loot));
    out.add(onOff("Slayer task", slayer));
    return out;
  }

  private static String onOff(String label, boolean value) {
    return "- " + label + ": " + (value ? "on" : "off");
  }

  /**
   * What {@code ::bstand help} prints, in {@code CommandAction} order. A fixed list, kept in step
   * with the enum by {@code HelpLinesTest}.
   */
  public static List<String> helpLines() {
    List<String> out = new ArrayList<>();
    out.add("Bankstand commands:");
    out.add("- ::bstand - shows connection status: account, character, last sync.");
    out.add("- ::bstand sync - sends now instead of waiting for the next cycle.");
    out.add("- ::bstand link - re-links this character to your account.");
    out.add(
        "- ::bstand log - arms a guided collection log read; open the log and click Search.");
    out.add("- ::bstand export - prints and copies your current Collect/Events toggle state.");
    out.add("- ::bstand repair - clears a stale pairing so you can paste a fresh code.");
    out.add("- ::bstand help - shows this list.");
    return out;
  }

  /**
   * What {@code ::bstand sync} reports. Says plainly that the collection log is not included, so
   * the sync does not look broken.
   */
  public static List<String> syncLines(boolean paired, List<String> enabled) {
    List<String> out = new ArrayList<>();
    if (!paired) {
      out.add("Not paired, so there is nothing to sync.");
      return out;
    }
    if (enabled.isEmpty()) {
      out.add("No capabilities switched on, so there is nothing to sync.");
      return out;
    }
    List<String> syncing = new ArrayList<>(enabled);
    boolean collectionLog = syncing.remove("collection log");
    if (!syncing.isEmpty()) {
      out.add("Syncing " + String.join(", ", syncing) + " now.");
    }
    if (collectionLog) {
      out.add("The collection log is not included: it can only be read from the log's own Search.");
    }
    return out;
  }

  /** Coarse on purpose: more precision would imply more than we know. */
  static String describeAge(long millis) {
    long minutes = millis / 60_000L;
    if (minutes < 1) {
      return "less than a minute ago";
    }
    if (minutes == 1) {
      return "1 minute ago";
    }
    if (minutes < 60) {
      return minutes + " minutes ago";
    }
    long hours = minutes / 60;
    return hours == 1 ? "1 hour ago" : hours + " hours ago";
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Builds the v1 submit envelope. The shape is a frozen server contract, pinned by the
 * fixtures under src/test/resources/contracts.
 *
 * <p>Every block is omitted when empty: absent means "not observed", and the server
 * treats a present-but-empty block as an erase.
 */
public final class SubmitEnvelope {
  private SubmitEnvelope() {}

  public static final int SCHEMA_VERSION = 1;

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, null, null, null, null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, collectionLogItems, null, null, null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems,
      Map<String, Integer> combatAchievementCounts,
      Map<String, Integer> diaryTaskCounts,
      String accountType) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, collectionLogItems, combatAchievementCounts, diaryTaskCounts,
        accountType, false);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems,
      Map<String, Integer> combatAchievementCounts,
      Map<String, Integer> diaryTaskCounts,
      String accountType,
      boolean fullEnumeration) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, collectionLogItems, combatAchievementCounts, diaryTaskCounts,
        accountType, fullEnumeration, null);
  }

  /** Without the slayer task. */
  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems,
      Map<String, Integer> combatAchievementCounts,
      Map<String, Integer> diaryTaskCounts,
      String accountType,
      boolean fullEnumeration,
      Map<String, Integer> combatAchievementBossCounts) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, collectionLogItems, combatAchievementCounts, diaryTaskCounts,
        accountType, fullEnumeration, combatAchievementBossCounts, null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems,
      Map<String, Integer> combatAchievementCounts,
      Map<String, Integer> diaryTaskCounts,
      String accountType,
      boolean fullEnumeration,
      Map<String, Integer> combatAchievementBossCounts,
      Map<String, Object> slayerTask) {
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("submissionId", submissionId);
    body.put("schemaVersion", schemaVersion);
    body.put("pluginVersion", pluginVersion);
    body.put("capturedAt", capturedAt);
    body.put("accountHash", Long.toString(accountHash));
    if (displayName != null && !displayName.trim().isEmpty()) {
      body.put("displayName", displayName);
    }
    Map<String, Object> skills = new LinkedHashMap<>();
    for (Map.Entry<String, Integer> e : skillXp.entrySet()) {
      Map<String, Object> stat = new LinkedHashMap<>();
      stat.put("xp", e.getValue());
      skills.put(e.getKey(), stat);
    }
    body.put("skills", skills);
    if (questStates != null && !questStates.isEmpty()) {
      body.put("quests", new LinkedHashMap<>(questStates));
    }
    if (diaryStates != null && !diaryStates.isEmpty()) {
      body.put("diaries", new LinkedHashMap<>(diaryStates));
    }
    if (diaryTaskCounts != null && !diaryTaskCounts.isEmpty()) {
      body.put("diaryTasks", new LinkedHashMap<>(diaryTaskCounts));
    }
    if (collectionLogItems != null && !collectionLogItems.isEmpty()) {
      body.put("collectionLog", new ArrayList<>(collectionLogItems));
      // Only after a complete guided read (Search open). Never sent as false.
      if (fullEnumeration) {
        body.put("collectionLogFullyEnumerated", true);
      }
    }
    if (combatAchievementCounts != null && !combatAchievementCounts.isEmpty()) {
      body.put("combatAchievements", new LinkedHashMap<>(combatAchievementCounts));
    }
    if (combatAchievementBossCounts != null && !combatAchievementBossCounts.isEmpty()) {
      body.put("combatAchievementBossCounts", new LinkedHashMap<>(combatAchievementBossCounts));
    }
    // Null for an unknown varbit value: omit rather than send a wrong type.
    if (accountType != null && !accountType.isEmpty()) {
      body.put("accountType", accountType);
    }
    // {"active": false} is an observed state; absent means not read this time.
    if (slayerTask != null && !slayerTask.isEmpty()) {
      body.put("slayerTask", new LinkedHashMap<>(slayerTask));
    }
    return body;
  }
}

package com.bankstand;

/**
 * A failed submit. The message is generic and safe to show; never put the token or account hash
 * in it. {@link #isRetryable()} marks transient failures (network, 429, 5xx).
 */
public class SubmitException extends Exception {
  private final boolean retryable;
  private final boolean authFailure;
  private final long retryAfterMillis;

  public SubmitException(String message) {
    this(message, false);
  }

  public SubmitException(String message, boolean retryable) {
    this(message, retryable, false);
  }

  public SubmitException(String message, boolean retryable, boolean authFailure) {
    this(message, retryable, authFailure, 0L);
  }

  public SubmitException(
      String message, boolean retryable, boolean authFailure, long retryAfterMillis) {
    super(message);
    this.retryable = retryable;
    this.authFailure = authFailure;
    this.retryAfterMillis = retryAfterMillis;
  }

  public boolean isRetryable() {
    return retryable;
  }

  /** A rejected or revoked token (401/403): only re-pairing fixes it, so stop submitting. */
  public boolean isAuthFailure() {
    return authFailure;
  }

  /** A 429's {@code Retry-After}, or zero. */
  public long getRetryAfterMillis() {
    return retryAfterMillis;
  }
}

package com.bankstand;

/**
 * Decides whether a capture may submit: backs off across captures on failure and halts on a
 * revoked token until re-pairing. Counted in captures, the only clock it has.
 * Synchronized: executor callbacks write, the client thread reads.
 */
public class SubmitGate {

  /** About sixteen minutes at a sixty second capture. */
  public static final int MAX_SKIPPED_CAPTURES = 15;

  private boolean halted;
  private int consecutiveFailures;
  private int skipsRemaining;
  // Epoch millis before which nothing is sent: the server's Retry-After.
  private long pausedUntilMs;

  /** Consumes one skip when backing off. */
  public synchronized boolean allow() {
    if (halted || isPaused(System.currentTimeMillis())) {
      return false;
    }
    if (skipsRemaining > 0) {
      skipsRemaining--;
      return false;
    }
    return true;
  }

  /** Clears any backoff, but never the halt. */
  public synchronized void onSuccess() {
    consecutiveFailures = 0;
    skipsRemaining = 0;
  }

  /** Doubles the wait, to a cap. */
  public synchronized void onFailure() {
    consecutiveFailures++;
    skipsRemaining = Math.min(MAX_SKIPPED_CAPTURES, (1 << Math.min(consecutiveFailures, 5)) - 1);
  }

  /** A rejected or revoked token. Returns true only the first time, so it is announced once. */
  public synchronized boolean onAuthFailure() {
    boolean announce = !halted;
    halted = true;
    return announce;
  }

  /** A Retry-After: nothing is sent before it passes. Never shortens a longer pause. */
  public synchronized void pauseFor(long nowMs, long retryAfterMs) {
    pausedUntilMs = Math.max(pausedUntilMs, nowMs + retryAfterMs);
  }

  public synchronized boolean isPaused(long nowMs) {
    return nowMs < pausedUntilMs;
  }

  /** Called on re-pairing, the only thing that clears a halt. */
  public synchronized void resume() {
    halted = false;
    pausedUntilMs = 0;
    consecutiveFailures = 0;
    skipsRemaining = 0;
  }

  public synchronized boolean isHalted() {
    return halted;
  }
}

package com.bankstand;

import java.util.Map;
import java.util.Set;

/** Which blocks a capture puts on the wire. Skills is required, so it is not listed. */
final class SubmitPlan {
  private final boolean submit;
  private final boolean quests;
  private final boolean diaries;
  private final boolean collectionLog;
  private final boolean fullEnumeration;
  private final boolean combatAchievements;
  private final boolean accountType;
  private final boolean slayerTask;

  private SubmitPlan(
      boolean submit,
      boolean quests,
      boolean diaries,
      boolean collectionLog,
      boolean fullEnumeration,
      boolean combatAchievements,
      boolean accountType,
      boolean slayerTask) {
    this.submit = submit;
    this.quests = quests;
    this.diaries = diaries;
    this.collectionLog = collectionLog;
    this.fullEnumeration = fullEnumeration;
    this.combatAchievements = combatAchievements;
    this.accountType = accountType;
    this.slayerTask = slayerTask;
  }

  boolean shouldSubmit() {
    return submit;
  }

  boolean includesQuests() {
    return quests;
  }

  boolean includesDiaries() {
    return diaries;
  }

  boolean includesCollectionLog() {
    return collectionLog;
  }

  // True only when the flag rides on this submission's collection log block.
  boolean includesFullEnumeration() {
    return fullEnumeration;
  }

  boolean includesCombatAchievements() {
    return combatAchievements;
  }

  boolean includesAccountType() {
    return accountType;
  }

  boolean includesSlayerTask() {
    return slayerTask;
  }

  /**
   * Decides what this capture sends, per capability: a block rides along only when it changed
   * since the server last acknowledged it.
   *
   * <p>Whole blocks only, never a delta: the server merges blocks with jsonb {@code ||}, a
   * top-level replace, so a partial block would erase the fields it left out. An unacked block
   * has no baseline, so it keeps re-sending until stored. An empty block is never sent: absent
   * means "not observed", empty would assert the player has none. Null means the opt-in is off.
   */
  static SubmitPlan plan(
      SkillBaseline skillBaseline,
      Map<String, Integer> skills,
      QuestBaseline questBaseline,
      Map<String, String> quests,
      DiaryBaseline diaryBaseline,
      Map<String, String> diaries, Map<String, Integer> diaryTaskCounts,
      CollectionLogBaseline collectionLogBaseline,
      Set<Integer> collectionLogItems,
      CombatAchievementBaseline combatAchievementBaseline,
      Map<String, Integer> combatAchievements,
      AccountTypeBaseline accountTypeBaseline,
      String accountType,
      boolean fullEnumerationPending,
      SlayerTaskBaseline slayerTaskBaseline,
      SlayerTask slayerTask) {
    boolean sendQuests =
        quests != null && !quests.isEmpty() && questBaseline.changedSince(quests);
    boolean sendDiaries =
        diaries != null && !diaries.isEmpty() && diaryBaseline.changedSince(diaries, diaryTaskCounts);
    // The collection log counts toward the decision on its own. A pending full enumeration also
    // forces it, since a COMPLETE read can reveal no new ids. An empty log has no block to ride on.
    boolean sendCollectionLog =
        !collectionLogItems.isEmpty()
            && (collectionLogBaseline.changedSince(collectionLogItems.size())
                || fullEnumerationPending);
    boolean sendCombatAchievements =
        combatAchievements != null
            && !combatAchievements.isEmpty()
            && combatAchievementBaseline.changedSince(combatAchievements);
    // Counts on its own: the type rarely changes, so it must not wait on xp moving.
    boolean sendAccountType =
        accountType != null
            && !accountType.isEmpty()
            && accountTypeBaseline.changedSince(accountType);
    // On its own: a finished task must replace the stored one even with no xp change.
    boolean sendSlayerTask = slayerTaskBaseline.changedSince(slayerTask);
    boolean submit =
        skillBaseline.changedSince(skills)
            || sendQuests
            || sendDiaries
            || sendCollectionLog
            || sendCombatAchievements
            || sendAccountType
            || sendSlayerTask;
    return new SubmitPlan(
        submit,
        sendQuests,
        sendDiaries,
        sendCollectionLog,
        fullEnumerationPending && sendCollectionLog,
        sendCombatAchievements,
        sendAccountType,
        sendSlayerTask);
  }
}

package com.bankstand;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BiPredicate;

/**
 * The panel's failure line. Snapshot and event failures are kept apart, so one path's success
 * never hides the other's failure. A snapshot failure belongs to the login whose capture failed;
 * event failures are the device's, since one drain can carry several accounts. Set from HTTP
 * threads.
 */
final class SyncFailures {

  static final String FALLBACK = "Sync failed.";

  private final Runnable onChange;
  private final BiPredicate<Long, Integer> isCurrentLogin;
  // Written before snapshot, so a reader that sees the failure sees its login too.
  private volatile long snapshotAccount;
  private volatile int snapshotGeneration;
  private volatile String snapshot;
  private volatile String events;
  // An auth failure halts every account, so a switch keeps it.
  private volatile boolean snapshotAuth;
  // Bumped by clear(), so a drain from before a re-pair or disconnect writes nothing.
  private volatile int epoch;

  SyncFailures(Runnable onChange, BiPredicate<Long, Integer> isCurrentLogin) {
    this.onChange = onChange;
    this.isCurrentLogin = isCurrentLogin;
  }

  /** A failure with no message is still a failure. */
  static String reason(Throwable failure) {
    String message = failure.getMessage();
    return message == null ? FALLBACK : message;
  }

  void snapshotFailed(Throwable failure, long accountHash, int generation) {
    snapshotAccount = accountHash;
    snapshotGeneration = generation;
    snapshotAuth = failure instanceof SubmitException && ((SubmitException) failure).isAuthFailure();
    snapshot = reason(failure);
    onChange.run();
  }

  /** Clears only the same login's failure: another login's success says nothing about it. */
  void snapshotSucceeded(long accountHash, int generation) {
    if (snapshotAccount == accountHash && snapshotGeneration == generation) {
      snapshot = null;
    }
    onChange.run();
  }

  /** The previous account's snapshot failure is not the new one's. */
  void accountChanged() {
    if (!snapshotAuth) {
      snapshot = null;
    }
    onChange.run();
  }

  /** Pairing or disconnecting starts over. */
  void clear() {
    epoch++;
    snapshot = null;
    events = null;
  }

  boolean any() {
    return shown() != null;
  }

  /** The snapshot's failure first, otherwise the events'. */
  String shown() {
    String failed = snapshot;
    // An auth failure halts every account, so it shows whoever is logged in.
    boolean ours = snapshotAuth || isCurrentLogin.test(snapshotAccount, snapshotGeneration);
    return failed != null && ours ? failed : events;
  }

  Drain startDrain() {
    return new Drain();
  }

  /** One drain's chunks. */
  final class Drain {
    private final int startEpoch = epoch;
    private volatile String failed;

    void failed(Throwable failure) {
      if (failed == null) {
        failed = reason(failure);
      }
    }

    /** Records the outcome, then releases the flight. Clears only if every sent chunk succeeded. */
    void finish(int sentChunks, AtomicBoolean flight) {
      // A drain started under a pairing since replaced or removed says nothing about this one.
      if (startEpoch == epoch && failed != null) {
        events = failed;
      } else if (startEpoch == epoch && sentChunks > 0) {
        events = null;
      }
      flight.set(false);
      onChange.run();
    }
  }
}

