package com.bankstand.http;

import java.io.IOException;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** {@link HttpTransport} over RuneLite's shared OkHttpClient. */
public class OkHttpTransport implements HttpTransport {

  private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

  private final OkHttpClient client;

  @Inject
  public OkHttpTransport(OkHttpClient client) {
    this.client = noRedirects(client);
  }

  /**
   * A 3xx comes back as a response instead of being followed, so a bearer token or capture body
   * is never re-sent to wherever a server points it. Shares the shared client's pool.
   */
  static OkHttpClient noRedirects(OkHttpClient client) {
    return client.newBuilder().followRedirects(false).followSslRedirects(false).build();
  }

  @Override
  public HttpResponse post(String url, String jsonBody, Map<String, String> headers)
      throws IOException {
    return post(client, url, jsonBody, headers);
  }

  @Override
  public HttpResponse post(
      String url, String jsonBody, Map<String, String> headers, long timeoutMillis)
      throws IOException {
    OkHttpClient bounded =
        client.newBuilder().callTimeout(timeoutMillis, TimeUnit.MILLISECONDS).build();
    return post(bounded, url, jsonBody, headers);
  }

  private static HttpResponse post(
      OkHttpClient client, String url, String jsonBody, Map<String, String> headers)
      throws IOException {
    Request.Builder builder =
        new Request.Builder().url(url).post(RequestBody.create(JSON, jsonBody));
    for (Map.Entry<String, String> header : headers.entrySet()) {
      builder.header(header.getKey(), header.getValue());
    }
    try (Response response = client.newCall(builder.build()).execute()) {
      ResponseBody body = response.body();
      return new HttpResponse(
          response.code(), body != null ? body.string() : "", response.header("Retry-After"));
    }
  }

  @Override
  public HttpResponse get(String url, Map<String, String> headers) throws IOException {
    Request.Builder builder = new Request.Builder().url(url).get();
    for (Map.Entry<String, String> header : headers.entrySet()) {
      builder.header(header.getKey(), header.getValue());
    }
    try (Response response = client.newCall(builder.build()).execute()) {
      ResponseBody body = response.body();
      return new HttpResponse(response.code(), body != null ? body.string() : "");
    }
  }
}

package com.bankstand.session;

/**
 * Tracks the logged-in account across game-state changes. The logged-out sentinel is never
 * adopted or submitted, and no state carries across a change of account hash.
 */
public class AccountSession {

  /** RuneLite's {@code client.getAccountHash()} returns this when logged out. */
  public static final long LOGGED_OUT = -1L;

  // Volatile: written on the client thread, read on the submit executor, and vice versa.
  private volatile long accountHash = LOGGED_OUT;
  private volatile int generation = 0;
  private volatile boolean submitted = false;

  public long getAccountHash() {
    return accountHash;
  }

  public boolean isActive() {
    return accountHash != LOGGED_OUT;
  }

  /**
   * Bumped on every session change (switch, logout, relog). A submit captures it at dispatch so a
   * stale result is dropped via {@link #isCurrent}.
   */
  public int getGeneration() {
    return generation;
  }

  /** True when {@code hash}/{@code gen} still identify the current login. */
  public boolean isCurrent(long hash, int gen) {
    return isActive() && accountHash == hash && generation == gen;
  }

  /** True while this account's identity submit is in flight or has succeeded. */
  public boolean isSubmitted() {
    return submitted;
  }

  /**
   * Marks a submit in flight so the next tick does not fire a second one. In flight, not done: a
   * failure must clear it via {@link #markSubmitFailed} so it can be retried.
   */
  public void markSubmitInFlight() {
    submitted = true;
  }

  /**
   * Allows a retry after a failed submit, only if the same login is still current.
   */
  public void markSubmitFailed(long hash, int gen) {
    if (isCurrent(hash, gen)) {
      submitted = false;
    }
  }

  /**
   * Starts a fresh session for a new hash and returns true. The logged-out sentinel and the
   * current hash are no-ops.
   */
  public boolean onLogin(long hash) {
    if (hash == LOGGED_OUT || hash == accountHash) {
      return false;
    }
    reset();
    accountHash = hash;
    submitted = false;
    generation++;
    return true;
  }

  /** Clears the session on logout. The device token is account-independent and kept. */
  public void onLogout() {
    reset();
    accountHash = LOGGED_OUT;
    submitted = false;
    generation++;
  }

  private void reset() {
    // Hook point: clear any per-account cache here so data never leaks across accounts.
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

/** The account type changes once if ever, so a missed ack here never self-heals. */
public class AccountTypeCaptureTest {

  private static final Set<Integer> NO_LOG = Collections.emptySet();

  private static Map<String, Integer> skills(int xp) {
    Map<String, Integer> map = new LinkedHashMap<>();
    map.put("attack", xp);
    return map;
  }

  private static SubmitPlan planWith(
      AccountTypeBaseline baseline, String accountType) {
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills(100));
    return TestPlans.plan(
        skillBaseline,
        skills(100),
        new QuestBaseline(),
        null,
        new DiaryBaseline(),
        null,
        new CollectionLogBaseline(),
        NO_LOG,
        new CombatAchievementBaseline(),
        null,
        baseline,
        accountType);
  }

  @Test
  public void submitsOnTheTypeAloneWhenNothingElseMoved() {
    // Must submit on its own; the type never changes after login.
    SubmitPlan plan = planWith(new AccountTypeBaseline(), "group");

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesAccountType());
  }

  @Test
  public void staysQuietOnceTheServerHasAcknowledgedIt() {
    AccountTypeBaseline acked = new AccountTypeBaseline();
    acked.advance("group");

    SubmitPlan plan = planWith(acked, "group");

    assertFalse(plan.shouldSubmit());
    assertFalse(plan.includesAccountType());
  }

  @Test
  public void sendsAgainWhenTheAnswerChanges() {
    AccountTypeBaseline acked = new AccountTypeBaseline();
    acked.advance("hardcore");

    SubmitPlan plan = planWith(acked, "ironman");

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesAccountType());
  }

  @Test
  public void sendsNothingWhenTheGameNamedNoType() {
    // Null means "not observed", which is no reason to submit.
    assertFalse(planWith(new AccountTypeBaseline(), null).shouldSubmit());
    assertFalse(planWith(new AccountTypeBaseline(), "").shouldSubmit());
  }

  @Test
  public void advancesOnlyOnThisBlocksOwnAcknowledgement() {
    // The whole-submission verdict can read stored while this block was dropped; advancing
    // on it would lose the fact for good.
    assertTrue(
        BankstandPlugin.shouldAdvanceAccountType(response("persisted", true, "accountType"), true));
    assertFalse(
        BankstandPlugin.shouldAdvanceAccountType(response("persisted", true, "skills"), true));
  }

  @Test
  public void neverAdvancesForABlockItDidNotSend() {
    assertFalse(
        BankstandPlugin.shouldAdvanceAccountType(
            response("persisted", true, "accountType"), false));
  }

  @Test
  public void survivesARestartThroughTheAckedState() {
    // Without this the client resends the same word forever.
    AccountTypeBaseline baseline = new AccountTypeBaseline();
    baseline.advance("unranked_group");

    AckedState state = new AckedState();
    state.setAccountType(baseline.ackedValue());

    AccountTypeBaseline restored = new AccountTypeBaseline();
    restored.restore(state.getAccountType());

    assertEquals("unranked_group", restored.ackedValue());
    assertFalse(restored.changedSince("unranked_group"));
  }

  @Test
  public void forgetsTheTypeOnAnAccountSwitch() {
    // A type belongs to one character.
    AccountTypeBaseline baseline = new AccountTypeBaseline();
    baseline.advance("ironman");
    baseline.reset();

    assertTrue(baseline.changedSince("group"));
    assertEquals(null, baseline.ackedValue());
  }

  private static com.bankstand.dto.SubmitSnapshotResponse response(
      String reason, boolean stored, String... blocks) {
    return new com.google.gson.Gson()
        .fromJson(
            "{\"accepted\":true,\"stored\":"
                + stored
                + ",\"reason\":\""
                + reason
                + "\",\"storedBlocks\":[\""
                + String.join("\",\"", blocks)
                + "\"]}",
            com.bankstand.dto.SubmitSnapshotResponse.class);
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import net.runelite.api.vars.AccountType;
import org.junit.Test;

/**
 * Joins against RuneLite's deprecated {@code AccountType} on purpose: it is the authoritative
 * ordinal table, and removal fails compilation. Plugin code reads the varbit, not the enum.
 */
@SuppressWarnings("deprecation")
public class AccountTypesTest {

  @Test
  public void readsTheVarbitRuneliteNames() {
    assertEquals(1777, AccountTypes.ACCOUNT_TYPE_VARBIT);
  }

  @Test
  public void mapsEveryValueRuneliteKnowsAbout() {
    // The varbit value is the ordinal of RuneLite's enum, so an inserted member is caught here.
    assertEquals("regular", AccountTypes.keyFor(AccountType.NORMAL.ordinal()));
    assertEquals("ironman", AccountTypes.keyFor(AccountType.IRONMAN.ordinal()));
    assertEquals("ultimate", AccountTypes.keyFor(AccountType.ULTIMATE_IRONMAN.ordinal()));
    assertEquals("hardcore", AccountTypes.keyFor(AccountType.HARDCORE_IRONMAN.ordinal()));
    assertEquals("group", AccountTypes.keyFor(AccountType.GROUP_IRONMAN.ordinal()));
    assertEquals(
        "hardcore_group", AccountTypes.keyFor(AccountType.HARDCORE_GROUP_IRONMAN.ordinal()));
  }

  @Test
  public void coversEveryMemberRuneliteDeclares() {
    for (AccountType type : AccountType.values()) {
      assertTrue(type.name(), AccountTypes.keyFor(type.ordinal()) != null);
    }
  }

  @Test
  public void mapsTheUnrankedGroupIronmanRuneliteDoesNotDeclare() {
    // Measured on a real account: unranked group ironman reports 6, past RuneLite's enum.
    assertEquals(
        "hardcore_group", AccountTypes.keyFor(AccountType.HARDCORE_GROUP_IRONMAN.ordinal()));
    assertEquals("unranked_group", AccountTypes.keyFor(6));
  }

  @Test
  public void refusesToGuessAnUnknownValue() {
    // Not a fallback to "regular": an unknown mode must not become a confident wrong answer.
    assertNull(AccountTypes.keyFor(7));
    assertNull(AccountTypes.keyFor(99));
    assertNull(AccountTypes.keyFor(-1));
  }

  @Test
  public void showsTheRawValueSoAnUnknownCanBeReported() {
    // VarInspector logs changes only and 1777 never changes in a session, so this is the
    // only way to see what an account reports.
    assertTrue(AccountTypes.describe(4).contains("group"));
    assertTrue(AccountTypes.describe(4).contains("1777"));
    assertTrue(AccountTypes.describe(4).contains("4"));

    String unknown = AccountTypes.describe(7);
    assertTrue(unknown.contains("unrecognised"));
    assertTrue(unknown.contains("7"));
    assertTrue(unknown.contains("report"));
  }

  @Test
  public void neverClaimsToVerifyOwnership() {
    // The plugin proves a connection, not ownership, so no status line says "verified".
    for (int value = -1; value <= 7; value++) {
      String line = AccountTypes.describe(value).toLowerCase(java.util.Locale.ROOT);
      assertTrue(line, !line.contains("verified"));
      assertTrue(line, !line.contains("confirmed"));
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** A client restart must not re-send what the server already took, nor forget the log. */
public class AckedStateRestartTest {

  private static final long ACCOUNT = 4_242L;

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private File file;

  @Before
  public void setUp() {
    file = new File(folder.getRoot(), "acked-state.json");
  }

  private static class Client {
    final SkillBaseline skills = new SkillBaseline();
    final QuestBaseline quests = new QuestBaseline();
    final DiaryBaseline diaries = new DiaryBaseline();
    final CollectionLogAccumulator log = new CollectionLogAccumulator();
    final CollectionLogBaseline logBaseline = new CollectionLogBaseline();

    SubmitPlan plan(
        Map<String, Integer> s, Map<String, String> q, Map<String, String> d) {
      return TestPlans.plan(skills, s, quests, q, diaries, d, logBaseline, log.observed());
    }

    void ackAll(Map<String, Integer> s, Map<String, String> q, Map<String, String> d) {
      skills.advance(s);
      quests.advance(q);
      diaries.advance(d);
      logBaseline.advance(log.size());
    }

    void save(AckedStateStore store) {
      AckedState state = AckedState.empty();
      state.setSkills(skills.ackedDigest());
      state.setQuests(quests.ackedDigest());
      state.setDiaries(diaries.ackedDigest());
      state.setCollectionLogItems(log.observed());
      state.setCollectionLogAcked(logBaseline.ackedCount());
      store.save(ACCOUNT, state);
    }

    void restore(AckedStateStore store) {
      AckedState state = store.load(ACCOUNT);
      skills.restore(state.getSkills());
      quests.restore(state.getQuests());
      diaries.restore(state.getDiaries());
      log.restore(state.getCollectionLogItems());
      logBaseline.restore(state.getCollectionLogAcked());
    }
  }

  private static Map<String, Integer> skills(int attackXp) {
    Map<String, Integer> m = new LinkedHashMap<>();
    m.put("attack", attackXp);
    m.put("cooking", 500);
    return m;
  }

  private static Map<String, String> quests(String state) {
    Map<String, String> m = new LinkedHashMap<>();
    m.put("COOKS_ASSISTANT", state);
    return m;
  }

  private static Map<String, String> diaries() {
    Map<String, String> m = new LinkedHashMap<>();
    m.put("VARROCK_EASY", "COMPLETE");
    return m;
  }

  private static Set<Integer> wholeLog() {
    Set<Integer> ids = new LinkedHashSet<>();
    for (int i = 1; i <= 1700; i++) {
      ids.add(i);
    }
    return ids;
  }

  private AckedStateStore store() {
    return new AckedStateStore(file, new Gson());
  }

  /** A restart must not re-send every block once. */
  @Test
  public void aRestartWithNothingChangedSendsNothing() {
    Client first = new Client();
    first.log.restore(wholeLog());
    first.ackAll(skills(100), quests("FINISHED"), diaries());
    first.save(store());

    Client afterRestart = new Client();
    afterRestart.log.restore(wholeLog());
    afterRestart.restore(store());

    assertFalse(afterRestart.plan(skills(100), quests("FINISHED"), diaries()).shouldSubmit());
  }

  @Test
  public void aRestartStillSendsWhatActuallyChangedWhileAway() {
    Client first = new Client();
    first.ackAll(skills(100), quests("FINISHED"), diaries());
    first.save(store());

    Client afterRestart = new Client();
    afterRestart.restore(store());
    SubmitPlan plan =
        afterRestart.plan(skills(999), quests("FINISHED"), diaries());

    assertTrue(plan.shouldSubmit());
    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
  }

  @Test
  public void aRestartRemembersTheCollectionLogItself() {
    Client first = new Client();
    first.log.restore(wholeLog());
    first.ackAll(skills(100), quests("FINISHED"), diaries());
    first.save(store());

    Client afterRestart = new Client();
    afterRestart.restore(store());

    assertEquals(1700, afterRestart.log.size());
  }

  /**
   * The count gate only holds over a growing observed set, so the count and the accumulator
   * must be restored together.
   */
  @Test
  public void restoringTheCountWithoutTheAccumulatorWouldChurn() {
    Client first = new Client();
    first.log.restore(wholeLog());
    first.ackAll(skills(100), quests("FINISHED"), diaries());
    first.save(store());

    // Baseline restored, accumulator left empty.
    Client broken = new Client();
    broken.logBaseline.restore(store().load(ACCOUNT).getCollectionLogAcked());
    for (int id = 1; id <= 30; id++) {
      broken.log.observe(id);
    }
    assertTrue(broken.plan(skills(100), quests("FINISHED"), diaries()).includesCollectionLog());

    Client correct = new Client();
    correct.restore(store());
    for (int id = 1; id <= 30; id++) {
      correct.log.observe(id);
    }
    assertFalse(correct.plan(skills(100), quests("FINISHED"), diaries()).includesCollectionLog());
  }

  @Test
  public void aLogThatGrowsAfterARestartIsSentWhole() {
    Client first = new Client();
    first.log.restore(wholeLog());
    first.ackAll(skills(100), quests("FINISHED"), diaries());
    first.save(store());

    Client afterRestart = new Client();
    afterRestart.restore(store());
    afterRestart.log.observe(9001);

    assertTrue(
        afterRestart.plan(skills(100), quests("FINISHED"), diaries()).includesCollectionLog());
    assertEquals(1701, afterRestart.log.size());
  }

  /** The acked count is stored, not derived from the accumulator, so an unsent log still sends. */
  @Test
  public void aLogWhoseSubmitFailedIsStillSentAfterARestart() {
    Client first = new Client();
    first.log.restore(wholeLog());
    first.skills.advance(skills(100));
    first.quests.advance(quests("FINISHED"));
    first.diaries.advance(diaries());
    first.save(store());

    Client afterRestart = new Client();
    afterRestart.restore(store());

    assertTrue(
        afterRestart.plan(skills(100), quests("FINISHED"), diaries()).includesCollectionLog());
  }

  @Test
  public void anUnreadableFileCostsOneResendAndNothingMore() throws IOException {
    Client first = new Client();
    first.log.restore(wholeLog());
    first.ackAll(skills(100), quests("FINISHED"), diaries());
    first.save(store());
    java.nio.file.Files.write(file.toPath(), "corrupt".getBytes(java.nio.charset.StandardCharsets.UTF_8));

    Client afterRestart = new Client();
    afterRestart.restore(store());

    // Everything reads as changed: the safe direction.
    assertTrue(afterRestart.plan(skills(100), quests("FINISHED"), diaries()).shouldSubmit());
  }

  @Test
  public void anotherCharacterOnTheSameMachineIsUnaffected() {
    Client first = new Client();
    first.log.restore(wholeLog());
    first.ackAll(skills(100), quests("FINISHED"), diaries());
    first.save(store());

    AckedState other = store().load(9_999L);

    assertTrue(other.getCollectionLogItems().isEmpty());
    assertEquals(-1, other.getCollectionLogAcked());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class AckedStateStoreTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private File file;
  private AckedStateStore store;

  @Before
  public void setUp() throws IOException {
    file = new File(folder.getRoot(), "acked.json");
    store = new AckedStateStore(file, new Gson());
  }

  private static Set<Integer> ids(Integer... values) {
    return new LinkedHashSet<>(Arrays.asList(values));
  }

  @Test
  public void aCharacterNothingIsKnownAboutReadsAsEmpty() {
    AckedState state = store.load(1234L);

    assertNull(state.getSkills());
    assertTrue(state.getCollectionLogItems().isEmpty());
    // Not zero: zero would claim the server acknowledged an empty log.
    assertEquals(-1, state.getCollectionLogAcked());
  }

  @Test
  public void survivesARoundTrip() {
    AckedState state = AckedState.empty();
    state.setSkills("skills-digest");
    state.setQuests("quests-digest");
    state.setDiaries("diaries-digest");
    state.setAccountType("ironman");
    state.setCollectionLogItems(ids(1, 2, 3));
    state.setCollectionLogAcked(3);
    Map<String, Long> synced = new LinkedHashMap<>();
    synced.put("skills", 1_700_000_000_000L);
    state.setLastSyncedAt(synced);

    store.save(1234L, state);
    AckedState loaded = new AckedStateStore(file, new Gson()).load(1234L);

    assertEquals("skills-digest", loaded.getSkills());
    assertEquals("quests-digest", loaded.getQuests());
    assertEquals("diaries-digest", loaded.getDiaries());
    assertEquals("ironman", loaded.getAccountType());
    assertEquals(ids(1, 2, 3), loaded.getCollectionLogItems());
    assertEquals(3, loaded.getCollectionLogAcked());
    assertEquals(1_700_000_000_000L, (long) loaded.getLastSyncedAt().get("skills"));
  }

  /** An older document has no such field at all; the store must still return an empty map. */
  @Test
  public void aDocumentMissingLastSyncedAtStillLoads() throws IOException {
    Files.write(
        file.toPath(),
        "{\"accounts\":{\"1234\":{\"skills\":\"only-skills\"}}}".getBytes(StandardCharsets.UTF_8));

    AckedState state = new AckedStateStore(file, new Gson()).load(1234L);

    assertTrue(state.getLastSyncedAt().isEmpty());
  }

  /** Two characters on one machine must not see each other's baselines. */
  @Test
  public void keepsCharactersApart() {
    AckedState first = AckedState.empty();
    first.setSkills("first");
    first.setCollectionLogItems(ids(1, 2));
    AckedState second = AckedState.empty();
    second.setSkills("second");
    second.setCollectionLogItems(ids(9));

    store.save(1L, first);
    store.save(2L, second);

    assertEquals("first", store.load(1L).getSkills());
    assertEquals(ids(1, 2), store.load(1L).getCollectionLogItems());
    assertEquals("second", store.load(2L).getSkills());
    assertEquals(ids(9), store.load(2L).getCollectionLogItems());
  }

  @Test
  public void savingOneCharacterLeavesTheOtherAlone() {
    AckedState first = AckedState.empty();
    first.setSkills("first");
    store.save(1L, first);

    AckedState second = AckedState.empty();
    second.setSkills("second");
    store.save(2L, second);

    assertEquals("first", new AckedStateStore(file, new Gson()).load(1L).getSkills());
  }

  @Test
  public void aNegativeAccountHashIsARealAccount() {
    // The account hash is a signed 64-bit value and can be negative.
    AckedState state = AckedState.empty();
    state.setSkills("negative");

    store.save(-8_234_567_890_123L, state);

    assertEquals("negative", new AckedStateStore(file, new Gson()).load(-8_234_567_890_123L).getSkills());
  }

  /** An unreadable file means "send everything again", the cheapest safe answer. */
  @Test
  public void treatsAnUnreadableFileAsEmptyRatherThanFailing() throws IOException {
    Files.write(file.toPath(), "{ this is not json".getBytes(StandardCharsets.UTF_8));

    AckedState state = new AckedStateStore(file, new Gson()).load(1234L);

    assertNull(state.getSkills());
    assertEquals(-1, state.getCollectionLogAcked());
  }

  @Test
  public void recoversByOverwritingACorruptFileOnTheNextSave() throws IOException {
    Files.write(file.toPath(), "not json at all".getBytes(StandardCharsets.UTF_8));
    AckedStateStore fresh = new AckedStateStore(file, new Gson());

    AckedState state = AckedState.empty();
    state.setSkills("recovered");
    fresh.save(1234L, state);

    assertEquals("recovered", new AckedStateStore(file, new Gson()).load(1234L).getSkills());
  }

  @Test
  public void aDocumentMissingItsCollectionLogFieldsStillLoads() throws IOException {
    Files.write(
        file.toPath(),
        "{\"accounts\":{\"1234\":{\"skills\":\"only-skills\"}}}".getBytes(StandardCharsets.UTF_8));

    AckedState state = new AckedStateStore(file, new Gson()).load(1234L);

    assertEquals("only-skills", state.getSkills());
    assertTrue(state.getCollectionLogItems().isEmpty());
  }

  @Test
  public void leavesNoTemporaryFileBehind() {
    store.save(1L, AckedState.empty());

    String[] names = folder.getRoot().list();
    assertEquals(1, names.length);
    assertEquals("acked.json", names[0]);
  }

  @Test
  public void createsTheParentDirectoryOnFirstSave() {
    File nested = new File(new File(folder.getRoot(), "bankstand"), "acked.json");
    AckedState state = AckedState.empty();
    state.setSkills("nested");

    new AckedStateStore(nested, new Gson()).save(7L, state);

    assertTrue(nested.exists());
    assertEquals("nested", new AckedStateStore(nested, new Gson()).load(7L).getSkills());
  }

  @Test
  public void handsOutStateTheCallerCannotAliasIntoTheStore() {
    AckedState state = AckedState.empty();
    state.setCollectionLogItems(ids(1, 2));
    store.save(1L, state);

    AckedState loaded = store.load(1L);
    loaded.getCollectionLogItems().add(999);

    assertEquals(ids(1, 2), store.load(1L).getCollectionLogItems());
  }

  @Test
  public void aSavedDigestReplacesTheOneBefore() {
    AckedState first = AckedState.empty();
    first.setSkills("old");
    store.save(1L, first);

    AckedState second = AckedState.empty();
    second.setSkills("new");
    store.save(1L, second);

    assertEquals("new", store.load(1L).getSkills());
    assertNotEquals("old", store.load(1L).getSkills());
  }

  @Test
  public void aSaveDuringATransientReadErrorKeepsEveryOtherCharacter() throws Exception {
    java.io.File file = new java.io.File(folder.newFolder(), "acked.json");
    AckedStateStore store = new AckedStateStore(file, new com.google.gson.Gson());
    AckedState other = AckedState.empty();
    other.setQuests("other-digest");
    store.save(77L, other);

    org.junit.Assume.assumeTrue(file.setReadable(false) && !file.canRead());
    AckedState mine = AckedState.empty();
    mine.setQuests("mine-digest");
    try {
      store.save(42L, mine);
      assertEquals("held for this session", "mine-digest", store.load(42L).getQuests());
    } finally {
      file.setReadable(true);
    }
    assertEquals("other-digest", store.load(77L).getQuests());
    assertEquals("merged once readable", "mine-digest", store.load(42L).getQuests());
    assertEquals(
        "and written", "mine-digest",
        new AckedStateStore(file, new com.google.gson.Gson()).load(42L).getQuests());
  }

  @Test
  public void aHeldSaveSurvivesAFailedWrite() throws Exception {
    java.io.File dir = folder.newFolder();
    java.io.File file = new java.io.File(dir, "acked.json");
    AckedStateStore store = new AckedStateStore(file, new com.google.gson.Gson());
    store.save(77L, AckedState.empty());
    AckedState mine = AckedState.empty();
    mine.setQuests("mine-digest");
    org.junit.Assume.assumeTrue(file.setReadable(false) && !file.canRead());
    try {
      store.save(42L, mine);
    } finally {
      file.setReadable(true);
    }
    org.junit.Assume.assumeTrue(dir.setWritable(false));
    try {
      store.load(77L);
      assertEquals("still held after the failed write", "mine-digest", store.load(42L).getQuests());
    } finally {
      dir.setWritable(true);
    }
    store.load(77L);
    assertEquals(
        "mine-digest", new AckedStateStore(file, new com.google.gson.Gson()).load(42L).getQuests());
  }
}

