package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class BackoffTest {

  @Test
  public void doublesTheWindowEachAttempt() {
    assertEquals(500L, BankstandClient.backoffMillis(1, 1000L, 0.5));
    assertEquals(1000L, BankstandClient.backoffMillis(2, 1000L, 0.5));
    assertEquals(2000L, BankstandClient.backoffMillis(3, 1000L, 0.5));
  }

  @Test
  public void picksFromZeroUpToTheWindow() {
    assertEquals(0L, BankstandClient.backoffMillis(3, 1000L, 0.0));
    assertEquals(2000L, BankstandClient.backoffMillis(3, 1000L, 0.5));
  }

  @Test
  public void neverWaitsPastTheCap() {
    for (int attempt = 1; attempt <= 20; attempt++) {
      assertTrue(
          BankstandClient.backoffMillis(attempt, 1000L, 0.999999)
              <= BankstandClient.MAX_BACKOFF_MILLIS);
    }
  }

  /** The cap is on the window, not the draw, so late attempts stay spread out. */
  @Test
  public void aCappedAttemptStillJitters() {
    assertEquals(0L, BankstandClient.backoffMillis(20, 1000L, 0.0));
    assertEquals(
        BankstandClient.MAX_BACKOFF_MILLIS / 2, BankstandClient.backoffMillis(20, 1000L, 0.5));
  }

  @Test
  public void aZeroBaseNeverWaits() {
    assertEquals(0L, BankstandClient.backoffMillis(4, 0L, 0.999999));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.bankstand.dto.PairResponse;
import com.bankstand.dto.SubmitEventsResponse;
import com.bankstand.dto.SubmitResponse;
import com.bankstand.dto.SubmitSnapshotResponse;
import com.bankstand.http.HttpResponse;
import com.bankstand.http.HttpTransport;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class BankstandClientTest {

  private static final String BASE = "https://example.test";

  private static final class FakeTransport implements HttpTransport {
    String url;
    String body;
    Map<String, String> headers;
    boolean called;
    long timeoutMillis;
    private final HttpResponse response;
    private final IOException toThrow;

    FakeTransport(HttpResponse response) {
      this(response, null);
    }

    FakeTransport(HttpResponse response, IOException toThrow) {
      this.response = response;
      this.toThrow = toThrow;
    }

    @Override
    public HttpResponse post(String url, String jsonBody, Map<String, String> headers)
        throws IOException {
      this.called = true;
      this.url = url;
      this.body = jsonBody;
      this.headers = headers;
      if (toThrow != null) {
        throw toThrow;
      }
      return response;
    }

    @Override
    public HttpResponse post(
        String url, String jsonBody, Map<String, String> headers, long timeoutMillis)
        throws IOException {
      this.timeoutMillis = timeoutMillis;
      return post(url, jsonBody, headers);
    }

    @Override
    public HttpResponse get(String url, Map<String, String> headers) throws IOException {
      this.called = true;
      this.url = url;
      this.headers = headers;
      if (toThrow != null) {
        throw toThrow;
      }
      return response;
    }
  }

  private static final class SequencedTransport implements HttpTransport {
    private final java.util.Deque<Object> steps = new java.util.ArrayDeque<>();
    int calls;

    SequencedTransport(Object... steps) {
      java.util.Collections.addAll(this.steps, steps);
    }

    @Override
    public HttpResponse get(String url, Map<String, String> headers) throws IOException {
      return post(url, "", headers);
    }

    @Override
    public HttpResponse post(String url, String jsonBody, Map<String, String> headers)
        throws IOException {
      calls++;
      Object step = steps.isEmpty() ? null : steps.poll();
      if (step instanceof IOException) {
        throw (IOException) step;
      }
      if (step instanceof HttpResponse) {
        return (HttpResponse) step;
      }
      throw new IllegalStateException("no scripted response for call " + calls);
    }
  }

  // Real scheduling for the retry tests; every test uses a zero base delay.
  private static final ScheduledExecutorService EXECUTOR = Executors.newSingleThreadScheduledExecutor();

  private static final long GET_TIMEOUT_SECONDS = 5;

  private static BankstandClient client(FakeTransport transport) {
    return new BankstandClient(transport, new Gson(), EXECUTOR);
  }

  private static SubmitException unwrapSubmitException(ExecutionException e) {
    return (SubmitException) e.getCause();
  }

  @Test
  public void pairsOnSuccessAndSendsTheNormalizedCode() throws Exception {
    FakeTransport t =
        new FakeTransport(
            new HttpResponse(
                200,
                "{\"deviceToken\":\"bsd_abc\",\"deviceId\":\"d1\","
                    + "\"expiresAt\":\"2026-10-01T00:00:00.000Z\"}"));

    PairResponse res = client(t).exchangePairingCode(BASE + "/", "abcd-efgh");

    assertEquals("bsd_abc", res.getDeviceToken());
    assertEquals("d1", res.getDeviceId());
    assertEquals("2026-10-01T00:00:00.000Z", res.getExpiresAt());
    assertEquals(BASE + "/api/plugin/v1/pair", t.url); // trailing slash trimmed
    assertTrue("normalized code in body", t.body.contains("\"ABCDEFGH\""));
    assertEquals("application/json", t.headers.get("Content-Type"));
    assertTrue(t.headers.get("User-Agent").matches("bankstand-runelite/\\d+\\.\\d+\\.\\d+"));
  }

  @Test
  public void rejectsAnInvalidCodeBeforeAnyRequest() {
    FakeTransport t = new FakeTransport(new HttpResponse(200, "{}"));
