package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Map;
import java.util.function.BooleanSupplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class CaptureGateTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  // Main-game worlds. Every other flag, including one added later, is skipped.
  private static final EnumSet<WorldType> ALLOWED =
      EnumSet.of(
          WorldType.MEMBERS,
          WorldType.PVP,
          WorldType.BOUNTY,
          WorldType.SKILL_TOTAL,
          WorldType.HIGH_RISK,
          WorldType.LEGACY_ONLY,
          WorldType.EOC_ONLY);

  private static boolean skipped(WorldType type) {
    return !ALLOWED.contains(type);
  }

  private static CaptureGate settled() {
    CaptureGate gate = new CaptureGate();
    for (int i = 0; i < CaptureGate.SETTLE_TICKS; i++) {
      gate.onTick(false);
    }
    return gate;
  }

  /** A plugin whose client reports {@code world} and whose login has settled. */
  private static BankstandPlugin pluginOn(EnumSet<WorldType> world) throws Exception {
    return pluginOn(world, new int[] {12850});
  }

  private static BankstandPlugin pluginOn(EnumSet<WorldType> world, int[] regions)
      throws Exception {
    Client client =
        (Client)
            Proxy.newProxyInstance(
                Client.class.getClassLoader(),
                new Class<?>[] {Client.class},
                (proxy, method, args) -> {
                  switch (method.getName()) {
                    case "getWorldType":
                      return world;
                    case "getAccountHash":
                      return 42L;
                    case "getMapRegions":
                      return regions;
                    default:
                      return method.getReturnType() == boolean.class ? false : null;
                  }
                });
    BankstandPlugin plugin = new BankstandPlugin();
    Field clientField = BankstandPlugin.class.getDeclaredField("client");
    clientField.setAccessible(true);
    clientField.set(plugin, client);
    Field gateField = BankstandPlugin.class.getDeclaredField("captureGate");
    gateField.setAccessible(true);
    gateField.set(plugin, settled());
    return plugin;
  }

  @Test
  public void allowsExactlyTheMainWorlds() {
    assertEquals(ALLOWED, EnumSet.copyOf(CaptureGate.MAIN_WORLDS));
    for (WorldType type : WorldType.values()) {
      assertEquals(type.name(), !skipped(type), CaptureGate.allowsWorld(EnumSet.of(type)));
    }
  }

  @Test
  public void keepsFreeAndOrdinaryWorlds() {
    assertTrue(CaptureGate.allowsWorld(EnumSet.noneOf(WorldType.class)));
    assertTrue(CaptureGate.allowsWorld(EnumSet.of(WorldType.MEMBERS, WorldType.PVP)));
    assertTrue(CaptureGate.allowsWorld(EnumSet.of(WorldType.MEMBERS, WorldType.SKILL_TOTAL)));
  }

  /** Separate saves, or a mode this build does not know: fail closed. */
  @Test
  public void skipsSpecialAndUnknownModes() {
    assertFalse(CaptureGate.allowsWorld(EnumSet.of(WorldType.LAST_MAN_STANDING)));
    assertFalse(CaptureGate.allowsWorld(EnumSet.of(WorldType.FRESH_START_WORLD)));
    assertFalse(CaptureGate.allowsWorld(EnumSet.of(WorldType.MEMBERS, WorldType.HARDCORE_MAIN)));
  }

  /** A Last Man Standing game runs on a normal world with a temporary loadout. */
  @Test
  public void aLastManStandingGameBlocksEveryCapture() throws Exception {
    BankstandPlugin inGame = pluginOn(EnumSet.of(WorldType.MEMBERS), new int[] {12850, 13658});
    assertFalse(inGame.isCaptureReady());
    assertFalse(inGame.gated(() -> true).getAsBoolean());

    BankstandPlugin outside = pluginOn(EnumSet.of(WorldType.MEMBERS), new int[] {12850});
    assertTrue(outside.isCaptureReady());
    assertTrue(pluginOn(EnumSet.of(WorldType.MEMBERS), null).isCaptureReady());
  }

  @Test
  public void aSkippedFlagWinsAlongsideOthers() {
    assertFalse(CaptureGate.allowsWorld(EnumSet.of(WorldType.MEMBERS, WorldType.SEASONAL)));
  }

  @Test
  public void anUnknownWorldIsNotAllowed() {
    assertFalse(CaptureGate.allowsWorld(null));
  }

  @Test
  public void waitsForTheWelcomeScreenThenAFewTicks() {
    CaptureGate gate = new CaptureGate();
    gate.onTick(true);
    gate.onTick(true);
    assertFalse(gate.isSettled());
    for (int i = 0; i < CaptureGate.SETTLE_TICKS - 1; i++) {
      gate.onTick(false);
      assertFalse(gate.isSettled());
    }
    gate.onTick(false);
    assertTrue(gate.isSettled());
  }

  @Test
  public void theWelcomeScreenReopeningRestartsTheSettle() {
    CaptureGate gate = settled();
    gate.onTick(true);
    assertFalse(gate.isSettled());
  }

  @Test
  public void resetWaitsForAFreshSettle() {
    CaptureGate gate = settled();
    gate.reset();
    assertFalse(gate.allows(EnumSet.noneOf(WorldType.class), null));
  }

  @Test
  public void anUnsettledLoginBlocksEvenAMainWorld() throws Exception {
    BankstandPlugin plugin = pluginOn(EnumSet.of(WorldType.MEMBERS));
    Field gateField = BankstandPlugin.class.getDeclaredField("captureGate");
    gateField.setAccessible(true);
    gateField.set(plugin, new CaptureGate());

    assertFalse(plugin.isCaptureReady());
    assertFalse(plugin.gated(() -> true).getAsBoolean());
  }

  /** The scheduled, logout and identity reads use isCaptureReady; event captures use gated. */
  @Test
  public void everyGateFollowsTheWorldCheckForEveryType() throws Exception {
    for (WorldType type : WorldType.values()) {
      BankstandPlugin plugin = pluginOn(EnumSet.of(type));
      boolean allowed = !skipped(type);
      assertEquals(type.name(), allowed, plugin.isCaptureReady());
      assertEquals(type.name(), allowed, plugin.gated(() -> true).getAsBoolean());
      assertFalse(type.name(), plugin.gated(() -> false).getAsBoolean());
    }
  }

  private interface Trigger {
    void fire(EventOutbox outbox, BooleanSupplier gate);
  }

  /** Each event capture emits on a main world and stays silent on every skipped one. */
  @Test
  public void eachEventCaptureFollowsTheWorldCheckForEveryType() throws Exception {
    Trigger[] triggers = {
      (outbox, gate) -> {
        PetDropCapture pet = new PetDropCapture(outbox, gate, () -> 1L);
        pet.handleMessage("You have a funny feeling like you're being followed.");
        pet.handleMessage("New item added to your collection log: Baby mole");
      },
      (outbox, gate) ->
          new CollectionLogUnlockCapture(outbox, gate, () -> 1L)
              .handleMessage("New item added to your collection log: Abyssal orphan"),
      (outbox, gate) ->
          new CombatAchievementCompletionCapture(outbox, gate, () -> 1L)
              .handleMessage("Congratulations, you've completed a hard combat task: Whack-a-Mole."),
      (outbox, gate) ->
          new CombatAchievementTierCompletionCapture(outbox, gate, () -> 1L)
              .handleMessage(
                  "Congratulations, you have completed the easy tier of the Combat Achievements!"),
    };
    for (WorldType type : WorldType.values()) {
      BooleanSupplier gate = pluginOn(EnumSet.of(type)).gated(() -> true);
      for (int i = 0; i < triggers.length; i++) {
        EventOutbox outbox = new EventOutbox(new File(folder.newFolder(), "events.json"), new Gson());
        triggers[i].fire(outbox, gate);
        assertEquals(type.name() + " trigger " + i, skipped(type), outbox.pending().isEmpty());
      }
    }
  }

  @SuppressWarnings("unchecked")
  private static Map<String, Integer> lastSkillRead(BankstandPlugin plugin) throws Exception {
    Field f = BankstandPlugin.class.getDeclaredField("lastSkillRead");
    f.setAccessible(true);
    return (Map<String, Integer>) f.get(plugin);
  }

  private static void setLastSkillRead(BankstandPlugin plugin) throws Exception {
    Field f = BankstandPlugin.class.getDeclaredField("lastSkillRead");
    f.setAccessible(true);
    f.set(plugin, Collections.singletonMap("attack", 100));
  }

  /** The logout read is checked against the last read, which must be this account's. */
  @Test
  public void forgetsTheLastSkillReadOnANewLoginAndOnLogout() throws Exception {
    BankstandPlugin plugin = pluginOn(EnumSet.noneOf(WorldType.class));
    setLastSkillRead(plugin);
    GameStateChanged login = new GameStateChanged();
    login.setGameState(GameState.LOGGED_IN);
    plugin.onGameStateChanged(login);
    assertNull(lastSkillRead(plugin));

    setLastSkillRead(plugin);
    GameStateChanged logout = new GameStateChanged();
    logout.setGameState(GameState.LOGIN_SCREEN);
    plugin.onGameStateChanged(logout);
    assertNull(lastSkillRead(plugin));
    assertFalse(plugin.isCaptureReady());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.LinkedHashSet;
import org.junit.Test;

public class CollectionLogAccumulatorTest {

  @Test
  public void recordsAnItemOnceAndReportsWhetherItWasNew() {
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    assertTrue(log.observe(11832));
    assertFalse(log.observe(11832));
    assertEquals(1, log.size());
  }

  @Test
  public void accumulatesAcrossReadsRatherThanReplacing() {
    // A partial read adds to what is known; it never replaces it.
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    log.observe(11832);
    log.observe(11834);

    log.observe(4151);

    assertEquals(
        new LinkedHashSet<>(Arrays.asList(11832, 11834, 4151)), log.observed());
  }

  @Test
  public void keepsFirstSeenOrder() {
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    log.observe(3);
    log.observe(1);
    log.observe(2);
    assertEquals(Arrays.asList(3, 1, 2), new java.util.ArrayList<>(log.observed()));
  }

  @Test
  public void resetForgetsEverything() {
    // A collection log belongs to one character.
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    log.observe(11832);
    log.reset();
    assertTrue(log.isEmpty());
    assertEquals(0, log.size());
  }

  @Test
  public void exposesAnUnmodifiableView() {
    // Mutating the view would bypass observe().
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    log.observe(11832);
    try {
      log.observed().add(999);
      org.junit.Assert.fail("expected the view to be unmodifiable");
    } catch (UnsupportedOperationException expected) {
      // as intended
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class CollectionLogBaselineTest {

  @Test
  public void reportsAChangeUntilTheServerAcknowledges() {
    CollectionLogBaseline b = new CollectionLogBaseline();
    assertTrue(b.changedSince(12));
    b.advance(12);
    assertFalse(b.changedSince(12));
  }

  @Test
  public void reportsAChangeWhenTheLogGrows() {
    CollectionLogBaseline b = new CollectionLogBaseline();
    b.advance(12);
    assertTrue(b.changedSince(13));
  }

  @Test
  public void neverReportsAChangeForAnEmptyLog() {
    // Nothing observed is not nothing owned; submitting would just send noise.
    CollectionLogBaseline b = new CollectionLogBaseline();
    assertFalse(b.changedSince(0));
  }

  @Test
  public void resendsAfterAResetSoAnAccountSwitchStartsClean() {
    CollectionLogBaseline b = new CollectionLogBaseline();
    b.advance(12);
    b.reset();
    assertTrue(b.changedSince(12));
  }

  @Test
  public void doesNotAdvanceOnAnUnacknowledgedSubmit() {
    // The baseline only moves on a server ack, so a dropped submit is retried.
    CollectionLogBaseline b = new CollectionLogBaseline();
    assertTrue(b.changedSince(5));
    assertTrue(b.changedSince(5));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.bankstand.CollectionLogSync.Outcome;
import org.junit.Test;

public class CollectionLogSyncTest {

  private static void idleTicks(CollectionLogSync sync, int count) {
    for (int i = 0; i < count; i++) {
      assertNull(sync.onTick(false, true));
    }
  }

  @Test
  public void ignoresOrdinaryPageBrowsing() {
    CollectionLogSync sync = new CollectionLogSync();

    assertFalse(sync.isActive());
    // The same script fires on a page turn; it must not report a whole-log sync.
    sync.onItemObserved(1, false);
    sync.onItemObserved(2, false);

    assertFalse(sync.isActive());
    assertEquals(0, sync.observedCount());
    assertNull(sync.onTick(false, true));
  }

  /** The Hub bans driving the Search, so the player clicking the game's own Search must suffice. */
  @Test
  public void aSearchStartsAReadWithNothingArmed() {
    CollectionLogSync sync = new CollectionLogSync();

    sync.onItemObserved(1, true);
    sync.onItemObserved(2, true);

    assertTrue(sync.isActive());
    assertFalse(sync.isAwaitingSearch());
    assertEquals(2, sync.observedCount());
  }

  @Test
  public void anUnarmedSearchStillReportsComplete() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.onItemObserved(1, true);

    Outcome outcome = null;
    for (int i = 0; i < CollectionLogSync.QUIET_TICKS && outcome == null; i++) {
      outcome = sync.onTick(true, true);
    }

    assertEquals(Outcome.COMPLETE, outcome);
  }

  @Test
  public void armingWaitsForTheSearchWithoutCountingAnything() {
    CollectionLogSync sync = new CollectionLogSync();

    sync.arm();

    assertTrue(sync.isActive());
    assertTrue(sync.isAwaitingSearch());
    assertEquals(0, sync.observedCount());
  }

  @Test
  public void countsItemsOnceTheSearchStartsStreaming() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();

    assertNull(sync.onTick(true, true));
    sync.onItemObserved(3, true);
    sync.onItemObserved(4, true);
    sync.onItemObserved(5, true);

    assertFalse(sync.isAwaitingSearch());
    assertEquals(3, sync.observedCount());
  }

  @Test
  public void reportsCompleteWhenAReadRunUnderSearchGoesQuiet() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));
    sync.onItemObserved(6, true);
    sync.onItemObserved(7, true);

    Outcome outcome = null;
    for (int i = 0; i < CollectionLogSync.QUIET_TICKS && outcome == null; i++) {
      outcome = sync.onTick(true, true);
    }

    assertEquals(Outcome.COMPLETE, outcome);
    assertEquals(2, outcome.getObserved());
    assertFalse(sync.isActive());
    assertNull(sync.onTick(true, true));
  }

  /** Eight Prospector ids fill four slots, and the count says four. */
  @Test
  public void countsAVariantAsTheSlotItFills() {
    CollectionLogSync sync = new CollectionLogSync();
    for (int id : new int[] {12013, 12014, 12015, 12016, 29472, 29474, 29476, 29478}) {
      sync.onItemObserved(id, true);
    }

    assertEquals(4, sync.observedCount());
  }

  @Test
  public void countsDistinctEntriesRatherThanScriptFires() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));

    for (int repeat = 0; repeat < 2; repeat++) {
      for (int id = 1; id <= 211; id++) {
        sync.onItemObserved(id, true);
      }
    }

    assertEquals(211, sync.observedCount());
  }

  @Test
  public void doesNotFinishWhileItemsAreStillArriving() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));

    for (int i = 0; i < CollectionLogSync.QUIET_TICKS * 3; i++) {
      sync.onItemObserved(100 + i, true);
      assertNull(sync.onTick(true, true));
    }

    assertTrue(sync.isActive());
    assertEquals(CollectionLogSync.QUIET_TICKS * 3, sync.observedCount());
  }

  @Test
  public void reportsPartialWhenTheLogClosesMidRead() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));
    sync.onItemObserved(9, true);
    sync.onItemObserved(10, true);
    sync.onItemObserved(11, true);

    Outcome outcome = sync.onTick(true, false);

    assertEquals(Outcome.PARTIAL, outcome);
    assertEquals(3, outcome.getObserved());
    assertFalse(sync.isActive());
  }

  /**
   * The search-open signal cannot be verified outside a live client, so when it never
   * arrives the sync under-claims rather than calling the read complete.
   */
  @Test
  public void reportsPartialWhenItemsArrivedWithoutTheSearchEverBeingSeen() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    sync.onItemObserved(12, true);

    Outcome outcome = null;
    for (int i = 0; i < CollectionLogSync.QUIET_TICKS && outcome == null; i++) {
      outcome = sync.onTick(false, true);
    }

    assertEquals(Outcome.PARTIAL, outcome);
    assertEquals(1, outcome.getObserved());
  }

  @Test
  public void cancelsSilentlyWhenTheLogClosesBeforeAnySearch() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();

    assertNull(sync.onTick(false, false));
    assertFalse(sync.isActive());
  }

  @Test
  public void cancelsAnArmedSyncThePlayerNeverActedOn() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();

    idleTicks(sync, CollectionLogSync.ARM_TIMEOUT_TICKS - 1);
    assertTrue(sync.isActive());
    assertNull(sync.onTick(false, true));

    assertFalse(sync.isActive());
  }

  @Test
  public void theArmTimeoutDoesNotApplyOnceItemsAreStreaming() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    idleTicks(sync, CollectionLogSync.ARM_TIMEOUT_TICKS - 1);

    // A read starting on the last tick still gets its full quiet window.
    sync.onItemObserved(13, true);
    assertNull(sync.onTick(true, true));
    assertTrue(sync.isActive());
    assertEquals(1, sync.observedCount());
  }

  @Test
  public void armingTwiceRestartsTheReadRatherThanAccumulating() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));
    sync.onItemObserved(14, true);
    sync.onItemObserved(15, true);

    sync.arm();

    assertEquals(0, sync.observedCount());
    assertTrue(sync.isAwaitingSearch());
  }

  @Test
  public void resetAbandonsAnythingInFlight() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    sync.onItemObserved(16, true);

    sync.reset();

    assertFalse(sync.isActive());
    assertEquals(0, sync.observedCount());
    assertNull(sync.onTick(true, true));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class CollectionLogUnlockCaptureTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  @Test
  public void emitsOnTheCollectionLogBroadcast() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("New item added to your collection log: Abyssal orphan");

    assertTrue(!outbox.pending().isEmpty());
    // The type is the one value the server also checks, so a typo would 400 permanently.
    assertEquals(
        TransientEvent.TYPE_COLLECTION_LOG_UNLOCK, outbox.pending().get(0).getEvent().getType());
    assertTrue(
        outbox.pending().get(0).getEvent().getPayload().get("itemName").equals("Abyssal orphan"));
  }

  /** An oversized name would 400 the whole batch and block every queued event forever. */
  @Test
  public void skipsAnOversizedItemName() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);
    String oversizedName = repeat("A", 129);

    capture.handleMessage("New item added to your collection log: " + oversizedName);

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void emitsAnItemNameAtExactlyTheLengthBound() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);
    String boundedName = repeat("A", 128);

    capture.handleMessage("New item added to your collection log: " + boundedName);

    assertTrue(!outbox.pending().isEmpty());
  }

  private static String repeat(String s, int times) {
