      assertNotNull(body, h.eventOutbox.problem());
    }
    File loot = new File(dir, "loot.json");
    Files.write(loot.toPath(), "[null, {}]".getBytes(StandardCharsets.UTF_8));
    assertTrue(h.lootOutbox.pending().isEmpty());
    assertNotNull(h.lootOutbox.problem());
  }

  @Test
  public void anUnwritableQueueIsReportedAndRecoversWhenWritable() throws Exception {
    assumeTrue(dir.setWritable(false));
    try {
      unlock("Pet snakeling");
      assertNotNull(h.eventOutbox.problem());
    } finally {
      dir.setWritable(true);
    }
    unlock("Abyssal orphan");
    assertNull(h.eventOutbox.problem());
  }

  @Test
  public void anOverflowIsCountedForTheStatusReport() throws Exception {
    for (int i = 0; i < EventOutbox.MAX_PENDING + 3; i++) {
      unlock("Item " + i);
    }
    assertEquals(3, h.eventOutbox.dropped());
  }

  @Test
  public void clientThreadSaveCostAtAFullQueue() throws Exception {
    for (int i = 0; i < EventOutbox.MAX_PENDING; i++) {
      unlock("Item " + i);
    }
    int runs = 50;
    long start = System.nanoTime();
    for (int i = 0; i < runs; i++) {
      unlock("Timed " + i);
    }
    long micros = (System.nanoTime() - start) / 1000 / runs;
    System.out.println("event outbox add at " + EventOutbox.MAX_PENDING + " pending: " + micros + " us");
    assertTrue(micros < 1_000_000);
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Every failure resolves to "not paired", never to carrying on with an unreadable credential.
 */
public class DeviceCredentialStoreTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private DeviceCredentialStore storeIn(File file) {
    return new DeviceCredentialStore(file, new Gson());
  }

  private File newFile() throws IOException {
    return new File(folder.newFolder("bankstand"), "device.json");
  }

  @Test
  public void roundTripsAPairing() throws IOException {
    File file = newFile();
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");
    saved.setDeviceId("dev_1");
    saved.setExpiresAt("2027-01-01T00:00:00Z");
    storeIn(file).save(saved);

    DeviceCredentials loaded = storeIn(file).load();

    assertEquals("tok_abc", loaded.getToken());
    assertEquals("dev_1", loaded.getDeviceId());
    assertEquals("2027-01-01T00:00:00Z", loaded.getExpiresAt());
    assertTrue(loaded.isPaired());
  }

  @Test
  public void aFailedSaveLeavesNoCopyOfTheTokenBehind() throws IOException {
    File file = newFile();
    // A non-empty directory where the file goes makes the final move fail.
    assertTrue(new File(file, "x").mkdirs());
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");

    assertFalse(storeIn(file).save(saved));

    String[] left = file.getParentFile().list((dir, name) -> name.endsWith(".tmp"));
    assertEquals(0, left.length);
  }

  @Test
  public void readsAsUnpairedWhenNothingWasEverWritten() throws IOException {
    DeviceCredentials loaded = storeIn(newFile()).load();

    assertFalse(loaded.isPaired());
    assertNull(loaded.getToken());
  }

  @Test
  public void readsAsUnpairedWhenTheFileIsCorrupt() throws IOException {
    // Never a parse failure the player has to diagnose, nor a partial credential.
    File file = newFile();
    Files.write(file.toPath(), "{ not json".getBytes(StandardCharsets.UTF_8));

    assertFalse(storeIn(file).load().isPaired());
  }

  @Test
  public void treatsABlankTokenAsUnpaired() throws IOException {
    File file = newFile();
    DeviceCredentials blank = new DeviceCredentials();
    blank.setToken("   ");
    storeIn(file).save(blank);

    assertFalse(storeIn(file).load().isPaired());
  }

  @Test
  public void clearForgetsThePairing() throws IOException {
    File file = newFile();
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");
    storeIn(file).save(saved);

    storeIn(file).clear();

    assertFalse(storeIn(file).load().isPaired());
  }

  @Test
  public void clearOnAnAlreadyEmptyStoreIsNotAnError() throws IOException {
    storeIn(newFile()).clear();
  }

  @Test
  public void createsItsDirectoryOnFirstSave() throws IOException {
    // The directory does not exist on a fresh install.
    File file = new File(new File(folder.getRoot(), "not-created-yet"), "device.json");
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");

    storeIn(file).save(saved);

    assertTrue(storeIn(file).load().isPaired());
  }

  @Test
  public void aFailedSaveDoesNotDestroyThePreviousPairing() throws IOException {
    // Temp-then-move, so a crash cannot leave a truncated token.
    File file = newFile();
    DeviceCredentials first = new DeviceCredentials();
    first.setToken("tok_first");
    storeIn(file).save(first);

    DeviceCredentials second = new DeviceCredentials();
    second.setToken("tok_second");
    storeIn(file).save(second);

    assertEquals("tok_second", storeIn(file).load().getToken());
  }

  @Test
  public void cachesAfterTheFirstLoadRatherThanReReadingTheFile() throws IOException {
    // load() runs on nearly every event, so a second call must not touch disk again.
    File file = newFile();
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");
    DeviceCredentialStore store = storeIn(file);
    store.save(saved);

    assertTrue(store.load().isPaired());
    Files.delete(file.toPath());

    assertTrue(store.load().isPaired());
    assertEquals("tok_abc", store.load().getToken());
  }

  @Test
  public void aSaveIsVisibleToTheSameInstancesNextLoadWithoutTouchingDisk() throws IOException {
    File file = newFile();
    DeviceCredentialStore store = storeIn(file);
    assertFalse(store.load().isPaired());

    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_new");
    store.save(saved);

    assertEquals("tok_new", store.load().getToken());
  }

  @Test
  public void clearIsVisibleToTheSameInstancesNextLoad() throws IOException {
    File file = newFile();
    DeviceCredentialStore store = storeIn(file);
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");
    store.save(saved);
    assertTrue(store.load().isPaired());

    store.clear();

    assertFalse(store.load().isPaired());
  }

  @Test
  public void anUnreadableFileIsRetriedAndNeverPurgesTheQueues() throws IOException {
    File file = newFile();
    DeviceCredentials paired = new DeviceCredentials();
    paired.setToken("tok_abc");
    paired.setPairingId("p1");
    storeIn(file).save(paired);
    File events = new File(file.getParentFile(), "events.json");
    EventOutbox writer = new EventOutbox(events, new Gson());
    writer.setPairing(PairingQueues.pairingOf(storeIn(file)));
    writer.add(1L, new TransientEvent("e1", TransientEvent.TYPE_PET_DROP, "2026-10-27T10:00:00Z", java.util.Collections.emptyMap()));

    org.junit.Assume.assumeTrue(file.setReadable(false) && !file.canRead());
    DeviceCredentialStore store = storeIn(file);
    try {
      assertFalse("unknown is not paired", store.load().isPaired());
      EventOutbox reader = new EventOutbox(events, new Gson());
      reader.setPairing(PairingQueues.pairingOf(store));
      reader.pending();
    } finally {
      file.setReadable(true);
    }
    assertTrue("read again, not cached as unpaired", store.load().isPaired());
    EventOutbox after = new EventOutbox(events, new Gson());
    after.setPairing(PairingQueues.pairingOf(store));
    assertEquals(1, after.pending().size());
  }

  @Test
  public void eachReadKeepsItsOwnReadability() throws IOException {
    File file = newFile();
    DeviceCredentials paired = new DeviceCredentials();
    paired.setToken("tok_abc");
    storeIn(file).save(paired);
    DeviceCredentialStore store = storeIn(file);
    org.junit.Assume.assumeTrue(file.setReadable(false) && !file.canRead());
    DeviceCredentialStore.Read failed;
    try {
      failed = store.read();
    } finally {
      file.setReadable(true);
    }
    // A second reader succeeds in between; the first result must not change under it.
    DeviceCredentialStore.Read ok = store.read();
    assertTrue(failed.unreadable);
    assertFalse(failed.credentials.isPaired());
    assertFalse(ok.unreadable);
    assertTrue(ok.credentials.isPaired());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import org.junit.Test;

public class DeviceCredentialsTest {

  /** toString() must not leak the token, which the source-scanning log test cannot see. */
  @Test
  public void toStringNeverIncludesTheToken() {
    DeviceCredentials credentials = new DeviceCredentials();
    credentials.setToken("bsd_super_secret_token_value");
    credentials.setDeviceId("dev_1");
    credentials.setExpiresAt("2027-01-01T00:00:00Z");

    String rendered = credentials.toString();

    assertFalse(rendered.contains("bsd_super_secret_token_value"));
    assertTrue(rendered.contains("dev_1"));
    assertTrue(rendered.contains("2027-01-01T00:00:00Z"));
  }

  private static DeviceCredentials pairedWith(String serverUrl) {
    DeviceCredentials credentials = new DeviceCredentials();
    credentials.setToken("bsd_tok");
    credentials.setServerUrl(serverUrl);
    return credentials;
  }

  @Test
  public void givesTheTokenOnlyToTheOriginItWasPairedWith() {
    DeviceCredentials paired = pairedWith("https://bankstand.example");

    assertEquals("bsd_tok", paired.tokenFor("https://bankstand.example"));
    assertEquals("bsd_tok", paired.tokenFor("https://BANKSTAND.example:443/api"));
    assertNull("another host", paired.tokenFor("https://other.example"));
    assertNull("another port", paired.tokenFor("https://bankstand.example:8443"));
    assertNull("another scheme", paired.tokenFor("http://bankstand.example"));
    assertNull("a lookalike host", paired.tokenFor("https://bankstand.example.evil.test"));
    assertNull("userinfo", paired.tokenFor("https://bankstand.example@evil.test"));
    assertNull("unusable", paired.tokenFor("not a url"));
  }

  @Test
  public void anOlderPairingWithNoServerBelongsToTheDefaultServerOnly() {
    DeviceCredentials legacy = pairedWith(null);

    assertEquals("bsd_tok", legacy.tokenFor(BankstandKeys.DEFAULT_SERVER_URL));
    assertNull(legacy.tokenFor("http://localhost:3000"));
  }

  @Test
  public void anUnpairedRecordHasNoTokenForAnyServer() {
    assertNull(DeviceCredentials.none().tokenFor(BankstandKeys.DEFAULT_SERVER_URL));
  }

  @Test
  public void theServerSurvivesTheFileRoundTrip() {
    Gson gson = new Gson();
    DeviceCredentials read =
        gson.fromJson(gson.toJson(pairedWith("http://localhost:3000")), DeviceCredentials.class);
    assertEquals("bsd_tok", read.tokenFor("http://localhost:3000"));
    assertNull(read.tokenFor(BankstandKeys.DEFAULT_SERVER_URL));
  }
}

