package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.bankstand.http.HttpResponse;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.File;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** Diary reads taken before the game has sent every value must never lower what was stored. */
public class DiaryEarlyReadTest {

  private static final String STORED =
      "{\"accepted\":true,\"stored\":true,\"storedBlocks\":[\"skills\",\"diaries\","
          + "\"combatAchievements\",\"accountType\",\"slayerTask\",\"diaryTaskVars\"]}";
  private static final String[] DIARY_BLOCKS = {"diaries", "diaryTasks", "diaryTaskVars"};

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private PluginHarness h;
  private int xp = 1_000;

  @Before
  public void setUp() throws Exception {
    h = start(true);
    // Nothing is acked yet, so the first read waits out the hold.
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
  }

  /** A plugin over the same state folder, as after a client restart. */
  private PluginHarness start(boolean loaded) throws Exception {
    PluginHarness harness = new PluginHarness(folder.getRoot());
    harness.toggles.put("collectQuests", false);
    harness.toggles.put("collectSessions", false);
    // The slayer read needs a real client once the login is old enough.
    harness.toggles.put("collectSlayer", false);
    harness.transport.byPath.put("/submit", body -> new HttpResponse(200, STORED));
    if (loaded) {
      progress(harness);
    }
    harness.xp = xp;
    harness.logIn();
    harness.executor.runAll();
    return harness;
  }

  /** Account A: Varrock easy and medium done, three easy task bits set. */
  private static void progress(PluginHarness harness) {
    harness.varbits.put(DiaryVarbits.ALL.get("VARROCK_EASY"), 1);
    harness.varbits.put(DiaryVarbits.ALL.get("VARROCK_MEDIUM"), 1);
    harness.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    harness.varbits.put(VarbitID.VARROCK_MED_COUNT, 13);
    harness.varps.put(VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, 0b111);
  }

  private static void zeroes(PluginHarness harness) {
    harness.varps.clear();
    harness.varbits.clear();
  }

  /** One periodic capture with moved XP, so a submit always goes out. */
  private void capture() throws Exception {
    h.xp = ++xp;
    h.plugin.captureSkills();
    h.runClientThread();
    h.executor.runAll();
  }

  private List<JsonObject> snapshots() {
    List<JsonObject> out = new ArrayList<>();
    for (String body : h.transport.bodies) {
      JsonObject json = body == null ? null : new Gson().fromJson(body, JsonObject.class);
      if (json != null && json.has("skills")) {
        out.add(json);
      }
    }
    return out;
  }

  private JsonObject last() {
    List<JsonObject> all = snapshots();
    return all.get(all.size() - 1);
  }

  private void assertNoDiaryBlock(JsonObject body) {
    for (String block : DIARY_BLOCKS) {
      assertFalse(block + " in " + body, body.has(block));
    }
  }

  private static String flag(JsonObject body, String tier) {
    return body.getAsJsonObject("diaries").get(tier).getAsString();
  }

  private static int count(JsonObject body, String tier) {
    return body.getAsJsonObject("diaryTasks").get(tier).getAsInt();
  }

  /** A hop: same account and baselines, with the login clock restarted. */
  private void soonAfterLogin() {
    h.hopTo(EnumSet.of(WorldType.MEMBERS));
    h.executor.runAll();
  }

  private void relog(long hash) throws Exception {
    h.state(GameState.LOGIN_SCREEN);
    h.executor.runAll();
    h.hash = hash;
    zeroes(h);
    h.logIn();
    h.executor.runAll();
  }

  @Test
  public void aStepAckedProgressIsWhatTheFirstReadSent() {
    JsonObject first = last();
    assertEquals("COMPLETE", flag(first, "VARROCK_MEDIUM"));
    assertEquals(13, count(first, "VARROCK_MEDIUM"));
    assertTrue(first.has("diaryTaskVars"));
  }

  @Test
  public void bAndCStepAllZeroAfterTheSettleSendsNoDiaryBlockAndTheLaterRealReadNothingNew()
      throws Exception {
    h = start(false);
    capture();
    assertEquals(1, snapshots().size());
    assertNoDiaryBlock(last());
    progress(h);
    capture();
    assertEquals(2, snapshots().size());
    assertNoDiaryBlock(last());
  }

  @Test
  public void dStepAPartialLoadAfterARestartSendsNoDiaryBlock() throws Exception {
    h = start(false);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_EASY"), 1);
    h.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    h.varps.put(VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, 0b001);
    capture();
    assertNoDiaryBlock(last());
    // Everything arrives: same as stored, so still nothing to send.
    progress(h);
    capture();
    assertNoDiaryBlock(last());
    // Real progress goes out as before.
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_HARD"), 1);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_HARD"));
    assertEquals("COMPLETE", flag(last(), "VARROCK_MEDIUM"));
  }

  @Test
  public void dStepAPartialLoadAfterARelogSendsNoDiaryBlock() throws Exception {
    relog(PluginHarness.MAIN);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_EASY"), 1);
    h.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void dStepOnlyTheTaskVarsLaggingStillHoldsTheWholeDiaryRead() throws Exception {
    soonAfterLogin();
    progress(h);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_HARD"), 1);
    h.varps.put(VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, 0b001);
    capture();
    assertNoDiaryBlock(last());
    h.varps.put(VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, 0b111);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_HARD"));
    assertFalse("the vars equal what was acked", last().has("diaryTaskVars"));
  }

  @Test
  public void dStepALowerCountAloneHoldsTheBlock() throws Exception {
    soonAfterLogin();
    h.varbits.put(VarbitID.VARROCK_MED_COUNT, 2);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_HARD"), 1);
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void aHeldReadNeverCausesASubmitOfItsOwn() throws Exception {
    soonAfterLogin();
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_MEDIUM"), 0);
    for (int i = 0; i < 3; i++) {
      h.plugin.captureSkills();
      h.runClientThread();
      h.executor.runAll();
    }
    assertEquals(1, snapshots().size());
  }

  @Test
  public void aCountRiseWithoutAFlagChangeResendsTheDiaryBlocksOnce() throws Exception {
    h.varbits.put(VarbitID.VARROCK_HARD_COUNT, 3);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_MEDIUM"));
    assertEquals(3, count(last(), "VARROCK_HARD"));
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void aHeldCountRiseNeverCausesASubmitOfItsOwn() throws Exception {
    soonAfterLogin();
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_MEDIUM"), 0);
    h.varbits.put(VarbitID.VARROCK_HARD_COUNT, 3);
    h.plugin.captureSkills();
    h.runClientThread();
    h.executor.runAll();
    assertEquals(1, snapshots().size());
  }

  @Test
  public void aLowerReadLongAfterLoginIsBelievedSoTheHoldIsBounded() throws Exception {
    h.varbits.put(VarbitID.VARROCK_MED_COUNT, 12);
    h.ticks(DiaryBaseline.HOLD_TICKS);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_HARD"), 1);
    capture();
    assertEquals(12, count(last(), "VARROCK_MEDIUM"));
    // Acked, so the lower value is the new floor and nothing repeats.
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void eStepASwitchNeverCarriesOneAccountsDiaryToTheOther() throws Exception {
    relog(77L);
    capture();
    JsonObject b = last();
    if (b.has("diaries")) {
      assertFalse("A's state under B", b.getAsJsonObject("diaries").toString().contains("\"COMPLETE\""));
    }
    assertFalse(b.has("diaryTaskVars"));
    relog(PluginHarness.MAIN);
    capture();
    assertNoDiaryBlock(last());
    progress(h);
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void eStepAHopWithZeroesSendsNoDiaryBlock() throws Exception {
    zeroes(h);
    h.hopTo(EnumSet.of(WorldType.MEMBERS));
    h.executor.runAll();
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void iStepANewAccountsZeroReadGoesOnceAfterTheHold() throws Exception {
    relog(77L);
    capture();
    assertNoDiaryBlock(last());
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
    JsonObject b = last();
    assertEquals("INCOMPLETE", flag(b, "VARROCK_EASY"));
    assertEquals(0, count(b, "VARROCK_EASY"));
    assertFalse("all-zero vars stay unknown", b.has("diaryTaskVars"));
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void gStepNoAckedStateHoldsEvenRealValuesUntilTheWindowEnds() throws Exception {
    relog(77L);
    capture();
    assertNoDiaryBlock(last());
    progress(h);
    capture();
    assertNoDiaryBlock(last());
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_MEDIUM"));
    assertEquals(13, count(last(), "VARROCK_MEDIUM"));
    assertTrue(last().has("diaryTaskVars"));
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void hStepNoAckedStateHoldsAPartialLoadThenSendsTheCurrentRead() throws Exception {
    relog(77L);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_EASY"), 1);
    h.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    capture();
    assertNoDiaryBlock(last());
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_EASY"));
    assertEquals("INCOMPLETE", flag(last(), "VARROCK_MEDIUM"));
  }

  @Test
  public void aHeldUnknownBaselineReadNeverCausesASubmitOfItsOwn() throws Exception {
    relog(77L);
    capture();
    int sent = snapshots().size();
    progress(h);
    for (int i = 0; i < 3; i++) {
      h.plugin.captureSkills();
      h.runClientThread();
      h.executor.runAll();
    }
    assertEquals(sent, snapshots().size());
  }

  @Test
  public void aRePairThenAnEarlyZeroReadSendsNoDiaryBlock() throws Exception {
    h.transport.byPath.put(
        "/pair", body -> new HttpResponse(200, "{\"deviceToken\":\"tok-b\",\"deviceId\":\"d\"}"));
    h.call("pair", "BBBB-BBBB");
    h.executor.runAll();
    relog(PluginHarness.MAIN);
    capture();
    assertNoDiaryBlock(last());
  }

  // Fresh pairing: what the client sends for a character with nothing acked. Evidence only.

  private static int varp(JsonObject body) {
    return body.getAsJsonObject("diaryTaskVars").getAsJsonObject("varps")
        .get(Integer.toString(VarPlayerID.VARROCK_ACHIEVEMENT_DIARY)).getAsInt();
  }

  private static int reward(JsonObject body) {
    return body.getAsJsonObject("diaryTaskVars").getAsJsonObject("varbits")
        .get(Integer.toString(VarbitID.VARROCK_EASY_REWARD)).getAsInt();
  }

  @Test
  public void freshPartialValuesStillThereAtTick200AreSentAsReadThenTheFullReadFollows()
      throws Exception {
    relog(77L);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_EASY"), 1);
    h.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    h.varps.put(VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, 0b001);
    h.ticks(DiaryBaseline.HOLD_TICKS - CaptureGate.SETTLE_TICKS - 1);
    capture();
    assertNoDiaryBlock(last());
    h.ticks(1);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_EASY"));
    assertEquals("INCOMPLETE", flag(last(), "VARROCK_MEDIUM"));
    assertEquals(0, count(last(), "VARROCK_MEDIUM"));
    assertEquals(0b001, varp(last()));
    progress(h);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_MEDIUM"));
    assertEquals(13, count(last(), "VARROCK_MEDIUM"));
    assertEquals(0b111, varp(last()));
  }

  @Test
  public void freshCountsBeforeTaskBitsSendZeroBitsThenTheBitsRideTheNextSubmit()
      throws Exception {
    relog(77L);
    h.ticks(DiaryBaseline.HOLD_TICKS);
    h.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    capture();
    assertEquals(14, count(last(), "VARROCK_EASY"));
    assertEquals(0, varp(last()));
    h.varps.put(VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, 0b111);
    capture();
    assertFalse("flags and counts unchanged", last().has("diaries"));
    assertEquals(0b111, varp(last()));
  }

  @Test
  public void freshTaskBitsBeforeCountsSendZeroCountsThenTheCounts() throws Exception {
    relog(77L);
    h.ticks(DiaryBaseline.HOLD_TICKS);
    h.varps.put(VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, 0b111);
    capture();
    assertEquals("INCOMPLETE", flag(last(), "VARROCK_EASY"));
    assertEquals(0, count(last(), "VARROCK_EASY"));
    assertEquals(0b111, varp(last()));
    h.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    capture();
    assertEquals(14, count(last(), "VARROCK_EASY"));
    assertEquals(14, last().getAsJsonObject("diaryTaskVars").getAsJsonObject("varbits")
        .get(Integer.toString(VarbitID.VARROCK_EASY_COUNT)).getAsInt());
  }

  @Test
  public void freshTierFlagAndRewardAfterTheCountsEachGoOutWhenTheyLand() throws Exception {
    relog(77L);
    h.ticks(DiaryBaseline.HOLD_TICKS);
    h.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    capture();
    assertEquals("INCOMPLETE", flag(last(), "VARROCK_EASY"));
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_EASY"), 1);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_EASY"));
    assertFalse("tier flags are not in the rider", last().has("diaryTaskVars"));
    h.varbits.put(VarbitID.VARROCK_EASY_REWARD, 1);
    capture();
    assertFalse("a reward alone only changes the rider", last().has("diaries"));
    assertEquals(1, reward(last()));
  }

  @Test
  public void freshATierFlagBeforeItsCountSendsCompleteWithACountOfZero() throws Exception {
    relog(77L);
    h.ticks(DiaryBaseline.HOLD_TICKS);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_EASY"), 1);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_EASY"));
    assertEquals(0, count(last(), "VARROCK_EASY"));
  }

  @Test
  public void freshAHopDuringTheHoldRestartsTheWindow() throws Exception {
    relog(77L);
    progress(h);
    h.ticks(150);
    soonAfterLogin();
    h.ticks(100);
    capture();
    assertNoDiaryBlock(last());
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_MEDIUM"));
  }

  @Test
  public void freshALogoutDuringTheHoldRestartsTheWindow() throws Exception {
    relog(77L);
    h.ticks(150);
    relog(77L);
    progress(h);
    h.ticks(100);
    capture();
    assertNoDiaryBlock(last());
  }

  @Test
  public void freshASwitchDuringTheHoldNeverSendsTheFirstAccountsDiaryUnderTheSecond()
      throws Exception {
    relog(77L);
    progress(h);
    h.ticks(150);
    capture();
    relog(88L);
    h.varbits.put(DiaryVarbits.ALL.get("VARROCK_EASY"), 1);
    h.varbits.put(VarbitID.VARROCK_EASY_COUNT, 14);
    h.ticks(100);
    capture();
    assertNoDiaryBlock(last());
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
    assertEquals("88", last().get("accountHash").getAsString());
    assertEquals("COMPLETE", flag(last(), "VARROCK_EASY"));
    assertEquals("INCOMPLETE", flag(last(), "VARROCK_MEDIUM"));
    for (JsonObject body : snapshots()) {
      if ("77".equals(body.get("accountHash").getAsString())) {
        assertNoDiaryBlock(body);
      }
    }
  }

  @Test
  public void freshARestartBeforeTheFirstAckHoldsAgain() throws Exception {
    h.transport.byPath.put("/submit", body -> new HttpResponse(400, ""));
    relog(77L);
    progress(h);
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
    assertEquals("sent but refused", "COMPLETE", flag(last(), "VARROCK_MEDIUM"));
    h = start(false);
    relog(77L);
    progress(h);
    capture();
    assertNoDiaryBlock(last());
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
    assertEquals("COMPLETE", flag(last(), "VARROCK_MEDIUM"));
  }

  @Test
  public void freshEarlyReadsOfSkillsAndCombatAchievementsAreNotHeld()
      throws Exception {
    relog(77L);
    h.xp = 0;
    h.plugin.captureSkills();
    h.runClientThread();
    h.executor.runAll();
    JsonObject body = last();
    assertNoDiaryBlock(body);
    assertEquals(0, body.getAsJsonObject("skills").getAsJsonObject("attack").get("xp").getAsInt());
    // An ironman whose varbit has not arrived reads as regular, so regular waits out the window.
    assertFalse(body.has("accountType"));
    assertEquals(0, body.getAsJsonObject("combatAchievements").get("easy").getAsInt());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class DiaryTaskCompletionCaptureTest {

  private static final String WESTERN_TASK_MESSAGE =
      "Well done! You have completed an elite task in the Western Provinces area. Your"
          + " Achievement Diary has been updated.";

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private EventOutbox outboxIn(File file) {
    return new EventOutbox(file, new Gson());
  }

  private File newFile() throws IOException {
    // TemporaryFolder#newFolder throws on a repeated path, and this is called in a loop.
    return new File(folder.newFolder(), "events.json");
  }

  @Test
  public void emitsOnADiaryTaskCompletionBroadcast() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed an elite task in the Western Provinces area. Your"
            + " Achievement Diary has been updated.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals(
        TransientEvent.TYPE_DIARY_TASK_COMPLETED, outbox.pending().get(0).getEvent().getType());
    assertEquals("elite", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals(
        "Western Provinces", outbox.pending().get(0).getEvent().getPayload().get("area"));
  }

  @Test
  public void emitsOnAnIndefiniteArticleAVariant() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed a hard task in the Kandarin area. Your Achievement"
            + " Diary has been updated.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals("hard", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals("Kandarin", outbox.pending().get(0).getEvent().getPayload().get("area"));
  }

  @Test
  public void emitsForEveryRealTier() throws IOException {
    for (String tier : new String[] {"easy", "medium", "hard", "elite"}) {
      EventOutbox outbox = outboxIn(newFile());
      DiaryTaskCompletionCapture capture =
          new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);
      String article = tier.equals("elite") || tier.equals("easy") ? "an" : "a";

      capture.handleMessage(
          "Well done! You have completed "
              + article
              + " "
              + tier
              + " task in the Varrock area. Your Achievement Diary has been updated.");

      assertTrue("expected an event for tier " + tier, !outbox.pending().isEmpty());
      assertEquals(tier, outbox.pending().get(0).getEvent().getPayload().get("tier"));
    }
  }

  @Test
  public void keepsADoubleBarrelledAreaNameIntact() throws IOException {
    // Double-barrelled region names must be captured whole.
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed a medium task in the Lumbridge & Draynor area. Your"
            + " Achievement Diary has been updated.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals(
        "Lumbridge & Draynor", outbox.pending().get(0).getEvent().getPayload().get("area"));
  }

  @Test
  public void ignoresAnUnrecognisedTierWord() throws IOException {
    // Combat achievement tiers must never parse as diary tiers.
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed a master task in the Varrock area. Your Achievement"
            + " Diary has been updated.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void doesNotConfuseTheTierCompletionBroadcastForThisOne() throws IOException {
    // The tier-completion broadcast must not match this pattern.
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Congratulations, you have completed all of the Easy tasks in the Varrock area. Your"
            + " Achievement Diary has been updated.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void ignoresAnUnrelatedMessage() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've reached level 99 in Attack!");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void skipsAnOversizedAreaName() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);
    String oversizedArea = repeat("A", 129);

    capture.handleMessage(
        "Well done! You have completed an elite task in the "
            + oversizedArea
            + " area. Your Achievement Diary has been updated.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void emitsAnAreaNameAtExactlyTheLengthBound() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);
    String boundedArea = repeat("A", 128);

    capture.handleMessage(
        "Well done! You have completed an elite task in the "
            + boundedArea
            + " area. Your Achievement Diary has been updated.");

    assertTrue(!outbox.pending().isEmpty());
  }

  private static String repeat(String s, int times) {
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < times; i++) {
      builder.append(s);
    }
    return builder.toString();
  }

  @Test
  public void touchesNothingWhenDisabled() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> false, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed an elite task in the Western Provinces area. Your"
            + " Achievement Diary has been updated.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void carriesTierAndAreaOnly() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L).handleMessage(WESTERN_TASK_MESSAGE);
    assertEquals(
        Set.of("tier", "area"), outbox.pending().get(0).getEvent().getPayload().keySet());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class DiaryTaskVarbitsTest {

  @Test
  public void coversTheSame48TiersAsTheCompletionTable() {
    // Both tables must cover the same tiers so a count always joins to its completion flag.
    assertEquals(DiaryVarbits.ALL.keySet(), DiaryTaskVarbits.ALL.keySet());
    assertEquals(48, DiaryTaskVarbits.ALL.size());
  }

  @Test
  public void readsADifferentVarbitFromTheCompletionFlag() {
    // Each tier has three varbits; the completion flag would report 0 or 1 tasks.
    for (Map.Entry<String, Integer> e : DiaryTaskVarbits.ALL.entrySet()) {
      assertNotEquals(e.getKey(), DiaryVarbits.ALL.get(e.getKey()), e.getValue());
    }
  }

  @Test
  public void namesEachVarbitOnce() {
    // A shared varbit would report the same count for two tiers.
    Set<Integer> seen = new HashSet<>(DiaryTaskVarbits.ALL.values());
    assertEquals(DiaryTaskVarbits.ALL.size(), seen.size());
  }

  @Test
  public void keepsKaramjaOutsideTheBlockWhereTheGamePutIt() {
    // Karamja predates the 6288-6330 block, so its easy count really is 2423.
    assertEquals(Integer.valueOf(2423), DiaryTaskVarbits.ALL.get("KARAMJA_EASY"));
    for (Map.Entry<String, Integer> e : DiaryTaskVarbits.ALL.entrySet()) {
      if (e.getKey().equals("KARAMJA_EASY")) {
        continue;
      }
      assertTrue(e.getKey() + " = " + e.getValue(), e.getValue() >= 6288);
    }
  }

  @Test
  public void usesTheWireKeysAndNotTheRuneliteNames() {
    // Wire names differ from VarbitID (MEDIUM, not MED); a mismatch drops a whole region.
    assertTrue(DiaryTaskVarbits.ALL.containsKey("KOUREND_KEBOS_ELITE"));
    assertTrue(DiaryTaskVarbits.ALL.containsKey("LUMBRIDGE_DRAYNOR_MEDIUM"));
    assertTrue(DiaryTaskVarbits.ALL.containsKey("WESTERN_PROVINCES_HARD"));
    for (String key : DiaryTaskVarbits.ALL.keySet()) {
      assertTrue(key, key.endsWith("_EASY") || key.endsWith("_MEDIUM")
          || key.endsWith("_HARD") || key.endsWith("_ELITE"));
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.stream.IntStream;
import org.junit.Test;

/** The allowlist the server validates against, pinned by id. */
public class DiaryTaskVarsAllowlistTest {

  @Test
  public void varpsAreTheTwentyThreeTaskVarplayers() {
    int[] expected =
        IntStream.concat(
                IntStream.rangeClosed(1176, 1200).filter(id -> id < 1188 || id > 1191),
                IntStream.of(2085, 2086))
            .toArray();
    int[] actual = DiaryTaskVars.VARPS.clone();
    Arrays.sort(actual);
    assertEquals(23, actual.length);
    assertEquals(Arrays.toString(expected), Arrays.toString(actual));
  }

  @Test
  public void varbitsAreKaramjaTasksEveryRewardAndEveryTierCount() {
    assertEquals(39 + 48 + 48, DiaryTaskVars.VARBITS.length);
    assertEquals(39 + 48 + 48, Arrays.stream(DiaryTaskVars.VARBITS).distinct().count());
    for (int count : DiaryTaskVarbits.ALL.values()) {
      assertTrue(Arrays.stream(DiaryTaskVars.VARBITS).anyMatch(id -> id == count));
    }
    // Karamja tasks sit in 3566-3609, skipping the started, reward and done varbits.
    assertEquals(
        39,
        Arrays.stream(DiaryTaskVars.VARBITS)
            .filter(id -> id >= 3566 && id <= 3609)
            .filter(id -> id != 3576 && id != 3577 && id != 3578 && id != 3598 && id != 3599)
            .count());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.bankstand.http.HttpResponse;
import com.google.gson.JsonObject;
import com.google.gson.Gson;
import java.io.File;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** The raw per-task diary values: read with the diary counts, sent only as a rider. */
public class DiaryTaskVarsTest {

  private static final String OTHER_BLOCKS =
      "[\"skills\",\"diaries\",\"combatAchievements\",\"accountType\",\"slayerTask\"";
  private static final String STORED_WITH_VARS =
      "{\"accepted\":true,\"stored\":true,\"storedBlocks\":" + OTHER_BLOCKS + ",\"diaryTaskVars\"]}";
  // A server from before this field: it strips the block and never acks it.
  private static final String STORED_WITHOUT_VARS =
      "{\"accepted\":true,\"stored\":true,\"storedBlocks\":" + OTHER_BLOCKS + "]}";

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private File dir;
  private PluginHarness h;
  private String reply = STORED_WITH_VARS;

  @Before
  public void setUp() throws Exception {
    dir = folder.getRoot();
    h = start();
  }

  private PluginHarness start() throws Exception {
    PluginHarness harness = new PluginHarness(dir);
    // Quest reads run a client script the fake client cannot answer; sessions add requests.
    harness.toggles.put("collectQuests", false);
    harness.toggles.put("collectSessions", false);
    harness.transport.byPath.put("/submit", body -> new HttpResponse(200, reply));
    harness.varps.put(VarPlayerID.FREMENNIK_ACHIEVEMENT_DIARY, 0b1011);
    harness.varbits.put(VarbitID.ATJUN_EASY_BANANA, 5);
    harness.varbits.put(VarbitID.WESTERN_EASY_REWARD, 1);
    harness.xp = 1_000;
    // The slayer read needs a real client once the login is old enough.
    harness.toggles.put("collectSlayer", false);
    harness.logIn();
    harness.executor.runAll();
    // Past the hold an unknown baseline gets, so a first read goes out.
    harness.ticks(DiaryBaseline.HOLD_TICKS);
    return harness;
  }

  /** One periodic capture, run to completion. */
  private void capture() throws Exception {
    h.plugin.captureSkills();
    h.runClientThread();
    h.executor.runAll();
  }

  /** The snapshot submissions so far (identity submits carry no skills). */
  private List<JsonObject> snapshots() {
    List<JsonObject> out = new ArrayList<>();
    for (String body : h.transport.bodies) {
      JsonObject json = body == null ? null : new Gson().fromJson(body, JsonObject.class);
      if (json != null && json.has("skills")) {
        out.add(json);
      }
    }
    return out;
  }

  private JsonObject last() {
    List<JsonObject> all = snapshots();
    return all.get(all.size() - 1);
  }

  @Test
  public void theFirstReadSendsTheWholeAllowlistAndNoEvents() throws Exception {
    capture();
    JsonObject vars = last().getAsJsonObject("diaryTaskVars");
    assertNotNull(vars);
    assertEquals(23, vars.getAsJsonObject("varps").size());
    assertEquals(39 + 48 + 48, vars.getAsJsonObject("varbits").size());
    assertEquals(0b1011, vars.getAsJsonObject("varps").get("1184").getAsInt());
    assertEquals(5, vars.getAsJsonObject("varbits").get("3566").getAsInt());
    assertEquals(1, vars.getAsJsonObject("varbits").get("4511").getAsInt());
    assertTrue("per-tier counts keep their own field", last().has("diaryTasks"));
    assertTrue("no events from this path", h.eventOutbox.pending().isEmpty());
  }

  @Test
  public void aChangeRidesTheNextSubmit() throws Exception {
    capture();
    h.varps.put(VarPlayerID.FREMENNIK_ACHIEVEMENT_DIARY, 0b1111);
    h.xp = 2_000;
    capture();
    assertEquals(2, snapshots().size());
    assertEquals(0b1111, last().getAsJsonObject("diaryTaskVars").getAsJsonObject("varps").get("1184").getAsInt());
  }

  @Test
  public void anUnchangedBlockStaysOff() throws Exception {
    capture();
    h.xp = 2_000;
    capture();
    assertEquals(2, snapshots().size());
    assertFalse(last().has("diaryTaskVars"));
  }

  @Test
  public void aChangeAloneNeverForcesASubmit() throws Exception {
    capture();
    h.varps.put(VarPlayerID.FREMENNIK_ACHIEVEMENT_DIARY, 0b1111);
    capture();
    assertEquals(1, snapshots().size());
  }

  @Test
  public void aServerThatStripsTheBlockCausesNoExtraSubmits() throws Exception {
    reply = STORED_WITHOUT_VARS;
    capture();
    capture();
    capture();
    assertEquals(1, snapshots().size());
    // Unacked, it keeps riding on submits that happen anyway.
    h.xp = 2_000;
    capture();
    assertEquals(2, snapshots().size());
    assertTrue(last().has("diaryTaskVars"));
  }

  @Test
  public void anAccountSwitchResendsTheBlock() throws Exception {
    capture();
    h.state(GameState.LOGIN_SCREEN);
    h.hash = 77L;
    h.logIn();
    h.executor.runAll();
    h.ticks(DiaryBaseline.HOLD_TICKS);
    capture();
    assertEquals(2, snapshots().size());
    assertTrue(last().has("diaryTaskVars"));
  }

  @Test
  public void aRePairResendsTheBlock() throws Exception {
    h.transport.byPath.put(
        "/pair", body -> new HttpResponse(200, "{\"deviceToken\":\"tok-b\",\"deviceId\":\"d\"}"));
    capture();
    h.call("pair", "BBBB-BBBB");
    h.executor.runAll();
    h.xp = 2_000;
    capture();
    assertTrue(last().has("diaryTaskVars"));
  }

  @Test
  public void aRestartRemembersWhatWasAcked() throws Exception {
    capture();
    h = start();
    h.xp = 2_000;
    capture();
    assertEquals(1, snapshots().size());
    assertFalse(last().has("diaryTaskVars"));
    assertNotNull(h.ackedStore.load(PluginHarness.MAIN).getDiaryTaskVars());
  }

  @Test
  public void theLogoutReadSendsSkillsButNoVarBasedBlock() throws Exception {
    h.varbits.put(VarbitID.ARDOUGNE_EASY_COUNT, 3);
    capture();
    h.ticks(1);
    // A cleared client: every varp and varbit reads zero, but XP moved on.
    h.varps.clear();
    h.varbits.clear();
    h.xp = 2_000;
    h.state(GameState.LOGIN_SCREEN);
    h.executor.runAll();
    assertEquals(2, snapshots().size());
    JsonObject logout = last();
    assertTrue(logout.has("skills"));
    for (String block :
        new String[] {
          "diaries", "diaryTasks", "diaryTaskVars", "combatAchievements",
          "combatAchievementBossCounts", "accountType", "quests", "slayerTask"
        }) {
      assertFalse(block, logout.has(block));
    }
  }

  @Test
  public void aReadBeforeTheVarsArriveNeverOverwritesKnownState() throws Exception {
