package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import org.junit.Test;

public class DiaryVarbitsTest {
  private static final Pattern WIRE_KEY_PATTERN =
      Pattern.compile("^[A-Z]+(_[A-Z]+)*_(EASY|MEDIUM|HARD|ELITE)$");

  @Test
  public void everyWireKeyMatchesTheExpectedShape() {
    for (String key : DiaryVarbits.ALL.keySet()) {
      assertTrue(key + " does not match the wire key shape", WIRE_KEY_PATTERN.matcher(key).matches());
    }
  }

  @Test
  public void everyVarbitIdIsDistinct() {
    Set<Integer> ids = new HashSet<>(DiaryVarbits.ALL.values());
    assertEquals(DiaryVarbits.ALL.size(), ids.size());
  }

  @Test
  public void theRegionPrefixSetIsExactlyTheExpectedTwelve() {
    Set<String> expected =
        new HashSet<>(
            java.util.Arrays.asList(
                "ARDOUGNE",
                "DESERT",
                "FALADOR",
                "FREMENNIK",
                "KANDARIN",
                "KARAMJA",
                "KOUREND_KEBOS",
                "LUMBRIDGE_DRAYNOR",
                "MORYTANIA",
                "VARROCK",
                "WESTERN_PROVINCES",
                "WILDERNESS"));
    Set<String> actual = new HashSet<>();
    for (String key : DiaryVarbits.ALL.keySet()) {
      actual.add(regionPrefix(key));
    }
    assertEquals(expected, actual);
  }

  @Test
  public void karamjaCarriesAllFourTiersLikeEveryOtherRegion() {
    // Karamja's flags sit outside the main block; VarbitID names them ATJUN_*_DONE.
    Set<String> karamja = new HashSet<>();
    for (Map.Entry<String, Integer> e : DiaryVarbits.ALL.entrySet()) {
      if (regionPrefix(e.getKey()).equals("KARAMJA")) {
        karamja.add(e.getKey());
      }
    }
    assertEquals(
        new HashSet<>(
            java.util.Arrays.asList(
                "KARAMJA_EASY", "KARAMJA_MEDIUM", "KARAMJA_HARD", "KARAMJA_ELITE")),
        karamja);
  }

  @Test
  public void coversAllFortyEightTiers() {
    // An omitted key reads as "not observed", so a gap is a silent blind spot.
    assertEquals(48, DiaryVarbits.ALL.size());
  }

  @Test
  public void keepsKaramjasPreBlockVarbitIds() {
    // Pinned: they look wrong next to the 4458-4498 block but are correct.
    assertEquals(Integer.valueOf(3578), DiaryVarbits.ALL.get("KARAMJA_EASY"));
    assertEquals(Integer.valueOf(3599), DiaryVarbits.ALL.get("KARAMJA_MEDIUM"));
    assertEquals(Integer.valueOf(3611), DiaryVarbits.ALL.get("KARAMJA_HARD"));
    assertEquals(Integer.valueOf(4566), DiaryVarbits.ALL.get("KARAMJA_ELITE"));
  }

  // Strips the tier suffix; the region prefix may contain underscores (KOUREND_KEBOS).
  private static String regionPrefix(String wireKey) {
    int lastUnderscore = wireKey.lastIndexOf('_');
    return wireKey.substring(0, lastUnderscore);
  }
}

package com.bankstand;

import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.junit.Test;

/** Disconnect needs a live client to run, so its order is pinned on the source. */
public class DisconnectTest {

  @Test
  public void clearsLocallyFirstThenRevokesOffTheClientThread() throws IOException {
    String source =
        new String(
            Files.readAllBytes(
                Paths.get("src", "main", "java", "com", "bankstand", "BankstandPlugin.java")),
            StandardCharsets.UTF_8);
    int start = source.indexOf("private void disconnect() {");
    String body = source.substring(start, source.indexOf("\n  }\n", start));

    int readToken = body.indexOf("DeviceCredentials paired = deviceStore.load();");
    int clear = body.indexOf("removed[0] = deviceStore.clear();");
    int unpair = body.indexOf("api.unpairInBackground(");
    assertTrue("reads the token before forgetting it", readToken >= 0 && readToken < clear);
    assertTrue(
        "revokes at the server it was paired with, not the one now configured",
        body.indexOf("paired.pairedServerUrl(), paired.getToken()", unpair) > unpair);
    assertTrue("clears before and regardless of the server call", clear < unpair);
    assertTrue(
        "tells the player when the server could not be reached",
        body.indexOf("notice(UNPAIR_UNREACHABLE)", unpair) > unpair);
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class EventOutboxTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private EventOutbox outboxIn(File file) {
    return new EventOutbox(file, new Gson());
  }

  private File newFile() throws IOException {
    return new File(folder.newFolder("bankstand"), "events.json");
  }

  private TransientEvent event(String id) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("itemName", "Dragon warhammer");
    return new TransientEvent(id, TransientEvent.TYPE_NOTABLE_DROP, "2026-08-10T10:00:00Z", payload);
  }

  @Test
  public void roundTripsPendingEntries() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    outbox.add(123L, event("a"));
    outbox.add(123L, event("b"));

    List<OutboxEntry> reloaded = outboxIn(file).pending();

    assertEquals(2, reloaded.size());
    assertEquals("a", reloaded.get(0).getEvent().getId());
    assertEquals("b", reloaded.get(1).getEvent().getId());
    assertEquals(123L, reloaded.get(0).getAccountHash());
  }

  @Test
  public void readsAsEmptyWhenNothingWasEverWritten() throws IOException {
    assertTrue(outboxIn(newFile()).pending().isEmpty());
  }

  @Test
  public void ackRemovesExactlyTheMatchingEntriesAndLeavesTheRestInOrder() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    outbox.add(1L, event("a"));
    outbox.add(1L, event("b"));
    outbox.add(1L, event("c"));

    outbox.ack(EventOutbox.toIdSet(Collections.singletonList("b")));

    List<OutboxEntry> remaining = outbox.pending();
    assertEquals(2, remaining.size());
    assertEquals("a", remaining.get(0).getEvent().getId());
    assertEquals("c", remaining.get(1).getEvent().getId());
  }

  @Test
  public void ackWithNoMatchesChangesNothing() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    outbox.add(1L, event("a"));

    outbox.ack(EventOutbox.toIdSet(Collections.singletonList("not-present")));

    assertEquals(1, outbox.pending().size());
  }

  @Test
  public void clearForgetsEveryPendingEvent() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    outbox.add(1L, event("a"));
    outbox.add(2L, event("b"));

    outbox.clear();

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void overflowingTheCapDropsTheOldestEntryAndKeepsTheRest() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    for (int i = 0; i < EventOutbox.MAX_PENDING; i++) {
      outbox.add(1L, event("id-" + i));
    }
    outbox.add(1L, event("overflow"));

    List<OutboxEntry> pending = outbox.pending();
    assertEquals(EventOutbox.MAX_PENDING, pending.size());
    // The oldest entry is the one dropped.
    assertEquals("id-1", pending.get(0).getEvent().getId());
    assertEquals("overflow", pending.get(pending.size() - 1).getEvent().getId());
  }

  @Test
  public void readingACorruptFileResolvesToEmptyRatherThanThrowing() throws IOException {
    File file = newFile();
    java.nio.file.Files.write(file.toPath(), "not json".getBytes(java.nio.charset.StandardCharsets.UTF_8));

    assertTrue(outboxIn(file).pending().isEmpty());
  }

  /**
   * {@code add} runs on the client thread and {@code ack} on the executor, both
   * read-modify-writing the same file. No add may be lost to a concurrent ack.
   */
  @Test
  public void concurrentAddAndAckDoNotLoseEntries() throws Exception {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    int iterations = 150; // below MAX_PENDING, so no drop-oldest eviction is expected
    Set<String> neverMatches = EventOutbox.toIdSet(Collections.singletonList("no-such-id"));
    CountDownLatch ready = new CountDownLatch(2);
    CountDownLatch go = new CountDownLatch(1);

    Thread adder =
        new Thread(
            () -> {
              ready.countDown();
              awaitUninterruptibly(go);
              for (int i = 0; i < iterations; i++) {
                outbox.add(1L, event("id-" + i));
              }
            });
    Thread acker =
        new Thread(
            () -> {
              ready.countDown();
              awaitUninterruptibly(go);
              for (int i = 0; i < iterations; i++) {
                outbox.ack(neverMatches);
              }
            });

    adder.start();
    acker.start();
    ready.await();
    go.countDown();
    adder.join(30_000);
    acker.join(30_000);

    assertEquals(iterations, outbox.pending().size());
  }

  private static void awaitUninterruptibly(CountDownLatch latch) {
    try {
      latch.await();
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
    }
  }

  /** A "not observed" field comes back off disk as an explicit null. */
  @Test
  public void aNullPayloadFieldSurvivesTheRoundTripToDisk() throws Exception {
    java.io.File file = new java.io.File(folder.newFolder("nulls"), "events.json");
    java.util.Map<String, Object> payload = new java.util.LinkedHashMap<>();
    payload.put("petName", "Heron");
    payload.put("source", null);
    new EventOutbox(file, new com.google.gson.Gson())
        .add(1L, new TransientEvent(TransientEvent.TYPE_PET_DROP, payload));

    java.util.Map<String, Object> reloaded =
        new EventOutbox(file, new com.google.gson.Gson()).pending().get(0).getEvent().getPayload();
    org.junit.Assert.assertTrue(reloaded.containsKey("source"));
    org.junit.Assert.assertNull(reloaded.get("source"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.bankstand.dto.SubmitEventsResponse;
import com.google.gson.Gson;
import org.junit.Test;

public class EventSendPacerTest {

  @Test
  public void aRetryAfterPausesEveryAccount() {
    EventSendPacer pacer = new EventSendPacer();
    pacer.pauseFor(0L, 60_000L);
    assertFalse(pacer.maySend(1L, 59_999L));
    assertFalse(pacer.maySend(2L, 59_999L));
    assertTrue(pacer.maySend(1L, 60_000L));
  }

  @Test
  public void aShorterPauseNeverCutsALongerOneShort() {
    EventSendPacer pacer = new EventSendPacer();
    pacer.pauseFor(0L, 60_000L);
    pacer.pauseFor(0L, 1_000L);
    assertFalse(pacer.maySend(1L, 30_000L));
  }

  @Test
  public void anUnroutedAccountWaitsWhileOthersStillSend() {
    EventSendPacer pacer = new EventSendPacer();
    pacer.unrouted(1L, 0L);
    assertFalse(pacer.maySend(1L, EventSendPacer.UNROUTED_BACKOFF_MS - 1));
    assertTrue(pacer.maySend(2L, 0L));
    assertTrue(pacer.maySend(1L, EventSendPacer.UNROUTED_BACKOFF_MS));
  }

  @Test
  public void anIdentityChangeRetriesAnUnroutedAccountAtOnce() {
    EventSendPacer pacer = new EventSendPacer();
    pacer.unrouted(1L, 0L);
    pacer.forgetUnrouted();
    assertTrue(pacer.maySend(1L, 1L));
  }

  @Test
  public void recordAppliesOnlyARoutedReply() {
    EventSendPacer pacer = new EventSendPacer();
    assertTrue(pacer.record(1L, 0L, reply(true), null));
    assertTrue(pacer.maySend(1L, 0L));
    assertFalse(pacer.record(1L, 0L, reply(false), null));
    assertFalse(pacer.maySend(1L, 1L));
  }

  @Test
  public void recordPausesOnARetryAfterButNotOnAPlainFailure() {
    EventSendPacer pacer = new EventSendPacer();
    assertFalse(pacer.record(1L, 0L, null, new SubmitException("Could not reach Bankstand.", true)));
    assertTrue(pacer.maySend(1L, 0L));
    assertFalse(
        pacer.record(1L, 0L, null, new SubmitException("Bankstand is busy.", true, false, 60_000L)));
    assertFalse(pacer.maySend(2L, 59_999L));
    assertTrue(pacer.maySend(2L, 60_000L));
  }

  private static SubmitEventsResponse reply(boolean routed) {
    return new Gson()
        .fromJson("{\"routed\":" + routed + ",\"acks\":[]}", SubmitEventsResponse.class);
  }
}

