}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.lang.reflect.Method;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemStack;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class LootCaptureTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private static final Instant NOW = Instant.parse("2026-10-08T12:00:00Z");
  private static final int NOTED_COINS = 996;

  /** Canonicalises one noted id and calls one item notable; everything else is plain. */
  private static final LootCapture.Items ITEMS =
      new LootCapture.Items() {
        @Override
        public int canonical(int itemId) {
          return itemId == NOTED_COINS ? 995 : itemId;
        }

        @Override
        public boolean isNotable(int itemId, int quantity) {
          return itemId == 11286;
        }
      };

  private LootOutbox outbox() throws Exception {
    return new LootOutbox(new File(folder.newFolder("bankstand"), "loot-outbox.json"), new Gson());
  }

  @Test
  public void touchesNothingWhileOff() throws Exception {
    LootOutbox outbox = outbox();
    // Null item lookups: any read before the gate would throw.
    LootCapture capture =
        new LootCapture(() -> false, () -> 1L, null, new LootLedger(), outbox, () -> {}, () -> NOW);
    capture.handleKill(1, "Rat", Collections.singletonList(new ItemStack(526, 1)));
    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void anOrdinaryKillWaitsForTheDrain() throws Exception {
    LootOutbox outbox = outbox();
    LootLedger ledger = new LootLedger();
    AtomicInteger fast = new AtomicInteger();
    LootCapture capture =
        new LootCapture(() -> true, () -> 1L, ITEMS, ledger, outbox, fast::incrementAndGet, () -> NOW);

    capture.handleKill(1, "Rat", Arrays.asList(new ItemStack(526, 1), new ItemStack(NOTED_COINS, 5)));

    assertTrue(outbox.pending().isEmpty());
    assertEquals(0, fast.get());
    LootEvent event = ledger.closeAll().get(0).getEvent();
    assertEquals("a noted id is sent as its base id", 995, event.getItems().get(1).getId());
  }

  @Test
  public void aNotableKillClosesItsWindowAndAsksForAnEarlySend() throws Exception {
    LootOutbox outbox = outbox();
    LootLedger ledger = new LootLedger();
    AtomicInteger fast = new AtomicInteger();
    LootCapture capture =
        new LootCapture(() -> true, () -> 1L, ITEMS, ledger, outbox, fast::incrementAndGet, () -> NOW);

    capture.handleKill(50, "Mithril dragon", Collections.singletonList(new ItemStack(526, 1)));
    capture.handleKill(50, "Mithril dragon", Collections.singletonList(new ItemStack(11286, 1)));

    assertEquals(1, fast.get());
    assertEquals(1, outbox.pending().size());
    assertEquals(
        "the notable kill rides with the rest of its window", 2, outbox.pending().get(0).getEvent().getKills());
    assertTrue(ledger.closeAll().isEmpty());
  }

  /** Loot from a player kill names that player, so neither capture may listen for it. */
  @Test
  public void noLootCaptureListensForPlayerKills() {
    for (Class<?> capture : new Class<?>[] {LootCapture.class, NotableDropCapture.class}) {
      for (Method method : capture.getDeclaredMethods()) {
        for (Class<?> parameter : method.getParameterTypes()) {
          assertTrue(
              capture.getSimpleName() + "." + method.getName() + " takes a PlayerLootReceived",
              parameter != PlayerLootReceived.class);
        }
      }
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class LootLedgerTest {

  private static final Instant T0 = Instant.parse("2026-10-08T12:00:00Z");
  private static final long ACCOUNT = 42L;
  private static final int CAVE_HORROR = 1047;

  private static Map<Integer, Integer> loot(int... idQtyPairs) {
    Map<Integer, Integer> items = new LinkedHashMap<>();
    for (int i = 0; i < idQtyPairs.length; i += 2) {
      items.put(idQtyPairs[i], idQtyPairs[i + 1]);
    }
    return items;
  }

  private static Map<Integer, Long> itemsOf(LootEvent event) {
    Map<Integer, Long> items = new LinkedHashMap<>();
    for (LootEvent.Item item : event.getItems()) {
      items.put(item.getId(), (long) item.getQty());
    }
    return items;
  }

  @Test
  public void killsOfOneNpcAggregateIntoOneRecordPerWindow() {
    LootLedger ledger = new LootLedger();
    assertTrue(ledger.record(ACCOUNT, CAVE_HORROR, "Cave horror", loot(995, 100), T0).isEmpty());
    ledger.record(ACCOUNT, CAVE_HORROR, "Cave horror", loot(995, 50, 5304, 1), T0.plusSeconds(20));
    ledger.record(ACCOUNT, CAVE_HORROR, "Cave horror", loot(5304, 2), T0.plusSeconds(40));

    List<LootEntry> closed = ledger.closeAll();

    assertEquals(1, closed.size());
    LootEvent event = closed.get(0).getEvent();
    assertEquals(ACCOUNT, closed.get(0).getAccountHash());
    assertEquals(CAVE_HORROR, event.getNpcId());
    assertEquals("Cave horror", event.getNpcName());
    assertEquals(3, event.getKills());
    assertEquals(T0.toString(), event.getWindowStart());
    assertEquals(T0.plusSeconds(40).toString(), event.getOccurredAt());
    assertEquals(150L, (long) itemsOf(event).get(995));
    assertEquals(3L, (long) itemsOf(event).get(5304));
    assertTrue("a closed window is gone", ledger.closeAll().isEmpty());
  }

  @Test
  public void eachNpcAndEachAccountHasItsOwnWindow() {
    LootLedger ledger = new LootLedger();
    ledger.record(ACCOUNT, 1, "Rat", loot(526, 1), T0);
    ledger.record(ACCOUNT, 2, "Goblin", loot(526, 1), T0);
    ledger.record(7L, 1, "Rat", loot(526, 1), T0);
    assertEquals(3, ledger.closeAll().size());
  }

  @Test
  public void anEmptyRollIsNotAKill() {
    LootLedger ledger = new LootLedger();
    ledger.record(ACCOUNT, CAVE_HORROR, "Cave horror", loot(), T0);
    assertTrue(ledger.closeAll().isEmpty());
  }

  @Test
  public void aNamelessNpcIsNotRecorded() {
    LootLedger ledger = new LootLedger();
    ledger.record(ACCOUNT, CAVE_HORROR, "  ", loot(995, 1), T0);
    ledger.record(ACCOUNT, CAVE_HORROR, null, loot(995, 1), T0);
    assertTrue(ledger.closeAll().isEmpty());
  }

  @Test
  public void aLongNameIsCutToTheBound() {
    LootLedger ledger = new LootLedger();
    StringBuilder name = new StringBuilder();
    for (int i = 0; i < 100; i++) {
      name.append('x');
    }
    ledger.record(ACCOUNT, CAVE_HORROR, name.toString(), loot(995, 1), T0);
    assertEquals(
        LootLedger.MAX_NPC_NAME_LENGTH, ledger.closeAll().get(0).getEvent().getNpcName().length());
  }

  @Test
  public void aWindowSplitsOnAKillBoundaryBeforeItWouldPass64DistinctItems() {
    LootLedger ledger = new LootLedger();
    List<LootEntry> closed = new ArrayList<>();
    // Each kill drops two new distinct items: 32 kills reach exactly 64.
    for (int kill = 0; kill < 33; kill++) {
      closed.addAll(
          ledger.record(
              ACCOUNT, CAVE_HORROR, "Cave horror", loot(kill * 2, 1, kill * 2 + 1, 1), T0));
    }
    assertEquals("the 33rd kill closed the full window", 1, closed.size());
    assertEquals(64, closed.get(0).getEvent().getItems().size());
    assertEquals(32, closed.get(0).getEvent().getKills());
    List<LootEntry> rest = ledger.closeAll();
    assertEquals(1, rest.get(0).getEvent().getKills());
    assertEquals(2, rest.get(0).getEvent().getItems().size());
  }

  @Test
  public void aWindowSplitsBeforeAQuantityWouldPassItsBound() {
    LootLedger ledger = new LootLedger();
    ledger.record(ACCOUNT, CAVE_HORROR, "Cave horror", loot(995, 900_000), T0);
    List<LootEntry> closed =
        ledger.record(ACCOUNT, CAVE_HORROR, "Cave horror", loot(995, 200_000), T0.plusSeconds(1));
    assertEquals(1, closed.size());
    assertEquals(900_000L, (long) itemsOf(closed.get(0).getEvent()).get(995));
    assertEquals(200_000L, (long) itemsOf(ledger.closeAll().get(0).getEvent()).get(995));
  }

  @Test
  public void aWindowSplitsBeforeItWouldPassAThousandKills() {
    LootLedger ledger = new LootLedger();
    List<LootEntry> closed = new ArrayList<>();
    for (int kill = 0; kill < LootLedger.MAX_KILLS_PER_RECORD + 1; kill++) {
      closed.addAll(ledger.record(ACCOUNT, 1, "Chicken", loot(526, 1), T0));
    }
    assertEquals(1, closed.size());
    assertEquals(LootLedger.MAX_KILLS_PER_RECORD, closed.get(0).getEvent().getKills());
  }

  @Test
  public void aWindowNeverSpansMoreThanItsMaximumLength() {
    LootLedger ledger = new LootLedger();
    ledger.record(ACCOUNT, 1, "Chicken", loot(526, 1), T0);
    List<LootEntry> closed =
        ledger.record(
            ACCOUNT, 1, "Chicken", loot(526, 1), T0.plus(LootLedger.MAX_WINDOW).plusSeconds(1));
    assertEquals(1, closed.size());
  }

  @Test
  public void aSingleKillIsHeldToTheRecordBoundsOnItsOwn() {
    LootLedger ledger = new LootLedger();
    Map<Integer, Integer> huge = new LinkedHashMap<>();
    for (int id = 0; id < 70; id++) {
      huge.put(id, 1);
    }
    huge.put(9999, LootLedger.MAX_QUANTITY + 1);
    ledger.record(ACCOUNT, 1, "Chicken", huge, T0);
    LootEvent event = ledger.closeAll().get(0).getEvent();
    assertEquals(LootLedger.MAX_ITEMS_PER_RECORD, event.getItems().size());
    for (LootEvent.Item item : event.getItems()) {
      assertTrue(item.getQty() <= LootLedger.MAX_QUANTITY);
    }
  }

  @Test
  public void closingOneNpcLeavesTheOthersOpen() {
    LootLedger ledger = new LootLedger();
    ledger.record(ACCOUNT, 1, "Rat", loot(526, 1), T0);
    ledger.record(ACCOUNT, 2, "Goblin", loot(526, 1), T0);
    assertEquals(1, ledger.close(ACCOUNT, 1).size());
    assertEquals(2, ledger.closeAll().get(0).getEvent().getNpcId());
  }

  @Test
  public void discardForgetsOpenWindows() {
    LootLedger ledger = new LootLedger();
    ledger.record(ACCOUNT, 1, "Rat", loot(526, 1), T0);
    ledger.discard();
    assertTrue(ledger.closeAll().isEmpty());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.bankstand.dto.EventAck;
import com.google.gson.Gson;
import java.io.File;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class LootOutboxTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private static LootEntry entry(String id) {
    return new LootEntry(
        1L,
        new LootEvent(
            id,
            1,
            "Rat",
            1,
            "2026-10-08T12:00:00Z",
            "2026-10-08T12:00:00Z",
            Collections.singletonList(new LootEvent.Item(526, 1))));
  }

  private static List<EventAck> acks(String json) {
    return new Gson().fromJson(json, com.bankstand.dto.SubmitLootResponse.class).getAcks();
  }

  @Test
  public void survivesARestart() throws Exception {
    File file = new File(folder.newFolder("bankstand"), "loot-outbox.json");
    new LootOutbox(file, new Gson()).addAll(Collections.singletonList(entry("a")));
    List<LootEntry> reloaded = new LootOutbox(file, new Gson()).pending();
    assertEquals(1, reloaded.size());
    assertEquals("a", reloaded.get(0).getEvent().getId());
    assertEquals(526, reloaded.get(0).getEvent().getItems().get(0).getId());
  }

  @Test
  public void evictsOnlyItsOwnOldestRecordsPastTheCap() throws Exception {
    File file = new File(folder.newFolder("bankstand"), "loot-outbox.json");
    LootOutbox outbox = new LootOutbox(file, new Gson());
    List<LootEntry> many = new ArrayList<>();
    for (int i = 0; i < LootOutbox.MAX_PENDING + 3; i++) {
      many.add(entry("e" + i));
    }
    outbox.addAll(many);
    List<LootEntry> pending = outbox.pending();
    assertEquals(LootOutbox.MAX_PENDING, pending.size());
    assertEquals("e3", pending.get(0).getEvent().getId());
  }

  /** Loot can never push a pet or an achievement out of the event outbox. */
  @Test
  public void aFullLootOutboxLeavesTheEventOutboxUntouched() throws Exception {
    File dir = folder.newFolder("bankstand");
    EventOutbox events = new EventOutbox(new File(dir, "events.json"), new Gson());
    events.add(1L, new TransientEvent(TransientEvent.TYPE_PET_DROP, Collections.emptyMap()));
    LootOutbox loot = new LootOutbox(new File(dir, "loot-outbox.json"), new Gson());
    List<LootEntry> many = new ArrayList<>();
    for (int i = 0; i < LootOutbox.MAX_PENDING * 2; i++) {
      many.add(entry("e" + i));
    }
    loot.addAll(many);

    assertEquals(1, events.pending().size());
    assertEquals(TransientEvent.TYPE_PET_DROP, events.pending().get(0).getEvent().getType());
  }

  @Test
  public void acksRemoveExactlyTheNamedRecords() throws Exception {
    File file = new File(folder.newFolder("bankstand"), "loot-outbox.json");
    LootOutbox outbox = new LootOutbox(file, new Gson());
    outbox.addAll(java.util.Arrays.asList(entry("a"), entry("b"), entry("c")));
    outbox.ack(Collections.singleton("b"));
    assertEquals(2, outbox.pending().size());
    assertEquals("c", outbox.pending().get(1).getEvent().getId());
  }

  @Test
  public void storedAndTerminalRejectionsAreAckedEverythingElseStays() {
    Set<String> ids =
        LootOutbox.idsToAck(
            acks(
                "{\"acks\":["
                    + "{\"id\":\"stored\",\"outcome\":\"stored\"},"
                    + "{\"id\":\"dup\",\"outcome\":\"duplicate\"},"
                    + "{\"id\":\"invalid\",\"outcome\":\"rejected\",\"reason\":\"invalid\"},"
                    + "{\"id\":\"quota\",\"outcome\":\"rejected\",\"reason\":\"quota\"},"
                    + "{\"id\":\"stale\",\"outcome\":\"rejected\",\"reason\":\"stale\"},"
                    + "{\"id\":\"off\",\"outcome\":\"rejected\",\"reason\":\"not_applied\"},"
                    + "{\"id\":\"unknown\",\"outcome\":\"rejected\",\"reason\":\"something_new\"}"
                    + "]}"));
    assertEquals(4, ids.size());
    assertTrue(ids.contains("stored"));
    assertTrue(ids.contains("dup"));
    assertTrue(ids.contains("invalid"));
    assertTrue(ids.contains("stale"));
  }

  @Test
  public void aQuotaRejectionStaysPendingLikeTheEventOutbox() {
    String json =
        "{\"acks\":[{\"id\":\"q\",\"outcome\":\"rejected\",\"reason\":\"quota\"}]}";
    assertTrue(LootOutbox.idsToAck(acks(json)).isEmpty());
    assertTrue(EventOutbox.idsToAck(acks(json)).isEmpty());
  }
}

