    assertFalse(NotableDropCapture.qualifies("Some other untradeable", false, null, 1, 0L, allowlist));
  }

  @Test
  public void payloadCarriesNullValueForAnUntradeableDrop() {
    Map<String, Object> payload = NotableDropCapture.payload("Ancient icon", 12791, 1, null, "Nex");
    assertEquals("Ancient icon", payload.get("itemName"));
    assertEquals(12791, payload.get("itemId"));
    assertEquals(1, payload.get("quantity"));
    assertEquals(null, payload.get("value"));
    assertEquals("Nex", payload.get("source"));
  }

  @Test
  public void payloadCarriesTheTotalValueForATradeableDrop() {
    Map<String, Object> payload = NotableDropCapture.payload("Dragon warhammer", 13576, 1, 30_000_000L, "Wintertodt");
    assertEquals(30_000_000L, payload.get("value"));
  }

  /**
   * The toggle gates the read itself. {@code itemManager} is null, so reading before the
   * gate would throw.
   */
  @Test
  public void handleLootTouchesNothingWhenDisabled() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    NotableDropCapture capture =
        new NotableDropCapture(outbox, () -> false, () -> 1L, null, () -> 0L, NO_ALLOWLIST);

    capture.handleLoot("Nex", Collections.singletonList(new ItemStack(12791, 1)));

    assertTrue(outbox.pending().isEmpty());
  }

  /** PvP loot would send the other player's name as the source, so only NPC loot is heard. */
  @Test
  public void subscribesToNpcLootOnly() {
    for (Method m : NotableDropCapture.class.getMethods()) {
      if (m.isAnnotationPresent(Subscribe.class)) {
        assertEquals(m.getName(), NpcLootReceived.class, m.getParameterTypes()[0]);
      }
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class NoticeGateTest {

  @Test
  public void announcesTheFirstFailure() {
    NoticeGate gate = new NoticeGate();
    assertTrue(gate.onFailure("Could not reach Bankstand."));
  }

  @Test
  public void suppressesTheSameFailureRepeating() {
    // The cycle runs every 60s, so an unreachable server would repeat the line forever.
    NoticeGate gate = new NoticeGate();
    gate.onFailure("Could not reach Bankstand.");
    assertFalse(gate.onFailure("Could not reach Bankstand."));
    assertFalse(gate.onFailure("Could not reach Bankstand."));
  }

  @Test
  public void announcesAFailureThatChanges() {
    // A different reason is new information.
    NoticeGate gate = new NoticeGate();
    gate.onFailure("Could not reach Bankstand.");
    assertTrue(gate.onFailure("Your device token is no longer valid."));
  }

  @Test
  public void announcesRecoveryOnlyWhenSomethingWasWrong() {
    NoticeGate gate = new NoticeGate();
    assertFalse(gate.onSuccess());

    gate.onFailure("Could not reach Bankstand.");
    assertTrue(gate.onSuccess());
    assertFalse(gate.onSuccess());
  }

  @Test
  public void announcesTheSameFailureAgainAfterARecovery() {
    // A failure returning after it cleared is news.
    NoticeGate gate = new NoticeGate();
    gate.onFailure("Could not reach Bankstand.");
    gate.onSuccess();
    assertTrue(gate.onFailure("Could not reach Bankstand."));
  }

  @Test
  public void treatsAMissingReasonAsItsOwnState() {
    // getMessage() is nullable; null must not throw or match a real failure.
    NoticeGate gate = new NoticeGate();
    assertTrue(gate.onFailure(null));
    assertFalse(gate.onFailure(null));
    assertTrue(gate.onFailure("Could not reach Bankstand."));
  }
}

