package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.time.Instant;
import java.util.Collections;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class PairingQueuesTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private static final long ACCOUNT = 7L;

  @Test
  public void dropLeavesNothingFromTheOldPairingToSendUnderTheNextOne() throws IOException {
    File dir = folder.newFolder("bankstand");
    Gson gson = new Gson();
    PresenceQueue presence = new PresenceQueue();
    presence.addTransition(new PresenceSignal(PresenceSignal.LOGIN, ACCOUNT, 1L));
    EventOutbox events = new EventOutbox(new File(dir, "events.json"), gson);
    events.add(
        ACCOUNT,
        new TransientEvent(
            "e1", TransientEvent.TYPE_NOTABLE_DROP, "2026-10-22T10:00:00Z", Collections.emptyMap()));
    LootLedger ledger = new LootLedger();
    ledger.record(ACCOUNT, 1, "Rat", Collections.singletonMap(526, 1), Instant.now());
    LootOutbox loot = new LootOutbox(new File(dir, "loot.json"), gson);
    loot.addAll(ledger.closeAll());
    ledger.record(ACCOUNT, 2, "Goblin", Collections.singletonMap(526, 1), Instant.now());
    assertEquals(1, loot.pending().size());

    PairingQueues queues = new PairingQueues(presence, events, ledger, loot, () -> null);
    boolean[] swappedFirst = {false};
    PairingQueues.Dropped dropped =
        queues.replace(
            () -> {
              swappedFirst[0] = !events.pending().isEmpty();
              return true;
            });
    assertEquals(1, dropped.events);
    assertEquals("one queued and one still open", 2, dropped.loot);
    assertEquals(
        "Re-paired: 1 queued event and 2 loot drops from the previous pairing were discarded.",
        dropped.repairNotice());
    assertTrue("the pairing is swapped before its queues are dropped", swappedFirst[0]);

    assertEquals(0, presence.size());
    assertTrue(events.pending().isEmpty());
    assertTrue("an open loot window is not closed into the next pairing", ledger.closeAll().isEmpty());
    assertTrue(loot.pending().isEmpty());
    // On disk too, so a restart does not bring them back.
    assertTrue(new EventOutbox(new File(dir, "events.json"), gson).pending().isEmpty());
    assertTrue(new LootOutbox(new File(dir, "loot.json"), gson).pending().isEmpty());
  }

  // The plugin needs a live client to run, so its re-pairing is pinned on the source.
  @Test
  public void aNewPairingDropsTheOldQueueAndRevokesTheOldTokenWhereItWasPaired()
      throws IOException {
    String source =
        new String(
            Files.readAllBytes(
                Paths.get("src", "main", "java", "com", "bankstand", "BankstandPlugin.java")),
            StandardCharsets.UTF_8);
    int start = source.indexOf("private Stored storeToken(");
    String body = source.substring(start, source.indexOf("\n  }\n", start));

    int previous = body.indexOf("DeviceCredentials previous = deviceStore.load();");
    int replace =
        body.indexOf(
            "boolean saved = deviceStore.save(DeviceCredentials.of(res, url));");
    int revoke = body.indexOf("previous.pairedServerUrl(), previous.getToken()");
    assertTrue("reads the old pairing before replacing it", previous >= 0 && previous < replace);
    assertTrue("revokes the old token at the server it was paired with", revoke > replace);
  }

  @Test
  public void aSendHoldingTheLockKeepsThePairingFromChangingUnderIt() throws Exception {
    PairingQueues queues =
        new PairingQueues(
            new PresenceQueue(),
            new EventOutbox(new File(folder.newFolder("q"), "events.json"), new Gson()),
            new LootLedger(),
            new LootOutbox(new File(folder.getRoot(), "q/loot.json"), new Gson()),
            () -> null);
    java.util.concurrent.CountDownLatch swapped = new java.util.concurrent.CountDownLatch(1);
    Thread pairing;
    synchronized (queues) {
      pairing = new Thread(() -> queues.replace(
                      () -> {
                        swapped.countDown();
                        return true;
                      }));
      pairing.start();
      assertTrue(
          "the swap waits for the send's read",
          !swapped.await(200, java.util.concurrent.TimeUnit.MILLISECONDS));
    }
    assertTrue(swapped.await(5, java.util.concurrent.TimeUnit.SECONDS));
    pairing.join();
  }

  @Test
  public void theRepairNoticeCountsWhatWasDroppedAndIsSilentWhenNothingWas() {
    assertNull(new PairingQueues.Dropped(0, 0, true).repairNotice());
    assertEquals(
        "Re-paired: 12 queued events and 3 loot drops from the previous pairing were discarded.",
        new PairingQueues.Dropped(12, 3, true).repairNotice());
    assertEquals(
        "Re-paired: 1 loot drop from the previous pairing was discarded.",
        new PairingQueues.Dropped(0, 1, true).repairNotice());
    assertEquals(
        "Re-paired: 2 queued events from the previous pairing were discarded.",
        new PairingQueues.Dropped(2, 0, true).repairNotice());
  }

  @Test
  public void aNewPairingTellsThePlayerWhatItDiscarded() throws IOException {
    String source =
        new String(
            Files.readAllBytes(
                Paths.get("src", "main", "java", "com", "bankstand", "BankstandPlugin.java")),
            StandardCharsets.UTF_8);
    int start = source.indexOf("private Stored storeToken(");
    String body = source.substring(start, source.indexOf("\n  }\n", start));
    assertTrue(body.contains(".repairNotice();"));
    assertTrue(body.contains("notice(discarded);"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.bankstand.http.HttpResponse;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** A pairing, a disconnect and a slow reply from the pairing before them, in every order. */
public class PairingReplacementTest {

  private static final String ALL_BLOCKS =
      "{\"accepted\":true,\"stored\":true,\"storedBlocks\":"
          + "[\"skills\",\"quests\",\"diaries\",\"collectionLog\",\"combatAchievements\"]}";

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private PluginHarness h;

  private final Map<String, Integer> skills = map("attack", 100);
  private final Map<String, String> quests = map("Cook's Assistant", "FINISHED");
  private final Map<String, String> diaries = map("Varrock Easy", "COMPLETE");
  private final Map<String, Integer> caCounts = map("easy", 3);
  private final Set<Integer> clog = new LinkedHashSet<>(Collections.singletonList(13262));

  private static <V> Map<String, V> map(String key, V value) {
    Map<String, V> m = new LinkedHashMap<>();
    m.put(key, value);
    return m;
  }

  @Before
  public void setUp() throws Exception {
    h = new PluginHarness(folder.getRoot());
    // Each code pairs to its own token, so the test can see which reply was kept.
    h.transport.byPath.put(
        "/pair",
        body -> {
          String code = body.contains("AAAAAAAA") ? "a" : "b";
          return new HttpResponse(
              200, "{\"deviceToken\":\"tok-" + code + "\",\"deviceId\":\"d\",\"expiresAt\":null}");
        });
    h.transport.byPath.put("/submit", body -> new HttpResponse(200, ALL_BLOCKS));
    h.logIn();
    h.executor.runAll();
  }

  private void submitSnapshot() throws Exception {
    h.call(
        "submitSnapshot",
        caCounts,
        null,
        PluginHarness.MAIN,
        h.generation(),
        "Zezima",
        skills,
        quests,
        diaries,
        null,
        clog,
        null,
        false,
        null,
        null,
        null);
  }

  private String token() {
    return h.deviceStore.load().getToken();
  }

  private boolean questsAcked() throws Exception {
    return !((QuestBaseline) h.get("questBaseline")).changedSince(quests);
  }

  @Test
  public void aPairingReplyAfterADisconnectIsDropped() throws Exception {
    h.call("pair", "AAAA-AAAA");
    h.call("disconnect");
    h.executor.runAll();
    assertFalse(h.deviceStore.load().isPaired());
  }

  @Test
  public void anOlderPairingReplyNeverOverwritesANewerOne() throws Exception {
    h.call("pair", "AAAA-AAAA");
    h.call("pair", "BBBB-BBBB");
    Runnable older = h.executor.take();
    h.executor.runAll(); // the newer pairing answers first
    assertEquals("tok-b", token());
    older.run();
    assertEquals("tok-b", token());
  }

  @Test
  public void aSnapshotAckedBeforeAReplaceAdvancesItsBaselines() throws Exception {
    submitSnapshot();
    h.executor.runAll();
    assertTrue("control: the same flow advances when nothing replaced it", questsAcked());
  }

  @Test
  public void aSnapshotAckedAfterAReplaceDoesNotAdvanceBaselines() throws Exception {
    submitSnapshot();
    Runnable inFlight = h.executor.take();
    h.call("pair", "BBBB-BBBB");
    h.executor.runAll();
    inFlight.run();
    h.executor.runAll();
    assertFalse(questsAcked());
    assertNull(h.ackedStore.load(PluginHarness.MAIN).getQuests());
  }

  @Test
  public void aLoadStartedBeforeARePairNeverRestoresTheOldAcks() throws Exception {
    submitSnapshot();
    h.executor.runAll();
    assertTrue(questsAcked());

    // A restart: the load is queued at login, and a re-pair lands while it is in flight.
    h = new PluginHarness(folder.getRoot());
    h.transport.byPath.put(
        "/pair", body -> new HttpResponse(200, "{\"deviceToken\":\"tok-b\",\"deviceId\":\"d\"}"));
    h.onClientThread = false;
    h.logIn();
    Runnable load = h.executor.take();
    h.call("pair", "BBBB-BBBB");
    h.executor.runAll();
    load.run();
    h.runClientThread();
    h.executor.runAll();
    assertFalse(questsAcked());
  }

  @Test
  public void aStaleRejectionLeavesNoFailureOnTheNewPairing() throws Exception {
    h.transport.byPath.put(
        "/submit",
        body -> {
          DeviceCredentials current = h.deviceStore.load();
          DeviceCredentials next = DeviceCredentials.none();
          next.setToken("tok-new");
          next.setServerUrl(current.getServerUrl());
          next.setPairingId("second");
          h.deviceStore.save(next);
          return new HttpResponse(401, "");
        });
    submitSnapshot();
    h.executor.runAll();
    assertNull(((SyncFailures) h.get("failures")).shown());
    assertFalse(((SubmitGate) h.get("submitGate")).isHalted());
  }

  @Test
  public void pairingAndDisconnectClearTheLastFailure() throws Exception {
    ((SyncFailures) h.get("failures")).snapshotFailed(new SubmitException("Bankstand is busy."), PluginHarness.MAIN, h.generation());
    h.call("pair", "AAAA-AAAA");
    h.executor.runAll();
    assertNull(((SyncFailures) h.get("failures")).shown());
    ((SyncFailures) h.get("failures")).snapshotFailed(new SubmitException("Bankstand is busy."), PluginHarness.MAIN, h.generation());
    h.call("disconnect");
    assertNull(((SyncFailures) h.get("failures")).shown());
  }

  @Test
  public void aPairingThatChangesNothingNeverBlocksTheLoad() throws Exception {
    submitSnapshot();
    h.executor.runAll();
    // A restart; a pairing starts during the load and fails to save, so nothing was forgotten.
    h = new PluginHarness(folder.getRoot());
    h.transport.byPath.put(
        "/pair", body -> new HttpResponse(200, "{\"deviceToken\":\"tok-b\",\"deviceId\":\"d\"}"));
    h.onClientThread = false;
    h.logIn();
    Runnable load = h.executor.take();
    java.io.File device = new java.io.File(folder.getRoot(), "device.json");
    assertTrue(device.delete());
    assertTrue(new java.io.File(device, "x").mkdirs());
    h.call("pair", "BBBB-BBBB");
    h.executor.runAll();
    load.run();
    h.runClientThread();
    h.executor.runAll();
    assertTrue("the acks on disk were restored", questsAcked());
  }

  @Test
  public void aLoginBetweenTheSwapAndTheResetNeverRestoresTheOldAcks() throws Exception {
    submitSnapshot();
    h.executor.runAll();
    h = new PluginHarness(folder.getRoot());
    h.transport.byPath.put(
        "/pair", body -> new HttpResponse(200, "{\"deviceToken\":\"tok-b\",\"deviceId\":\"d\"}"));
    h.onClientThread = false;
    h.call("pair", "BBBB-BBBB");
    h.executor.runAll(); // swapped on the executor; the reset waits for the client thread
    h.logIn();
    h.executor.runAll(); // the login's load reads the old acks
    h.runClientThread(); // the reset, then the load's apply
    h.executor.runAll();
    assertFalse(questsAcked());
  }

  @Test
  public void anAckLandingAfterTheResetIsDropped() throws Exception {
    h.transport.byPath.put(
        "/submit",
        body -> {
          try {
            h.call("forgetAcks"); // a re-pair's reset lands while the request is out
          } catch (Exception e) {
            throw new AssertionError(e);
          }
          return new HttpResponse(200, ALL_BLOCKS);
        });
    submitSnapshot();
    h.executor.runAll();
    assertFalse(questsAcked());
  }

  @Test
  public void aShutdownMidPairingStoresNothingAndRevokesTheNewToken() throws Exception {
    h.call("pair", "AAAA-AAAA");
    Runnable pairing = h.executor.take();
    h.plugin.shutDown();
    pairing.run();
    h.executor.runAll();
    assertEquals("device-token", token());
    assertEquals("only the orphaned new token is revoked", 1, h.transport.count("/unpair"));
  }

  @Test
  public void aPairingAnsweredAfterTheServerUrlChangedIsNotReportedAsConnected() throws Exception {
    h.call("pair", "AAAA-AAAA");
    h.serverUrl = "https://other.example";
    h.executor.runAll();
    String said = String.join("\n", h.notices());
    assertFalse(said, said.contains("Connected."));
    assertTrue(said, said.contains("Server URL changed"));
  }

  @Test
  public void aRelogBetweenTheRequestAndTheAckAdvancesNothing() throws Exception {
    submitSnapshot();
    Runnable inFlight = h.executor.take();
    h.state(net.runelite.api.GameState.LOGIN_SCREEN);
    h.logIn();
    h.executor.runAll();
    inFlight.run();
    h.executor.runAll();
    assertFalse(questsAcked());
  }

  @Test
  public void reAndDisconnectEachRevokeExactlyOnce() throws Exception {
    h.call("pair", "AAAA-AAAA");
    h.executor.runAll();
    assertEquals("re-pair revokes the old token", 1, h.transport.count("/unpair"));
    h.call("disconnect");
    h.executor.runAll();
    assertEquals("disconnect revokes the new one", 2, h.transport.count("/unpair"));
  }

  @Test
  public void disconnectWithoutAClientStillForgetsThePairing() throws Exception {
    h.set("pairingClient", null);
    h.call("disconnect");
    assertFalse(h.deviceStore.load().isPaired());
  }

  @Test
  public void pairingWithAnotherServerResendsEveryBlock() throws Exception {
    ((CollectionLogAccumulator) h.get("collectionLog")).restore(new LinkedHashSet<>(clog));
    submitSnapshot();
    h.executor.runAll();
    assertTrue(questsAcked());

    h.serverUrl = "https://other.example";
    h.call("pair", "BBBB-BBBB");
    h.executor.runAll();

    assertFalse("quests", questsAcked());
    assertTrue("diaries", ((DiaryBaseline) h.get("diaryBaseline")).changedSince(diaries));
    assertTrue(
        "combat achievements",
        ((CombatAchievementBaseline) h.get("combatAchievementBaseline")).changedSince(caCounts));
    assertTrue(
        "collection log",
        ((CollectionLogBaseline) h.get("collectionLogBaseline")).changedSince(clog.size()));
    AckedState disk = h.ackedStore.load(PluginHarness.MAIN);
    assertNull(disk.getQuests());
    assertNull(disk.getDiaries());
    assertNull(disk.getCombatAchievements());
    assertEquals(-1, disk.getCollectionLogAcked());
    assertEquals("what the player browsed is kept", clog, disk.getCollectionLogItems());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.bankstand.dto.PairResponse;
import com.google.gson.Gson;
import java.io.File;
import java.time.Instant;
import java.util.Collections;
import java.util.function.Supplier;
import org.junit.Assume;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class PairingTagTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private static final long ACCOUNT = 7L;
  private final Gson gson = new Gson();

  private static TransientEvent event(String id) {
    return new TransientEvent(
        id, TransientEvent.TYPE_NOTABLE_DROP, "2026-10-22T10:00:00Z", Collections.emptyMap());
  }

  private EventOutbox events(File dir, Supplier<String> pairing) {
    EventOutbox outbox = new EventOutbox(new File(dir, "events.json"), gson);
    outbox.setPairing(pairing);
    return outbox;
  }

  private LootOutbox loot(File dir, Supplier<String> pairing) {
    LootOutbox outbox = new LootOutbox(new File(dir, "loot.json"), gson);
    outbox.setPairing(pairing);
    return outbox;
  }

  @Test
  public void aFailedClearOnRepairNeverSendsTheOldQueueAfterARestart() throws Exception {
    File dir = folder.newFolder("bankstand");
    String[] pairing = {"pairing-a"};
    EventOutbox events = events(dir, () -> pairing[0]);
    LootLedger ledger = new LootLedger();
    LootOutbox loot = loot(dir, () -> pairing[0]);
    PairingQueues queues = new PairingQueues(new PresenceQueue(), events, ledger, loot, () -> pairing[0]);
    events.add(ACCOUNT, event("e1"));
    ledger.record(ACCOUNT, 1, "Rat", Collections.singletonMap(526, 1), Instant.now());
    loot.addAll(ledger.closeAll());

    // The disk refuses the clear: the old entries stay in the files.
    Assume.assumeTrue(dir.setWritable(false));
    try {
      queues.replace(
          () -> {
            pairing[0] = "pairing-b";
            return true;
          });
    } finally {
      dir.setWritable(true);
    }
    assertEquals("the clear really failed", 1, events(dir, () -> "pairing-a").pending().size());
    assertEquals("the clear really failed", 1, loot(dir, () -> "pairing-a").pending().size());

    // Restart under the new pairing: nothing from the old one is handed to a sender.
    assertTrue(events(dir, () -> "pairing-b").pending().isEmpty());
    assertTrue(loot(dir, () -> "pairing-b").pending().isEmpty());
    // And it is gone from disk once a write succeeds.
    assertTrue(events(dir, () -> "pairing-a").pending().isEmpty());
    assertTrue(loot(dir, () -> "pairing-a").pending().isEmpty());
  }

  @Test
  public void aLootWindowOpenedUnderTheOldPairingIsNeverSentUnderTheNewOne() throws Exception {
    File dir = folder.newFolder("bankstand");
    String[] pairing = {"pairing-a"};
    LootLedger ledger = new LootLedger();
    ledger.setPairing(() -> pairing[0]);
    ledger.record(ACCOUNT, 1, "Rat", Collections.singletonMap(526, 1), Instant.now());
    // Closed before the swap, added to the outbox after it.
    java.util.List<LootEntry> closed = ledger.closeAll();
    pairing[0] = "pairing-b";
    LootOutbox loot = loot(dir, () -> pairing[0]);
    loot.addAll(closed);
    assertTrue(loot.pending().isEmpty());
  }

  @Test
  public void entriesFromTheSamePairingAreKeptAndSent() throws Exception {
    File dir = folder.newFolder("bankstand");
    events(dir, () -> "pairing-a").add(ACCOUNT, event("e1"));
    assertEquals(1, events(dir, () -> "pairing-a").pending().size());
  }

  @Test
  public void aQueueFromBeforePairingsWereTaggedStaysWithThatPairingOnly() throws Exception {
    File dir = folder.newFolder("bankstand");
    // Both untagged: written by an older version, still paired the old way.
    events(dir, () -> null).add(ACCOUNT, event("e1"));
    assertEquals(1, events(dir, () -> null).pending().size());
    assertTrue(events(dir, () -> "pairing-b").pending().isEmpty());
  }

  @Test
  public void everyPairingGetsItsOwnLocalId() {
    PairResponse res =
        new Gson().fromJson("{\"deviceToken\":\"t\",\"deviceId\":\"d\"}", PairResponse.class);
    String first = DeviceCredentials.of(res, BankstandKeys.DEFAULT_SERVER_URL).getPairingId();
    String second = DeviceCredentials.of(res, BankstandKeys.DEFAULT_SERVER_URL).getPairingId();
    assertTrue(first != null && !first.isEmpty());
    assertNotEquals("even the same server and device id get a new one", first, second);
  }
}

