package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class PetDropCaptureTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  @Test
  public void recognisesBothPrimeMessageForms() {
    assertTrue(PetDropCapture.isPrimeMessage("You have a funny feeling like you're being followed."));
    assertTrue(PetDropCapture.isPrimeMessage("You feel something weird sneaking into your backpack."));
  }

  @Test
  public void anUnrelatedMessageDoesNotPrime() {
    assertFalse(PetDropCapture.isPrimeMessage("You have received a drop: Coins."));
  }

  @Test
  public void resolvesAKnownPetFromTheCollectionLogLine() {
    String name = PetDropCapture.resolvePetName("New item added to your collection log: Baby mole");
    assertEquals("Baby mole", name);
  }

  @Test
  public void resolvesAKnownPetFromTheUntradeableDropLine() {
    String name = PetDropCapture.resolvePetName("Untradeable drop: Heron");
    assertEquals("Heron", name);
  }

  @Test
  public void aNonPetUntradeableIsIgnored() {
    assertNull(PetDropCapture.resolvePetName("Untradeable drop: Clue scroll (elite)"));
  }

  /** Broadcasts use the pet's real display casing, so matching must be case-insensitive. */
  @Test
  public void resolvesAKnownPetRegardlessOfCasing() {
    assertEquals(
        "TzRek-Jad",
        PetDropCapture.resolvePetName("Untradeable drop: TzRek-Jad"));
    assertEquals(
        "Baby Mole",
        PetDropCapture.resolvePetName("New item added to your collection log: Baby Mole"));
    assertEquals(
        "Giant Squirrel",
        PetDropCapture.resolvePetName("Untradeable drop: Giant Squirrel"));
    assertEquals(
        "Pet Dagannoth Prime",
        PetDropCapture.resolvePetName("Untradeable drop: Pet Dagannoth Prime"));
  }

  @Test
  public void resolvesPetsFromTheFullCollectionLog() {
    assertEquals("Phoenix", PetDropCapture.resolvePetName("Untradeable drop: Phoenix"));
    assertEquals(
        "Pet Zilyana",
        PetDropCapture.resolvePetName("New item added to your collection log: Pet Zilyana"));
    assertEquals(
        "Tumeken's guardian",
        PetDropCapture.resolvePetName("Untradeable drop: Tumeken's guardian"));
  }

  @Test
  public void anUnrecognisedMessageResolvesToNull() {
    assertNull(PetDropCapture.resolvePetName("Congratulations, you've completed a hard Combat Task."));
  }

  @Test
  public void payloadCarriesTheNameAndNoSource() {
    java.util.Map<String, Object> payload = PetDropCapture.payload("Baby mole");
    assertEquals("Baby mole", payload.get("petName"));
    assertNull(payload.get("source"));
  }

  /** The toggle gates emitting, not the one-shot prime tracking. */
  @Test
  public void handleMessageEmitsNothingWhenDisabled() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    PetDropCapture capture = new PetDropCapture(outbox, () -> false, () -> 1L);

    capture.handleMessage("You have a funny feeling like you're being followed.");
    capture.handleMessage("New item added to your collection log: Baby mole");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void anUnrelatedLineInTheWindowDoesNotConsumeThePrime() throws IOException {
    EventOutbox outbox = outbox();
    PetDropCapture capture = new PetDropCapture(outbox, () -> true, () -> 1L);
    feed(capture, PRIME, "Untradeable drop: Clue scroll (elite)", "Untradeable drop: Heron");
    assertOnePet(outbox, "Heron");
  }

  /** A toggle-off between prime and resolve must still consume the prime, or it stays stuck. */
  @Test
  public void aPrimeConsumedWhileDisabledIsNotWronglyResolvedAfterReEnabling() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    boolean[] enabled = {true};
    PetDropCapture capture = new PetDropCapture(outbox, () -> enabled[0], () -> 1L);

    capture.handleMessage("You have a funny feeling like you're being followed.");
    enabled[0] = false;
    capture.handleMessage("Untradeable drop: Heron");
    enabled[0] = true;
    // No active prime remains, so this must not resolve anything.
    capture.handleMessage("Untradeable drop: Baby mole");

    assertTrue(outbox.pending().isEmpty());
  }

  private static final String KC = "Your Kraken kill count is: 1,872.";
  private static final String PRIME = "You have a funny feeling like you're being followed.";
  private static final String INSURED =
      "Your new pet has been automatically insured. If lost, it can be reclaimed from Probita in Ardougne.";

  private EventOutbox outbox() throws IOException {
    return new EventOutbox(new File(folder.newFolder("bankstand"), "events.json"), new Gson());
  }

  private static void feed(PetDropCapture capture, String... lines) {
    for (String line : lines) capture.handleMessage(line);
  }

  private static void assertOnePet(EventOutbox outbox, String name) {
    assertEquals(1, outbox.pending().size());
    assertEquals(name, outbox.pending().get(0).getEvent().getPayload().get("petName"));
  }

  @Test
  public void resolvesPastThePetInsuranceLine() throws IOException {
    EventOutbox outbox = outbox();
    PetDropCapture capture = new PetDropCapture(outbox, () -> true, () -> 1L);
    feed(capture, KC, PRIME, INSURED,
        "New item added to your collection log: Pet kraken", "Untradeable drop: Pet kraken");
    assertOnePet(outbox, "Pet kraken");
  }

  @Test
  public void resolvesPastThePetInsuranceLineWithTitleCase() throws IOException {
    EventOutbox outbox = outbox();
    PetDropCapture capture = new PetDropCapture(outbox, () -> true, () -> 1L);
    feed(capture, KC, PRIME, INSURED,
        "New item added to your collection log: Pet Kraken", "Untradeable drop: Pet Kraken");
    assertOnePet(outbox, "Pet Kraken");
  }

  @Test
  public void resolvesWithoutTheInsuranceLine() throws IOException {
    EventOutbox outbox = outbox();
    PetDropCapture capture = new PetDropCapture(outbox, () -> true, () -> 1L);
    feed(capture, KC, PRIME, "Untradeable drop: Pet kraken");
    assertOnePet(outbox, "Pet kraken");
  }

  @Test
  public void aPrimeOutsideTheWindowResolvesNothing() throws IOException {
    EventOutbox outbox = outbox();
    PetDropCapture capture = new PetDropCapture(outbox, () -> true, () -> 1L);
    feed(capture, PRIME, "a", "b", "c", "d", "Untradeable drop: Pet kraken");
    assertTrue(outbox.pending().isEmpty());
  }
}

package com.bankstand;

import com.bankstand.http.HttpResponse;
import com.bankstand.http.HttpTransport;
import com.bankstand.session.AccountSession;
import com.google.gson.Gson;
import java.io.File;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.AbstractExecutorService;
import java.util.concurrent.Callable;
import java.util.concurrent.Delayed;
import java.util.concurrent.FutureTask;
import java.util.concurrent.RunnableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;

/**
 * A paired plugin wired to fakes: a client, config, an executor the test drives by hand, and a
 * transport that records every request. Nothing reaches a network or RuneLite.
 */
final class PluginHarness {

  static final long MAIN = 42L;
  static final int[] LUMBRIDGE = {12850};
  static final int[] LMS_ARENA = {13658};

  // What the fake client and config report.
  Set<WorldType> world = EnumSet.of(WorldType.MEMBERS);
  int[] regions = LUMBRIDGE;
  long hash = MAIN;
  GameState gameState = GameState.LOGGED_IN;
  int xp;
  // False queues clientThread.invoke work until runClientThread, so a test can order it.
  boolean onClientThread = true;
  final Map<Integer, Integer> varps = new HashMap<>();
  final Map<Integer, Integer> varbits = new HashMap<>();
  String serverUrl = BankstandKeys.DEFAULT_SERVER_URL;
  final Map<String, Boolean> toggles = new HashMap<>();

  final ManualExecutor executor = new ManualExecutor();
  final RecordingTransport transport = new RecordingTransport();
  final BankstandPlugin plugin = new BankstandPlugin();
  final DeviceCredentialStore deviceStore;
  final AckedStateStore ackedStore;
  final EventOutbox eventOutbox;
  final LootOutbox lootOutbox;

  PluginHarness(File dir) throws Exception {
    Gson gson = new Gson();
    Client client =
        (Client)
            Proxy.newProxyInstance(
                Client.class.getClassLoader(),
                new Class<?>[] {Client.class},
                (proxy, method, args) -> {
                  switch (method.getName()) {
                    case "getWorldType":
                      return world;
                    case "getMapRegions":
                      return regions;
                    case "getAccountHash":
                      return hash;
                    case "isClientThread":
                      return onClientThread;
                    case "getGameState":
                      return gameState;
                    case "getLocalPlayer":
                      return localPlayer();
                    case "getSkillExperience":
                      return xp;
                    case "getVarpValue":
                      return varps.getOrDefault((Integer) args[0], 0);
                    case "getVarbitValue":
                      return args.length == 1 ? varbits.getOrDefault((Integer) args[0], 0) : 0;
                    default:
                      return zero(method.getReturnType());
                  }
                });
    BankstandConfig config =
        (BankstandConfig)
            Proxy.newProxyInstance(
                BankstandConfig.class.getClassLoader(),
                new Class<?>[] {BankstandConfig.class},
                (proxy, method, args) -> {
                  if (method.getReturnType() == boolean.class) {
                    return toggles.getOrDefault(method.getName(), Boolean.TRUE);
                  }
                  if ("serverBaseUrl".equals(method.getName())) {
                    return serverUrl;
                  }
                  return zero(method.getReturnType());
                });
    deviceStore = new DeviceCredentialStore(new File(dir, "device.json"), gson);
    DeviceCredentials paired = DeviceCredentials.none();
    paired.setToken("device-token");
    paired.setServerUrl(serverUrl);
    paired.setPairingId("first");
    deviceStore.save(paired);
    ackedStore = new AckedStateStore(new File(dir, "acked.json"), gson);
    eventOutbox = new EventOutbox(new File(dir, "events.json"), gson);
    lootOutbox = new LootOutbox(new File(dir, "loot.json"), gson);

    ClientThread clientThread = new ClientThread();
    Field threadClient = ClientThread.class.getDeclaredField("client");
    threadClient.setAccessible(true);
    threadClient.set(clientThread, client);

    set("client", client);
    set("config", config);
    set("clientThread", clientThread);
    set("executor", executor);
    set("configManager", configManager(dir));
    set("chatMessageManager", chatMessageManager());
    set("deviceStore", deviceStore);
    set("ackedStore", ackedStore);
    set("eventOutbox", eventOutbox);
    set("lootOutbox", lootOutbox);
    set("gson", gson);
    set("pairingClient", call("newClient", transport));
    set(
        "pairingQueues",
        new PairingQueues(
            (PresenceQueue) get("presenceQueue"),
            eventOutbox,
            (LootLedger) get("lootLedger"),
            lootOutbox,
            PairingQueues.pairingOf(deviceStore)));
  }

  /** A real ConfigManager over a scratch file, built without RuneLite's injector. */
  private static ConfigManager configManager(File dir) throws Exception {
    ConfigManager manager = (ConfigManager) unsafe().allocateInstance(ConfigManager.class);
    Class<?> dataType = Class.forName("net.runelite.client.config.ConfigData");
    Constructor<?> data = dataType.getDeclaredConstructor(File.class);
    data.setAccessible(true);
    setField(manager, "configProfile", data.newInstance(new File(dir, "runelite.properties")));
    setField(manager, "eventBus", new EventBus());
    Constructor<?> handler =
        Class.forName("net.runelite.client.config.ConfigInvocationHandler")
            .getDeclaredConstructor(ConfigManager.class);
    handler.setAccessible(true);
    setField(manager, "handler", handler.newInstance(manager));
    return manager;
  }

  private static net.runelite.api.Player localPlayer() {
    return (net.runelite.api.Player)
        Proxy.newProxyInstance(
            net.runelite.api.Player.class.getClassLoader(),
            new Class<?>[] {net.runelite.api.Player.class},
            (proxy, method, args) ->
                "getName".equals(method.getName()) ? "Zezima" : zero(method.getReturnType()));
  }

  /** Collects chat notices instead of drawing them. */
  private static net.runelite.client.chat.ChatMessageManager chatMessageManager() throws Exception {
    Object manager = unsafe().allocateInstance(net.runelite.client.chat.ChatMessageManager.class);
    setField(manager, "queuedMessages", new java.util.concurrent.ConcurrentLinkedQueue<>());
    return (net.runelite.client.chat.ChatMessageManager) manager;
  }

  /** Every chat notice so far, as formatted text. */
  @SuppressWarnings("unchecked")
  List<String> notices() throws Exception {
    Object manager = get("chatMessageManager");
    Field queue = manager.getClass().getDeclaredField("queuedMessages");
    queue.setAccessible(true);
    List<String> out = new ArrayList<>();
    for (Object message : (java.util.Collection<Object>) queue.get(manager)) {
      out.add(((net.runelite.client.chat.QueuedMessage) message).getRuneLiteFormattedMessage());
    }
    return out;
  }

  /** Runs what the plugin handed the client thread with invokeLater. */
  void runClientThread() throws Exception {
    ClientThread thread = (ClientThread) get("clientThread");
    Method drain = ClientThread.class.getDeclaredMethod("invoke");
    drain.setAccessible(true);
    boolean was = onClientThread;
    onClientThread = true;
    try {
      drain.invoke(thread);
    } finally {
      onClientThread = was;
    }
  }

  private static sun.misc.Unsafe unsafe() throws Exception {
    Field unsafeField = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
    unsafeField.setAccessible(true);
    return (sun.misc.Unsafe) unsafeField.get(null);
  }

  static Object zero(Class<?> type) {
    if (type == boolean.class) {
      return false;
    }
    if (type == int.class) {
      return 0;
    }
    if (type == long.class) {
      return 0L;
    }
    return null;
  }

  private static void setField(Object target, String name, Object value) throws Exception {
    Field field = target.getClass().getDeclaredField(name);
    field.setAccessible(true);
    field.set(target, value);
  }

  void set(String name, Object value) throws Exception {
    Field field = BankstandPlugin.class.getDeclaredField(name);
    field.setAccessible(true);
    field.set(plugin, value);
  }

  Object get(String name) throws Exception {
    Field field = BankstandPlugin.class.getDeclaredField(name);
    field.setAccessible(true);
    return field.get(plugin);
  }

  /** Calls a private plugin method by name; arguments must match its parameter count. */
  Object call(String name, Object... args) throws Exception {
    for (Method method : BankstandPlugin.class.getDeclaredMethods()) {
      if (method.getName().equals(name) && method.getParameterCount() == args.length) {
        method.setAccessible(true);
        return method.invoke(plugin, args);
      }
    }
    throw new NoSuchMethodException(name);
  }

  void state(GameState state) {
    GameStateChanged event = new GameStateChanged();
    event.setGameState(state);
    plugin.onGameStateChanged(event);
  }

  void ticks(int count) {
    for (int i = 0; i < count; i++) {
      plugin.onGameTick(new GameTick());
    }
  }

  void logIn() {
    state(GameState.LOGGED_IN);
    ticks(CaptureGate.SETTLE_TICKS);
  }

  void hopTo(Set<WorldType> type) {
    state(GameState.HOPPING);
    world = type;
    logIn();
  }

  int generation() throws Exception {
    return ((AccountSession) get("session")).getGeneration();
  }

  /** Runs tasks queued on the executor until it is idle. Scheduled (delayed) ones wait. */
  static final class ManualExecutor extends AbstractExecutorService
      implements ScheduledExecutorService {
    final Deque<Runnable> queue = new ArrayDeque<>();
    final List<Runnable> scheduled = new ArrayList<>();
    final List<Throwable> errors = new ArrayList<>();

    @Override
    protected <T> RunnableFuture<T> newTaskFor(Runnable runnable, T value) {
      return newTaskFor(java.util.concurrent.Executors.callable(runnable, value));
    }

    @Override
    protected <T> RunnableFuture<T> newTaskFor(Callable<T> callable) {
      return new FutureTask<T>(callable) {
        @Override
        protected void setException(Throwable t) {
          errors.add(t);
          super.setException(t);
        }
      };
    }

    @Override
    public void execute(Runnable command) {
      queue.add(command);
    }

    /** Pulls the next queued task without running it, so a test can reorder completions. */
    Runnable take() {
      return queue.poll();
    }

    void runAll() {
      Runnable next;
      while ((next = queue.poll()) != null) {
        next.run();
      }
      if (!errors.isEmpty()) {
        throw new AssertionError("a task threw", errors.get(0));
      }
    }

    private ScheduledFuture<?> later(Runnable task) {
      scheduled.add(task);
      return new Stub();
    }

    @Override
    public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
      return later(command);
    }

    @Override
    public <V> ScheduledFuture<V> schedule(Callable<V> callable, long delay, TimeUnit unit) {
      throw new UnsupportedOperationException();
    }

    @Override
    public ScheduledFuture<?> scheduleAtFixedRate(
        Runnable command, long initialDelay, long period, TimeUnit unit) {
      return later(command);
    }

    @Override
    public ScheduledFuture<?> scheduleWithFixedDelay(
        Runnable command, long initialDelay, long delay, TimeUnit unit) {
      return later(command);
    }

    @Override
    public void shutdown() {}

    @Override
    public List<Runnable> shutdownNow() {
      return Collections.emptyList();
    }

    @Override
    public boolean isShutdown() {
      return false;
    }

    @Override
    public boolean isTerminated() {
      return false;
    }

    @Override
    public boolean awaitTermination(long timeout, TimeUnit unit) {
      return true;
    }

    private static final class Stub extends FutureTask<Object> implements ScheduledFuture<Object> {
      Stub() {
        super(() -> null);
      }

      @Override
      public long getDelay(TimeUnit unit) {
        return 0;
      }

      @Override
      public int compareTo(Delayed other) {
        return 0;
      }
    }
  }

  /** Answers each request by its path and keeps every one it saw. */
  static final class RecordingTransport implements HttpTransport {
    final List<String> urls = new ArrayList<>();
    final List<String> bodies = new ArrayList<>();
    Function<String, HttpResponse> answer = body -> new HttpResponse(200, "{}");
    final Map<String, Function<String, HttpResponse>> byPath = new HashMap<>();

    /** A route that answers null loses the response, as a dropped connection does. */
    @Override
    public synchronized HttpResponse post(String url, String body, Map<String, String> headers)
        throws java.io.IOException {
      urls.add(url);
      bodies.add(body);
      HttpResponse response = answer.apply(body);
      for (Map.Entry<String, Function<String, HttpResponse>> route : byPath.entrySet()) {
        if (url.endsWith(route.getKey())) {
          response = route.getValue().apply(body);
          break;
        }
      }
      if (response == null) {
        throw new java.io.IOException("connection lost");
      }
      return response;
    }

    @Override
    public synchronized HttpResponse get(String url, Map<String, String> headers) {
      urls.add(url);
      return new HttpResponse(404, "");
    }

    synchronized long count(String path) {
      return urls.stream().filter(u -> u.endsWith(path)).count();
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

/** The version the server sees must be the version that was built and listed. */
public class PluginVersionTest {

  private static String find(String file, String regex) throws IOException {
    String text = new String(Files.readAllBytes(Paths.get(file)), StandardCharsets.UTF_8);
    Matcher m = Pattern.compile(regex, Pattern.MULTILINE).matcher(text);
    assertTrue(file + " carries a version", m.find());
    return m.group(1);
  }

  @Test
  public void versionMatchesTheBuild() throws IOException {
    assertEquals(find("build.gradle", "^version = '([^']+)'"), PluginVersion.VERSION);
  }

  @Test
  public void versionMatchesTheHubListing() throws IOException {
    assertEquals(find("runelite-plugin.properties", "^version=(\\S+)"), PluginVersion.VERSION);
  }

  @Test
  public void envelopeAndUserAgentUseTheConstant() throws IOException {
    String plugin =
        new String(
            Files.readAllBytes(Paths.get("src/main/java/com/bankstand/BankstandPlugin.java")),
            StandardCharsets.UTF_8);
    assertTrue(plugin.contains("PluginVersion.VERSION"));
    assertTrue(!plugin.contains("getImplementationVersion"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.junit.Test;

public class PresenceQueueTest {

  private static PresenceSignal signal(String state, long nanos) {
    return new PresenceSignal(state, 1L, nanos);
  }

  @Test
  public void onlyLoginAndActiveCarryTheLootFlag() {
    assertEquals(Boolean.TRUE, signal(PresenceSignal.LOGIN, 1).withLoot(true).getLoot());
    assertEquals(Boolean.FALSE, signal(PresenceSignal.ACTIVE, 1).withLoot(false).getLoot());
    assertNull(signal(PresenceSignal.LOGOUT, 1).withLoot(true).getLoot());
    assertNull(signal(PresenceSignal.OFF, 1).withLoot(true).getLoot());
    assertNull(signal(PresenceSignal.LOGIN, 1).getLoot());
  }

  @Test
  public void transitionsGoOutInOrder() {
    PresenceQueue queue = new PresenceQueue();
    PresenceSignal logout = signal(PresenceSignal.LOGOUT, 1);
    PresenceSignal login = signal(PresenceSignal.LOGIN, 2);
    queue.addTransition(logout);
    queue.addTransition(login);

    assertSame(logout, queue.peek());
    queue.onAnswered(logout);
    assertSame(login, queue.peek());
  }

  @Test
  public void aLoginNeverReplacesAnUnacknowledgedLogout() {
    PresenceQueue queue = new PresenceQueue();
    PresenceSignal logout = signal(PresenceSignal.LOGOUT, 1);
    queue.addTransition(logout);
    queue.onRetryableFailure(logout);
    queue.addTransition(signal(PresenceSignal.LOGIN, 2));

    assertEquals(2, queue.size());
    assertSame("the logout is still first, and still owed", logout, queue.peek());
  }

  @Test
  public void aTransitionThatFailsStaysAtTheHead() {
    PresenceQueue queue = new PresenceQueue();
    PresenceSignal logout = signal(PresenceSignal.LOGOUT, 1);
    queue.addTransition(logout);
    queue.onRetryableFailure(logout);
    assertSame(logout, queue.peek());
  }

  @Test
  public void aTerminalFailureDropsTheTransition() {
    PresenceQueue queue = new PresenceQueue();
    PresenceSignal logout = signal(PresenceSignal.LOGOUT, 1);
    queue.addTransition(logout);
    queue.onTerminalFailure(logout);
    assertNull(queue.peek());
  }

  @Test
  public void holdsAtMostEightTransitionsDroppingTheOldest() {
    PresenceQueue queue = new PresenceQueue();
    for (int i = 0; i < PresenceQueue.MAX_TRANSITIONS + 2; i++) {
      queue.addTransition(signal(PresenceSignal.LOGIN, i));
    }
    assertEquals(PresenceQueue.MAX_TRANSITIONS, queue.size());
    assertEquals(2L, queue.peek().getCreatedAtNanos());
  }

  @Test
  public void aHeartbeatIsOneLatestValue() {
    PresenceQueue queue = new PresenceQueue();
    queue.offerHeartbeat(signal(PresenceSignal.ACTIVE, 1));
    PresenceSignal newer = signal(PresenceSignal.ACTIVE, 2);
    queue.offerHeartbeat(newer);
    assertEquals(1, queue.size());
    assertSame(newer, queue.peek());
  }

  @Test
  public void aFailedHeartbeatIsDroppedNotRetried() {
    PresenceQueue queue = new PresenceQueue();
    PresenceSignal active = signal(PresenceSignal.ACTIVE, 1);
    queue.offerHeartbeat(active);
    queue.onRetryableFailure(active);
    assertNull(queue.peek());
  }

  @Test
  public void aHeartbeatOfferedBehindATransitionIsDropped() {
    PresenceQueue queue = new PresenceQueue();
    PresenceSignal logout = signal(PresenceSignal.LOGOUT, 1);
    queue.addTransition(logout);
    queue.offerHeartbeat(signal(PresenceSignal.ACTIVE, 2));

    assertSame(logout, queue.peek());
    queue.onAnswered(logout);
    assertNull(queue.peek());
  }

  @Test
  public void aTransitionSupersedesAnOlderPendingHeartbeat() {
    PresenceQueue queue = new PresenceQueue();
    queue.offerHeartbeat(signal(PresenceSignal.ACTIVE, 1));
    PresenceSignal logout = signal(PresenceSignal.LOGOUT, 2);
    queue.addTransition(logout);
    queue.onAnswered(logout);
    assertNull(queue.peek());
  }

  @Test
  public void elapsedTimeComesFromTheMonotonicClockAndGrowsWhileRetried() {
    PresenceSignal logout = new PresenceSignal(PresenceSignal.LOGOUT, 1L, 1_000_000_000L);
    assertEquals(0L, logout.elapsedMillis(1_000_000_000L));
    assertEquals(180_000L, logout.elapsedMillis(181_000_000_000L));
    assertEquals("never negative", 0L, logout.elapsedMillis(0L));
  }

  /** Presence is held in memory only. */
  @Test
  public void presenceIsNeverPersisted() throws IOException {
    for (String name : new String[] {"PresenceQueue", "PresenceTracker", "PresenceSignal"}) {
      String source =
          new String(
              Files.readAllBytes(
                  Paths.get("src", "main", "java", "com", "bankstand", name + ".java")),
              StandardCharsets.UTF_8);
      for (String banned : new String[] {"java.io", "java.nio", "Gson", "ConfigManager"}) {
        assertEquals(name + " must not use " + banned, -1, source.indexOf(banned));
      }
    }
  }

  @Test
  public void aQueuedTransitionRetriesWheneverTheServerTakesSessions() {
    assertTrue(BankstandPlugin.shouldRetryPresence(1, true));
    assertFalse(BankstandPlugin.shouldRetryPresence(0, true));
    assertFalse(BankstandPlugin.shouldRetryPresence(1, false));
  }

  @Test
  public void theMinuteDrainRetriesPresenceWithoutALoginGate() throws IOException {
    String source =
        new String(
            Files.readAllBytes(
                Paths.get("src", "main", "java", "com", "bankstand", "BankstandPlugin.java")),
            StandardCharsets.UTF_8);
    int drain = source.indexOf("public void drainEventOutbox() {");
    int nextReturn = source.indexOf("return;", drain);
    int retry = source.indexOf("retryQueuedPresence();", drain);
    assertTrue("drainEventOutbox must call retryQueuedPresence", retry > drain);
    assertTrue("the retry must run before any early return", retry < nextReturn);
    String body =
        source.substring(
            source.indexOf("private void retryQueuedPresence() {"),
            source.indexOf("static boolean shouldRetryPresence("));
    for (String gate : new String[] {"session.", "presenceTracker", "collectSessions"}) {
      assertEquals("retryQueuedPresence must not check " + gate, -1, body.indexOf(gate));
    }
    // A queued signal must never go out under a later pairing.
    for (String method : new String[] {"private void disconnect() {", "private Stored storeToken("}) {
      int start = source.indexOf(method);
      String methodBody = source.substring(start, source.indexOf("\n  }\n", start));
      assertTrue(method + " must drop the pairing's queues", methodBody.contains("pairingQueues.replace"));
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;

/** The hop table, row by row, plus the failed-hop timer. */
public class PresenceTrackerTest {

  private static final long A = 111L;
  private static final long B = 222L;
  private static final long SECOND = 1_000_000_000L;

  private static PresenceTracker onStandard(long hash) {
    PresenceTracker tracker = new PresenceTracker();
    tracker.onLoggedIn(true, hash, 0L);
    return tracker;
  }

  private static void assertSignals(List<PresenceSignal> got, String... states) {
    assertEquals("signal count", states.length, got.size());
    for (int i = 0; i < states.length; i++) {
      assertEquals(states[i], got.get(i).getState());
    }
  }

  @Test
  public void aLoginOnAStandardWorldSendsLogin() {
    PresenceTracker tracker = new PresenceTracker();
    List<PresenceSignal> out = tracker.onLoggedIn(true, A, 5L);
    assertSignals(out, PresenceSignal.LOGIN);
    assertEquals(A, out.get(0).getAccountHash());
    assertEquals(5L, out.get(0).getCreatedAtNanos());
  }

  @Test
  public void aRegionLoadOnAStandardWorldSendsNothing() {
    // LOADING then LOGGED_IN after every teleport: the world type has not changed.
    PresenceTracker tracker = onStandard(A);
    assertSignals(tracker.onLoggedIn(true, A, 10L));
    assertSignals(tracker.onLoggedIn(true, A, 20L));
  }

  @Test
  public void aRegionLoadOnANonStandardWorldSendsNothing() {
    PresenceTracker tracker = new PresenceTracker();
    assertSignals(tracker.onLoggedIn(false, A, 0L));
    assertSignals(tracker.onLoggedIn(false, A, 10L));
  }

  @Test
  public void aStandardToStandardHopSendsNothingIncludingItsLoginScreen() {
    PresenceTracker tracker = onStandard(A);
    tracker.onHopping();
    assertSignals(tracker.onLoginScreen(A, SECOND));
    assertSignals(tracker.onLoggedIn(true, A, 2 * SECOND));
    assertFalse(tracker.isHopTimerArmed());
    assertTrue(tracker.isOnStandardWorld());
  }

  @Test
  public void aHopWithoutALoginScreenSendsNothing() {
    PresenceTracker tracker = onStandard(A);
    tracker.onHopping();
    assertSignals(tracker.onLoggedIn(true, A, SECOND));
  }

  @Test
  public void arrivingOnANonStandardWorldSendsOneLogout() {
    PresenceTracker tracker = onStandard(A);
    tracker.onHopping();
    List<PresenceSignal> out = tracker.onLoggedIn(false, A, SECOND);
    assertSignals(out, PresenceSignal.LOGOUT);
    assertEquals(A, out.get(0).getAccountHash());
  }

  @Test
  public void returningToAStandardWorldSendsOneLogin() {
    PresenceTracker tracker = onStandard(A);
    tracker.onLoggedIn(false, A, SECOND);
    assertSignals(tracker.onLoggedIn(true, A, 2 * SECOND), PresenceSignal.LOGIN);
  }

  @Test
  public void nonStandardToNonStandardSendsNothing() {
    PresenceTracker tracker = new PresenceTracker();
    tracker.onLoggedIn(false, A, 0L);
    tracker.onHopping();
    assertSignals(tracker.onLoginScreen(A, SECOND));
    assertSignals(tracker.onLoggedIn(false, A, 2 * SECOND));
  }

  @Test
  public void loggingOutFromANonStandardWorldSendsNothing() {
    PresenceTracker tracker = onStandard(A);
    tracker.onLoggedIn(false, A, SECOND);
    assertSignals(tracker.onLoginScreen(A, 2 * SECOND));
  }

  @Test
  public void anOrdinaryLogoutSendsLogoutForTheLeavingAccount() {
    PresenceTracker tracker = onStandard(A);
    List<PresenceSignal> out = tracker.onLoginScreen(A, 7 * SECOND);
    assertSignals(out, PresenceSignal.LOGOUT);
    assertEquals(A, out.get(0).getAccountHash());
    assertEquals(7 * SECOND, out.get(0).getCreatedAtNanos());
    assertFalse(tracker.isOnStandardWorld());
  }

  @Test
  public void anAccountSwitchIsALogoutThenALoginForTheOtherAccount() {
    PresenceTracker tracker = onStandard(A);
    assertEquals(A, tracker.onLoginScreen(A, SECOND).get(0).getAccountHash());
    List<PresenceSignal> out = tracker.onLoggedIn(true, B, 2 * SECOND);
    assertSignals(out, PresenceSignal.LOGIN);
    assertEquals(B, out.get(0).getAccountHash());
  }

  @Test
  public void aFailedHopSendsALogoutBackdatedToItsLoginScreen() {
    PresenceTracker tracker = onStandard(A);
    tracker.onHopping();
    assertSignals(tracker.onLoginScreen(A, 10 * SECOND));
    assertTrue(tracker.isHopTimerArmed());

    // Not yet: the timer is checked against the login screen's own time.
    assertSignals(tracker.onHopTimer(39 * SECOND));

    List<PresenceSignal> out = tracker.onHopTimer(40 * SECOND);
    assertSignals(out, PresenceSignal.LOGOUT);
    assertEquals(A, out.get(0).getAccountHash());
    assertEquals(
        "the logout carries the login screen's time, not the timer's",
        10 * SECOND,
        out.get(0).getCreatedAtNanos());
    assertFalse(tracker.isOnStandardWorld());

    // The next fresh login is a real login.
    assertSignals(tracker.onLoggedIn(true, A, 60 * SECOND), PresenceSignal.LOGIN);
  }

  @Test
  public void aHopThatLandsCancelsTheTimer() {
    PresenceTracker tracker = onStandard(A);
    tracker.onHopping();
    tracker.onLoginScreen(A, SECOND);
    assertSignals(tracker.onLoggedIn(true, A, 20 * SECOND));
    assertFalse(tracker.isHopTimerArmed());
    assertSignals(tracker.onHopTimer(100 * SECOND));
  }

  @Test
  public void aDifferentAccountAfterAFailedHopEndsTheFirstAccountsSession() {
    PresenceTracker tracker = onStandard(A);
    tracker.onHopping();
    tracker.onLoginScreen(A, SECOND);
    List<PresenceSignal> out = tracker.onLoggedIn(true, B, 10 * SECOND);
    assertSignals(out, PresenceSignal.LOGOUT, PresenceSignal.LOGIN);
    assertEquals(A, out.get(0).getAccountHash());
    assertEquals(SECOND, out.get(0).getCreatedAtNanos());
    assertEquals(B, out.get(1).getAccountHash());
  }

  @Test
  public void turningSessionsOffInGameSendsOff() {
    PresenceTracker tracker = onStandard(A);
    List<PresenceSignal> out = tracker.onSessionsTurnedOff(SECOND);
    assertSignals(out, PresenceSignal.OFF);
    assertEquals(A, out.get(0).getAccountHash());
  }

  @Test
  public void turningSessionsOffOutOfGameSendsNothing() {
    assertSignals(new PresenceTracker().onSessionsTurnedOff(SECOND));
  }

  @Test
  public void turningSessionsOnInGameStartsASessionNow() {
    PresenceTracker tracker = onStandard(A);
    assertSignals(tracker.onSessionsTurnedOn(SECOND), PresenceSignal.LOGIN);
  }

  @Test
  public void turningSessionsOnOnANonStandardWorldSendsNothing() {
    PresenceTracker tracker = new PresenceTracker();
    tracker.onLoggedIn(false, A, 0L);
    assertSignals(tracker.onSessionsTurnedOn(SECOND));
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

public class QuestBaselineTest {
  private static Map<String, String> of(String k, String v) {
    Map<String, String> m = new LinkedHashMap<>();
    m.put(k, v);
    return m;
  }

  @Test
  public void everythingIsChangedAgainstAFreshBaseline() {
    assertTrue(new QuestBaseline().changedSince(of("COOKS_ASSISTANT", "NOT_STARTED")));
  }

  @Test
  public void unchangedAfterAdvance() {
    QuestBaseline b = new QuestBaseline();
    b.advance(of("COOKS_ASSISTANT", "NOT_STARTED"));
    assertFalse(b.changedSince(of("COOKS_ASSISTANT", "NOT_STARTED")));
  }

  @Test
  public void aQuestStateChangeIsAChange() {
    QuestBaseline b = new QuestBaseline();
    b.advance(of("COOKS_ASSISTANT", "NOT_STARTED"));
    assertTrue(b.changedSince(of("COOKS_ASSISTANT", "IN_PROGRESS")));
  }

  @Test
  public void aNewQuestKeyIsAChange() {
    QuestBaseline b = new QuestBaseline();
    b.advance(of("COOKS_ASSISTANT", "NOT_STARTED"));
    Map<String, String> more = of("COOKS_ASSISTANT", "NOT_STARTED");
    more.put("DRAGON_SLAYER_I", "IN_PROGRESS");
    assertTrue(b.changedSince(more));
  }

  @Test
  public void resetForgetsTheBaseline() {
    QuestBaseline b = new QuestBaseline();
    b.advance(of("COOKS_ASSISTANT", "NOT_STARTED"));
    b.reset();
    assertTrue(b.changedSince(of("COOKS_ASSISTANT", "NOT_STARTED")));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class QuestCompletionCaptureTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private EventOutbox outbox() throws IOException {
    return new EventOutbox(new File(folder.newFolder(), "events.json"), new Gson());
  }

  private QuestCompletionCapture capture(EventOutbox outbox, boolean enabled) {
    return new QuestCompletionCapture(
        outbox, () -> enabled, () -> 1L, null, BankstandPlugin::isKnownQuest, null);
  }

  @Test
  public void parsesScrollTitles() {
    assertEquals(
        "The Corsair Curse",
        QuestCompletionCapture.parseScrollTitle("You have completed The Corsair Curse!"));
    assertEquals(
        "One Small Favour",
        QuestCompletionCapture.parseScrollTitle("'One Small Favour' completed!"));
    assertEquals(
        "Doric's Quest",
        QuestCompletionCapture.parseScrollTitle("You have completed Doric's Quest!"));
    assertEquals(
        "Recipe for Disaster - Mountain Dwarf",
        QuestCompletionCapture.parseScrollTitle("You have freed the Mountain Dwarf!"));
    assertEquals(
        "Some Future Adventure",
        QuestCompletionCapture.parseScrollTitle("You have completed Some Future Adventure!"));
    assertNull(QuestCompletionCapture.parseScrollTitle(null));
  }

  @Test
  public void emitsAQuestRuneLiteDoesNotKnowYet() throws IOException {
    EventOutbox outbox = outbox();
    capture(outbox, true).handleTitle("You have completed Some Future Adventure!");

    assertEquals(1, outbox.pending().size());
    TransientEvent event = outbox.pending().get(0).getEvent();
    assertEquals(TransientEvent.TYPE_QUEST_COMPLETED, event.getType());
    assertEquals("Some Future Adventure", event.getPayload().get("questName"));
  }

  @Test
  public void skipsAQuestTheSnapshotAlreadyReports() throws IOException {
    EventOutbox outbox = outbox();
    capture(outbox, true).handleTitle("You have completed The Corsair Curse!");
    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void treatsANameMissingItsQuestSuffixAsKnown() {
    assertTrue(BankstandPlugin.isKnownQuest("Cook's Assistant"));
    assertTrue(BankstandPlugin.isKnownQuest("Olaf's"));
  }

  @Test
  public void emitsOncePerQuest() throws IOException {
    EventOutbox outbox = outbox();
    QuestCompletionCapture capture = capture(outbox, true);
    capture.handleTitle("You have completed Some Future Adventure!");
    capture.handleTitle("You have completed Some Future Adventure!");
    assertEquals(1, outbox.pending().size());
  }

  @Test
  public void emitsNothingWhileDisabled() throws IOException {
    EventOutbox outbox = outbox();
    capture(outbox, false).handleTitle("You have completed Some Future Adventure!");
    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void describesItInRecentActivity() {
    assertEquals(
        "Quests: Some Future Adventure completed",
        RecentActivityLog.describe(
            TransientEvent.TYPE_QUEST_COMPLETED,
            java.util.Map.of("questName", "Some Future Adventure")));
  }
}

