import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.util.List;
import org.junit.Test;

/** Against the Gson the client ships, which wraps a reader's IOException as a syntax error. */
public class ReadFailuresTest {

  private static Throwable parse(Reader reader) {
    try {
      new Gson().fromJson(reader, new TypeToken<List<OutboxEntry>>() {}.getType());
    } catch (RuntimeException e) {
      return e;
    }
    fail("expected a failure");
    return null;
  }

  /** Hands out part of a valid document, then fails like a disk or a lock would. */
  private static Reader failingAfter(String start) {
    StringReader head = new StringReader(start);
    return new Reader() {
      @Override
      public int read(char[] buf, int off, int len) throws IOException {
        int n = head.read(buf, off, len);
        if (n == -1) {
          throw new IOException("device not ready");
        }
        return n;
      }

      @Override
      public void close() {}
    };
  }

  @Test
  public void anIoErrorMidReadIsNotDamage() {
    assertFalse(ReadFailures.isDamaged(parse(failingAfter("[{\"accountHash\":"))));
  }

  @Test
  public void malformedOrTruncatedJsonIsDamage() {
    assertTrue(ReadFailures.isDamaged(parse(new StringReader("{not json"))));
    assertTrue(ReadFailures.isDamaged(parse(new StringReader("[{\"accountHash\":"))));
  }

  private static Throwable parseBytes(byte[] bytes) throws IOException {
    java.nio.file.Path file = java.nio.file.Files.createTempFile("queue", ".json");
    try {
      java.nio.file.Files.write(file, bytes);
      try (Reader reader =
          java.nio.file.Files.newBufferedReader(file, java.nio.charset.StandardCharsets.UTF_8)) {
        return parse(reader);
      }
    } finally {
      java.nio.file.Files.delete(file);
    }
  }

  @Test
  public void undecodableBytesAreDamage() throws IOException {
    byte[] prefix = "[{\"accountHash\":\"".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
    byte[] invalid = java.util.Arrays.copyOf(prefix, prefix.length + 2);
    invalid[prefix.length] = (byte) 0xC3;
    invalid[prefix.length + 1] = (byte) 0x28;
    assertTrue("not UTF-8", ReadFailures.isDamaged(parseBytes(invalid)));
    byte[] truncated = java.util.Arrays.copyOf(prefix, prefix.length + 2);
    truncated[prefix.length] = (byte) 0xE2;
    truncated[prefix.length + 1] = (byte) 0x82;
    assertTrue("cut mid-character", ReadFailures.isDamaged(parseBytes(truncated)));
  }
}

package com.bankstand;

import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

/** Checks that the README names every {@code KEY_COLLECT_*} toggle label from BankstandConfig. */
public class ReadmeCaptureListTest {

  private static final Path CONFIG_FILE =
      Paths.get("src", "main", "java", "com", "bankstand", "BankstandConfig.java");
  private static final Path README_FILE = Paths.get("README.md");

  private static final Pattern NAME_ATTRIBUTE = Pattern.compile("name\\s*=\\s*\"([^\"]+)\"");

  @Test
  public void everyCaptureToggleIsNamedInReadme() throws IOException {
    String config = Files.readString(CONFIG_FILE, StandardCharsets.UTF_8);
    String readme = Files.readString(README_FILE, StandardCharsets.UTF_8).toLowerCase(Locale.ROOT);

    List<String> labels = new ArrayList<>();
    // Split before each @ConfigItem( so every chunk holds exactly one item's attributes.
    for (String chunk : config.split("(?=@ConfigItem\\()")) {
      if (!chunk.contains("BankstandKeys.KEY_COLLECT_")) {
        continue;
      }
      Matcher nameMatcher = NAME_ATTRIBUTE.matcher(chunk);
      assertTrue(
          "Found a KEY_COLLECT_* @ConfigItem with no parseable name = \"...\" attribute:\n"
              + chunk,
          nameMatcher.find());
      labels.add(nameMatcher.group(1));
    }

    assertTrue(
        "Expected at least one KEY_COLLECT_* @ConfigItem in BankstandConfig.java; the"
            + " naming convention this test parses may have changed.",
        !labels.isEmpty());

    List<String> missing = new ArrayList<>();
    for (String label : labels) {
      // "Collect skill XP" -> "skill xp": the README names the subject without the verb.
      String subject = label.replaceFirst("(?i)^collect\\s+", "").toLowerCase(Locale.ROOT);
      if (!readme.contains(subject)) {
        missing.add(label);
      }
    }

    assertTrue(
        "README.md's \"What it captures\" section does not name every real capture"
            + " toggle. A toggle exists in BankstandConfig.java with no matching mention"
            + " in the README, which is exactly how the plugin grew from 4 documented"
            + " toggles to 8 without anyone noticing. Missing: "
            + missing,
        missing.isEmpty());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class RecentActivityLogTest {

  @Test
  public void startsEmpty() {
    assertTrue(new RecentActivityLog().recent().isEmpty());
  }

  @Test
  public void newestEntryComesFirst() {
    RecentActivityLog log = new RecentActivityLog();
    log.record("first");
    log.record("second");

    assertEquals(List.of("second", "first"), descriptions(log.recent()));
  }

  @Test
  public void evictsTheOldestOnceFull() {
    RecentActivityLog log = new RecentActivityLog();
    for (int i = 0; i < RecentActivityLog.MAX_ENTRIES + 3; i++) {
      log.record("entry-" + i);
    }

    List<PanelModel.ActivityRow> recent = log.recent();

    assertEquals(RecentActivityLog.MAX_ENTRIES, recent.size());
    assertEquals("entry-" + (RecentActivityLog.MAX_ENTRIES + 2), recent.get(0).description);
    assertEquals("entry-3", recent.get(recent.size() - 1).description);
  }

  @Test
  public void recentIsASnapshotNotALiveView() {
    RecentActivityLog log = new RecentActivityLog();
    log.record("first");

    List<PanelModel.ActivityRow> snapshot = log.recent();
    log.record("second");

    assertEquals(List.of("first"), descriptions(snapshot));
  }

  @Test
  public void stampsEachEntryWithWhenItWasRecorded() {
    RecentActivityLog log = new RecentActivityLog();
    long before = System.currentTimeMillis();
    log.record("first");
    long after = System.currentTimeMillis();

    long atMs = log.recent().get(0).atMs;
    assertTrue(atMs >= before && atMs <= after);
  }

  private static List<String> descriptions(List<PanelModel.ActivityRow> rows) {
    List<String> out = new ArrayList<>();
    for (PanelModel.ActivityRow row : rows) {
      out.add(row.description);
    }
    return out;
  }

  @Test
  public void clearForgetsEverything() {
    RecentActivityLog log = new RecentActivityLog();
    log.record("first");

    log.clear();

    assertTrue(log.recent().isEmpty());
  }

  private static Map<String, Object> payload(String... keyValuePairs) {
    Map<String, Object> payload = new LinkedHashMap<>();
    for (int i = 0; i < keyValuePairs.length; i += 2) {
      payload.put(keyValuePairs[i], keyValuePairs[i + 1]);
    }
    return payload;
  }

  @Test
  public void describesACollectionLogUnlockByItsItemName() {
    assertEquals(
        "Collection log: Dragon warhammer",
        RecentActivityLog.describe(
            TransientEvent.TYPE_COLLECTION_LOG_UNLOCK, payload("itemName", "Dragon warhammer")));
  }

  @Test
  public void describesACombatAchievementByItsTaskName() {
    assertEquals(
        "Combat achievements: Reflection completed",
        RecentActivityLog.describe(
            TransientEvent.TYPE_COMBAT_ACHIEVEMENT_COMPLETED,
            payload("tier", "master", "taskName", "Reflection")));
  }

  @Test
  public void describesADiaryTaskWithATitleCasedTier() {
    assertEquals(
        "Diaries: Elite task completed in Western Provinces",
        RecentActivityLog.describe(
            TransientEvent.TYPE_DIARY_TASK_COMPLETED,
            payload("tier", "elite", "area", "Western Provinces")));
  }

  @Test
  public void describesANotableDropByItsItemName() {
    assertEquals(
        "Notable drop: Twisted bow",
        RecentActivityLog.describe(TransientEvent.TYPE_NOTABLE_DROP, payload("itemName", "Twisted bow")));
  }

  @Test
  public void describesAPetDropByItsPetName() {
    assertEquals(
        "Pet drop: Baby mole",
        RecentActivityLog.describe(TransientEvent.TYPE_PET_DROP, payload("petName", "Baby mole")));
  }

  @Test
  public void anUnknownTypeDescribesAsNullRatherThanABlankLine() {
    assertNull(RecentActivityLog.describe("some_future_event", payload()));
  }
}

