public class SlayerTaskReaderTest {

  private final Map<Integer, Integer> varps = new HashMap<>();
  private final Map<Integer, Integer> varbits = new HashMap<>();

  private Client client() {
    return (Client)
        Proxy.newProxyInstance(
            Client.class.getClassLoader(),
            new Class<?>[] {Client.class},
            (proxy, method, args) -> {
              switch (method.getName()) {
                case "getVarpValue":
                  return varps.getOrDefault((Integer) args[0], 0);
                case "getVarbitValue":
                  return varbits.getOrDefault((Integer) args[0], 0);
                case "getDBRowsByValue":
                  return Collections.emptyList();
                default:
                  return null;
              }
            });
  }

  private void activeTask(int master) {
    varps.put(VarPlayerID.SLAYER_COUNT, 64);
    varps.put(VarPlayerID.SLAYER_COUNT_ORIGINAL, 187);
    varbits.put(VarbitID.SLAYER_MASTER, master);
    varbits.put(VarbitID.SLAYER_TASKS_COMPLETED, 312);
    varbits.put(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 14);
    varps.put(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED, 2);
  }

  @Test
  public void mapsEveryKnownMasterValue() {
    String[] expected = {
      "turael", "mazchna", "vannaka", "chaeldar", "duradel",
      "nieve", "krystilia", "konar", "spria", "mortimer"
    };
    for (int i = 0; i < expected.length; i++) {
      assertEquals(expected[i], SlayerTaskReader.masterKey(i + 1));
    }
  }

  @Test
  public void anUnknownMasterValueIsNull() {
    assertNull(SlayerTaskReader.masterKey(0));
    assertNull(SlayerTaskReader.masterKey(11));
    assertNull(SlayerTaskReader.masterKey(-1));
  }

  @Test
  public void readsTheMasterAndAllThreeStreaks() {
    activeTask(5);
    SlayerTask task = SlayerTaskReader.read(client());
    assertEquals("duradel", task.master);
    assertEquals(Integer.valueOf(312), task.streak);
    assertEquals(SlayerTask.streaks(312, 14, 2), task.streaks);
  }

  @Test
  public void theCurrentStreakFollowsTheMaster() {
    activeTask(7);
    assertEquals(Integer.valueOf(14), SlayerTaskReader.read(client()).streak);
    activeTask(10);
    assertEquals(Integer.valueOf(2), SlayerTaskReader.read(client()).streak);
  }

  @Test
  public void anUnmappedMasterIsSentAsNull() {
    activeTask(42);
    assertNull(SlayerTaskReader.read(client()).master);
  }

  @Test
  public void noActiveTaskSendsNoMasterEvenIfTheVarbitStillHoldsOne() {
    activeTask(5);
    varps.put(VarPlayerID.SLAYER_COUNT, 0);
    SlayerTask task = SlayerTaskReader.read(client());
    assertSame(SlayerTask.NONE, task);
    assertFalse(task.toWire().containsKey("master"));
  }

  @Test
  public void anOutOfRangeStreakIsNull() {
    activeTask(5);
    varbits.put(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, SlayerTaskReader.MAX_STREAK + 1);
    assertEquals(SlayerTask.streaks(312, null, 2), SlayerTaskReader.read(client()).streaks);
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.bankstand.session.AccountSession;
import com.google.gson.Gson;
import java.io.File;
import java.lang.reflect.Proxy;
import java.time.Instant;
import net.runelite.api.Client;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class SlayerTaskStartTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private static final long ACCOUNT = 1L;
  private static final Instant T0 = Instant.parse("2026-10-18T09:00:00Z");
  private static final Instant T1 = Instant.parse("2026-10-18T09:30:00Z");
  private static final SlayerTask DUST =
      new SlayerTask(true, "Dust devils", 187, 187, "duradel", 1240, 312, null);
  private static final SlayerTask DUST_LATER =
      new SlayerTask(true, "Dust devils", 64, 187, "duradel", 1240, 312, null);
  private static final SlayerTask KURASK =
      new SlayerTask(true, "Kurask", 120, 120, "duradel", 1255, 313, null);

  private File file;

  private SlayerTaskStart tracker() throws Exception {
    if (file == null) {
      file = new File(folder.newFolder("bankstand"), "slayer-task-start.json");
    }
    // Synchronous IO, so a second tracker reads what the first wrote.
    return new SlayerTaskStart(file, new Gson(), Runnable::run, null, new AccountSession());
  }

  @Test
  public void aTaskAlreadyRunningAtFirstLookHasNoStart() throws Exception {
    assertNull(tracker().observe(ACCOUNT, 1, DUST, T0).startedAt);
  }

  @Test
  public void aTaskSeenArrivingAfterNoneStartsThenAndKeepsIt() throws Exception {
    SlayerTaskStart t = tracker();
    t.observe(ACCOUNT, 1, SlayerTask.NONE, T0);
    assertEquals("2026-10-18T09:00:00Z", t.observe(ACCOUNT, 1, DUST, T0).startedAt);
    assertEquals("2026-10-18T09:00:00Z", t.observe(ACCOUNT, 1, DUST_LATER, T1).startedAt);
  }

  @Test
  public void aTaskReplacingAnotherStartsWhenSeen() throws Exception {
    SlayerTaskStart t = tracker();
    t.observe(ACCOUNT, 1, DUST, T0);
    assertEquals("2026-10-18T09:30:00Z", t.observe(ACCOUNT, 1, KURASK, T1).startedAt);
  }

  @Test
  public void aRestartKeepsTheStart() throws Exception {
    SlayerTaskStart t = tracker();
    t.observe(ACCOUNT, 1, SlayerTask.NONE, T0);
    t.observe(ACCOUNT, 1, DUST, T0);

    assertEquals("2026-10-18T09:00:00Z", tracker().observe(ACCOUNT, 1, DUST_LATER, T1).startedAt);
  }

  @Test
  public void aTaskChangedWhileClosedHasNoStartAndDropsTheOldOne() throws Exception {
    SlayerTaskStart t = tracker();
    t.observe(ACCOUNT, 1, SlayerTask.NONE, T0);
    t.observe(ACCOUNT, 1, DUST, T0);

    SlayerTaskStart restarted = tracker();
    assertNull(restarted.observe(ACCOUNT, 1, KURASK, T1).startedAt);
    assertNull(tracker().observe(ACCOUNT, 1, DUST, T1).startedAt);
  }

  @Test
  public void anotherAccountNeverInheritsWhatThisOneSaw() throws Exception {
    SlayerTaskStart t = tracker();
    t.observe(ACCOUNT, 1, SlayerTask.NONE, T0);
    assertNull(t.observe(2L, 1, DUST, T0).startedAt);
  }

  @Test
  public void aPartialReadDoesNotRestampARunningTask() throws Exception {
    SlayerTaskStart t = tracker();
    t.observe(ACCOUNT, 1, SlayerTask.NONE, T0);
    t.observe(ACCOUNT, 1, DUST, T0);
    SlayerTask partial = new SlayerTask(true, null, 186, null, "duradel", 1240, 312, null);
    assertNull(t.observe(ACCOUNT, 1, partial, T1).startedAt);
    assertEquals("2026-10-18T09:00:00Z", t.observe(ACCOUNT, 1, DUST_LATER, T1).startedAt);
  }

  @Test
  public void aTaskChangedWhileCaptureWasOffIsNotStamped() throws Exception {
    AccountSession session = new AccountSession();
    session.onLogin(ACCOUNT);
    SlayerTaskStart t =
        new SlayerTaskStart(
            new File(folder.newFolder("off"), "s.json"), new Gson(), Runnable::run,
            noTaskClient(), session);
    t.observe(ACCOUNT, session.getGeneration(), DUST, T0);
    t.read(false);
    assertNull(t.observe(ACCOUNT, session.getGeneration(), KURASK, T1).startedAt);
  }

  private static Client noTaskClient() {
    return (Client)
        Proxy.newProxyInstance(
            Client.class.getClassLoader(),
            new Class<?>[] {Client.class},
            (proxy, method, args) -> method.getReturnType() == int.class ? 0 : null);
  }

  @Test
  public void aChangeAcrossALogoutIsNotSeenLive() throws Exception {
    SlayerTaskStart t = tracker();
    t.observe(ACCOUNT, 1, SlayerTask.NONE, T0);
    assertNull(t.observe(ACCOUNT, 2, DUST, T1).startedAt);
  }
}

package com.bankstand;

import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Stream;
import org.junit.Test;

/** Keeps every source file small enough to review in one sitting. */
public class SourceSizeTest {

  private static final Path SOURCE_ROOT = Paths.get("src", "main", "java");

  private static final int MAX_LINES = 400;

  /** Static data and the config interface grow with the game, not with logic. */
  private static final Set<String> EXEMPT =
      Set.of("com/bankstand/BankstandConfig.java");

  /** Files still over the limit. Lower an entry when its file shrinks; never raise one. */
  private static final Map<String, Integer> RATCHET = new HashMap<>();

  static {
    RATCHET.put("com/bankstand/BankstandPlugin.java", 2542);
    RATCHET.put("com/bankstand/BankstandClient.java", 437);
  }

  @Test
  public void noSourceFileGrowsPastItsLimit() throws IOException {
    List<String> offences = new ArrayList<>();
    Set<String> seen = new HashSet<>();
    try (Stream<Path> files = Files.walk(SOURCE_ROOT)) {
      for (Path file : (Iterable<Path>) files.filter(p -> p.toString().endsWith(".java"))::iterator) {
        String name = SOURCE_ROOT.relativize(file).toString().replace('\\', '/');
        seen.add(name);
        if (EXEMPT.contains(name)) {
          continue;
        }
        int lines = Files.readAllLines(file, StandardCharsets.UTF_8).size();
        Integer ceiling = RATCHET.get(name);
        if (ceiling == null && lines > MAX_LINES) {
          offences.add(file + " has " + lines + " lines, over the " + MAX_LINES + " limit");
        } else if (ceiling != null && lines > ceiling) {
          offences.add(file + " grew to " + lines + " lines, past its ratchet of " + ceiling);
        } else if (ceiling != null && lines < ceiling) {
          offences.add(file + " shrank to " + lines + " lines: lower its ratchet to match");
        }
      }
    }
    for (String name : RATCHET.keySet()) {
      if (!seen.contains(name)) {
        offences.add(name + " has a ratchet entry but no longer exists: remove the entry");
      }
    }
    for (String name : EXEMPT) {
      if (!seen.contains(name)) {
        offences.add(name + " is exempt but no longer exists: remove the exemption");
      }
    }
    assertTrue(String.join("\n", offences), offences.isEmpty());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class StatusReportTest {

  private static boolean mentions(List<String> lines, String needle) {
    for (String line : lines) {
      if (line.contains(needle)) {
        return true;
      }
    }
    return false;
  }

  @Test
  public void namesWhatItActuallyCounted() {
    // The plugin counts item ids, the game counts entries, so the line says "ids".
    List<String> lines =
        StatusReport.lines(
            true, "https://x", "Zezima", "just now", null, Arrays.asList("skills"), 193, null, null);
    assertTrue(mentions(lines, "193 items"));
    assertFalse(mentions(lines, "193 entries"));
  }

  @Test
  public void unpairedSaysOnlyThat() {
    // Without a pairing the other lines would describe something that does not exist.
    List<String> lines =
        StatusReport.lines(false, "https://x", "Zezima", "just now", null, Arrays.asList("skills"), 12, null, null);
    assertEquals(1, lines.size());
    assertTrue(lines.get(0).contains("Not paired"));
  }

  @Test
  public void namesTheServerBecauseAWrongOneIsOtherwiseSilent() {
    List<String> lines =
        StatusReport.lines(
            true, "https://example.test", "Zezima", "just now", null, Arrays.asList("skills"), 12, null, null);
    assertTrue(mentions(lines, "https://example.test"));
  }

  @Test
  public void saysWhenNoCharacterIsLinkedAndHowToFixIt() {
    // Identity failed once: the line must say how to retry.
    List<String> lines =
        StatusReport.lines(true, "https://x", null, null, null, Arrays.asList("skills"), -1, null, null);
    assertTrue(mentions(lines, "No character linked"));
    assertTrue(mentions(lines, "::bstand link"));
  }

  @Test
  public void namesTheLinkedCharacter() {
    List<String> lines =
        StatusReport.lines(true, "https://x", "Zezima", "just now", null, Arrays.asList("skills"), 5, null, null);
    assertTrue(mentions(lines, "Zezima"));
  }

  @Test
  public void saysWhenNothingIsSwitchedOn() {
    List<String> lines =
        StatusReport.lines(true, "https://x", "Zezima", null, null, Collections.emptyList(), -1, null, null);
    assertTrue(mentions(lines, "No capabilities switched on"));
  }

  @Test
  public void reportsTheLastFailureOnlyWhenThereIsOne() {
    List<String> withFailure =
        StatusReport.lines(
            true, "https://x", "Zezima", "5m ago", "401 unauthorised", Arrays.asList("skills"), 5, null, null);
    assertTrue(mentions(withFailure, "401 unauthorised"));

    List<String> clean =
        StatusReport.lines(true, "https://x", "Zezima", "5m ago", null, Arrays.asList("skills"), 5, null, null);
    assertFalse(mentions(clean, "Last failure"));
  }

  @Test
  public void alwaysExplainsTheCollectionLog() {
    // A manual sync cannot refresh it, so it always gets a line.
    List<String> neverRead =
        StatusReport.lines(true, "https://x", "Zezima", "5m ago", null, Arrays.asList("skills"), -1, null, null);
    assertTrue(mentions(neverRead, "Search"));
    assertFalse(mentions(neverRead, "-1"));

    List<String> read =
        StatusReport.lines(true, "https://x", "Zezima", "5m ago", null, Arrays.asList("skills"), 189, null, null);
    assertTrue(mentions(read, "189"));
    assertTrue(mentions(read, "Search"));
  }

  @Test
  public void syncNamesWhatItIsSendingAndWhatItIsNot() {
    List<String> lines =
        StatusReport.syncLines(true, Arrays.asList("skills", "collection log", "quests"));
    assertTrue(mentions(lines, "Syncing skills, quests now."));
    assertFalse(lines.get(0).contains("collection log"));
    assertTrue(mentions(lines, "collection log is not included"));
  }

  @Test
  public void syncOnlyExplainsTheCollectionLogWhenItIsOn() {
    assertFalse(
        mentions(StatusReport.syncLines(true, Arrays.asList("skills")), "collection log"));
    List<String> onlyLog = StatusReport.syncLines(true, Arrays.asList("collection log"));
    assertEquals(1, onlyLog.size());
    assertTrue(mentions(onlyLog, "collection log is not included"));
  }

  @Test
  public void syncRefusesWithNothingToSend() {
    assertTrue(mentions(StatusReport.syncLines(false, Arrays.asList("skills")), "Not paired"));
    assertTrue(
        mentions(StatusReport.syncLines(true, Collections.emptyList()), "nothing to sync"));
  }

  @Test
  public void showsTheAccountTypeWhenTheGameReportedOne() {
    List<String> lines =
        StatusReport.lines(
            true,
            "https://x",
            "Zezima",
            "just now",
            null,
            Arrays.asList("skills"),
            5,
            "Account type: group (varbit 1777 = 4).", null);
    assertTrue(mentions(lines, "Account type: group"));
  }

  @Test
  public void saysNothingAboutTheAccountTypeWhileLoggedOut() {
    // The varbit reads 0 with no account loaded, the same as "regular", so the line is omitted.
    List<String> lines =
        StatusReport.lines(
            true, "https://x", null, "just now", null, Arrays.asList("skills"), 5, null, null);
    assertFalse(mentions(lines, "Account type"));
  }

  @Test
  public void queueLinesGiveCountsAndFileHealthOnly() {
    assertEquals(
        java.util.Collections.singletonList("Queued events: 2."),
        StatusReport.queueLines("events", 2, 0, null));
    java.util.List<String> bad = StatusReport.queueLines("events", 0, 3, "could not be saved");
    assertEquals("Queue full: 3 oldest events dropped this session.", bad.get(1));
    assertEquals("The events queue file could not be saved.", bad.get(2));
  }
}

