    Map<String, Object> nullCounts =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null);
    assertFalse(nullCounts.containsKey("diaryTasks"));
  }

  @Test
  public void carriesTheAccountTypeWhenTheGameNamedOne() {
    Map<String, Object> body =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, "hardcore_group");

    assertEquals("hardcore_group", body.get("accountType"));
  }

  @Test
  public void omitsTheAccountTypeWhenTheGameNamedNone() {
    // Null means "not observed"; a wrong type is worse than none.
    Map<String, Object> nothing =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null);
    assertFalse(nothing.containsKey("accountType"));

    Map<String, Object> empty =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, "");
    assertFalse(empty.containsKey("accountType"));
  }

  @Test
  public void carriesCombatAchievementBossCountsWhenThereAreAny() {
    java.util.Map<String, Integer> bossCounts = new java.util.LinkedHashMap<>();
    bossCounts.put("Vorkath", 4);
    bossCounts.put("Zulrah", 0);
    Map<String, Object> body =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null, false, bossCounts);

    @SuppressWarnings("unchecked")
    Map<String, Object> sent = (Map<String, Object>) body.get("combatAchievementBossCounts");
    assertEquals(Integer.valueOf(4), sent.get("Vorkath"));
    // Zero is a real reading, not "never read".
    assertEquals(Integer.valueOf(0), sent.get("Zulrah"));
  }

  @Test
  public void omitsCombatAchievementBossCountsWhenThereAreNone() {
    // Absent means "not observed"; a present-but-empty block erases on the server merge.
    Map<String, Object> none =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null, false, new java.util.LinkedHashMap<>());
    assertFalse(none.containsKey("combatAchievementBossCounts"));

    Map<String, Object> nullCounts =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null, false, null);
    assertFalse(nullCounts.containsKey("combatAchievementBossCounts"));
  }

  @Test
  public void aPreExistingCallerWithNoBossCountsStillOmitsTheBlock() {
    // The older overload must omit the field, not send it empty.
    Map<String, Object> body =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null, false);
    assertFalse(body.containsKey("combatAchievementBossCounts"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SubmitGateTest {

  private static void failAndSkipPast(SubmitGate gate) {
    gate.onFailure();
    while (!gate.allow()) {
      // Burn the backoff.
    }
  }

  @Test
  public void allowsACaptureWhenNothingHasGoneWrong() {
    SubmitGate gate = new SubmitGate();

    assertTrue(gate.allow());
    assertTrue(gate.allow());
  }

  /** A revoked token must halt submits rather than retry every cycle forever. */
  @Test
  public void stopsForeverOnARevokedToken() {
    SubmitGate gate = new SubmitGate();

    gate.onAuthFailure();

    assertTrue(gate.isHalted());
    for (int capture = 0; capture < 100; capture++) {
      assertFalse(gate.allow());
    }
  }

  @Test
  public void aRevokedTokenIsAnnouncedOnceRatherThanEveryCapture() {
    SubmitGate gate = new SubmitGate();

    assertTrue(gate.onAuthFailure());
    assertFalse(gate.onAuthFailure());
  }

  @Test
  public void resumingAfterAReRepairLetsCapturesThrough() {
    SubmitGate gate = new SubmitGate();
    gate.onAuthFailure();

    gate.resume();

    assertFalse(gate.isHalted());
    assertTrue(gate.allow());
  }

  @Test
  public void backsOffAfterAFailureRatherThanRetryingEveryCapture() {
    SubmitGate gate = new SubmitGate();

    gate.onFailure();

    assertFalse(gate.allow());
  }

  @Test
  public void backsOffFurtherTheLongerItKeepsFailing() {
    SubmitGate gate = new SubmitGate();
    int previous = 0;
    for (int round = 1; round <= 4; round++) {
      gate.onFailure();
      int skipped = 0;
      while (!gate.allow()) {
        skipped++;
      }
      assertTrue(
          "round " + round + " skipped " + skipped + ", previous " + previous, skipped > previous);
      previous = skipped;
    }
  }

  /** Backoff is bounded. */
  @Test
  public void neverBacksOffPastTheCap() {
    SubmitGate gate = new SubmitGate();
    for (int round = 0; round < 50; round++) {
      gate.onFailure();
    }
    int skipped = 0;
    while (!gate.allow()) {
      skipped++;
    }

    assertEquals(SubmitGate.MAX_SKIPPED_CAPTURES, skipped);
  }

  @Test
  public void oneSuccessClearsTheBackoffCompletely() {
    SubmitGate gate = new SubmitGate();
    for (int round = 0; round < 5; round++) {
      gate.onFailure();
    }

    gate.onSuccess();

    assertTrue(gate.allow());
    assertTrue(gate.allow());
  }

  @Test
  public void aFailureAfterARecoveryStartsFromTheShortestBackoffAgain() {
    SubmitGate gate = new SubmitGate();
    for (int round = 0; round < 5; round++) {
      gate.onFailure();
    }
    gate.onSuccess();
    failAndSkipPast(gate);

    // Back to the first rung: the server proved reachable.
    SubmitGate fresh = new SubmitGate();
    fresh.onFailure();
    int freshSkips = 0;
    while (!fresh.allow()) {
      freshSkips++;
    }
    gate.onSuccess();
    gate.onFailure();
    int afterRecoverySkips = 0;
    while (!gate.allow()) {
      afterRecoverySkips++;
    }

    assertEquals(freshSkips, afterRecoverySkips);
  }

  @Test
  public void aBackoffElapsingDoesNotUnhaltARevokedToken() {
    SubmitGate gate = new SubmitGate();
    gate.onFailure();
    gate.onAuthFailure();

    for (int capture = 0; capture < 50; capture++) {
      assertFalse(gate.allow());
    }
  }

  @Test
  public void aSuccessDoesNotSilentlyUnhaltARevokedToken() {
    SubmitGate gate = new SubmitGate();
    gate.onAuthFailure();

    // A silent unhalt would resume submitting with a rejected token.
    gate.onSuccess();

    assertTrue(gate.isHalted());
    assertFalse(gate.allow());
  }

  @Test
  public void concurrentAuthFailuresAnnounceExactlyOnce() throws Exception {
    SubmitGate gate = new SubmitGate();
    java.util.concurrent.ExecutorService pool = java.util.concurrent.Executors.newFixedThreadPool(8);
    java.util.concurrent.atomic.AtomicInteger announced = new java.util.concurrent.atomic.AtomicInteger();
    java.util.concurrent.CountDownLatch start = new java.util.concurrent.CountDownLatch(1);
    for (int i = 0; i < 8; i++) {
      pool.submit(
          () -> {
            start.await();
            if (gate.onAuthFailure()) {
              announced.incrementAndGet();
            }
            return null;
          });
    }
    start.countDown();
    pool.shutdown();
    assertTrue(pool.awaitTermination(5, java.util.concurrent.TimeUnit.SECONDS));
    assertEquals(1, announced.get());
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

/** A capability goes on the wire only when that capability itself changed. */
public class SubmitPlanTest {

  private static Map<String, Integer> skills(String name, int xp) {
    Map<String, Integer> map = new LinkedHashMap<>();
    map.put(name, xp);
    return map;
  }

  private static Map<String, String> states(String key, String value) {
    Map<String, String> map = new LinkedHashMap<>();
    map.put(key, value);
    return map;
  }

  private static final Set<Integer> NO_LOG = Collections.emptySet();

  private static class Acked {
    final SkillBaseline skills = new SkillBaseline();
    final QuestBaseline quests = new QuestBaseline();
    final DiaryBaseline diaries = new DiaryBaseline();
    final CollectionLogBaseline log = new CollectionLogBaseline();

    Acked() {
      skills.advance(SubmitPlanTest.skills("attack", 100));
      quests.advance(states("COOKS_ASSISTANT", "FINISHED"));
      diaries.advance(states("VARROCK_EASY", "COMPLETE"));
      log.advance(2);
    }

    SubmitPlan plan(
        Map<String, Integer> s, Map<String, String> q, Map<String, String> d, Set<Integer> c) {
      return TestPlans.plan(skills, s, quests, q, diaries, d, log, c);
    }
  }

  @Test
  public void sendsNothingWhenNothingMoved() {
    Acked acked = new Acked();

    SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2)));

    assertFalse(plan.shouldSubmit());
  }

  @Test
  public void anXpChangeCarriesSkillsAlone() {
    Acked acked = new Acked();

    SubmitPlan plan =
        acked.plan(
            skills("attack", 200),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2)));

    assertTrue(plan.shouldSubmit());
    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertFalse(plan.includesCollectionLog());
  }

  @Test
  public void aQuestChangeCarriesQuestsAndNotTheOtherRiders() {
    Acked acked = new Acked();

    SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "IN_PROGRESS"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertFalse(plan.includesCollectionLog());
  }

  @Test
  public void aDiaryChangeCarriesDiariesAlone() {
    Acked acked = new Acked();

    SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "INCOMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesDiaries());
    assertFalse(plan.includesQuests());
  }

  @Test
  public void aGrownCollectionLogCarriesTheLogAlone() {
    Acked acked = new Acked();

    SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2, 3)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesCollectionLog());
    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
  }

  @Test
  public void anOptInThatIsOffNeverContributesAndIsNeverSent() {
    Acked acked = new Acked();

    SubmitPlan plan = acked.plan(skills("attack", 100), null, null, NO_LOG);

    assertFalse(plan.shouldSubmit());
    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertFalse(plan.includesCollectionLog());
  }

  /** A never-acknowledged block counts as changed, so it resends until stored. */
  @Test
  public void aBlockThatWasNeverAcknowledgedKeepsBeingSent() {
    SkillBaseline skills = new SkillBaseline();
    skills.advance(skills("attack", 100));

    SubmitPlan plan =
        TestPlans.plan(
            skills,
            skills("attack", 100),
            new QuestBaseline(),
            states("COOKS_ASSISTANT", "FINISHED"),
            new DiaryBaseline(),
            states("VARROCK_EASY", "COMPLETE"),
            new CollectionLogBaseline(),
            new java.util.HashSet<>(Arrays.asList(1)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesQuests());
    assertTrue(plan.includesDiaries());
    assertTrue(plan.includesCollectionLog());
  }

  /** Absent means "not observed", so an empty block is never sent. */
  @Test
  public void anEmptyBlockIsNeverSent() {
    SubmitPlan plan =
        TestPlans.plan(
            new SkillBaseline(),
            skills("attack", 100),
            new QuestBaseline(),
            new LinkedHashMap<>(),
            new DiaryBaseline(),
            new LinkedHashMap<>(),
            new CollectionLogBaseline(),
            NO_LOG);

    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertFalse(plan.includesCollectionLog());
  }

  @Test
  public void severalChangesRideTogether() {
    Acked acked = new Acked();

    SubmitPlan plan =
        acked.plan(
            skills("attack", 200),
            states("COOKS_ASSISTANT", "IN_PROGRESS"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2, 3)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertTrue(plan.includesCollectionLog());
  }

  /**
   * Combat achievements opted out pass an empty map. The server never acks an empty block,
   * so sending one would make the client resubmit forever.
   */
  @Test
  public void leavesCombatAchievementsOutWhileTheOptInIsOff() {
    Acked acked = new Acked();
    CombatAchievementBaseline combat = new CombatAchievementBaseline();
    combat.advance(skills("easy", 23));

    SubmitPlan plan =
        TestPlans.plan(
            acked.skills,
            skills("attack", 200),
            acked.quests,
            null,
            acked.diaries,
            null,
            acked.log,
            NO_LOG,
            combat,
            Collections.emptyMap());

    assertFalse(plan.includesCombatAchievements());
    assertTrue(plan.shouldSubmit());
  }

  /**
   * A complete guided read that found no new ids still needs a block, or the completeness
   * fact never reaches the server.
   */
  @Test
  public void aCompleteEnumerationCarriesTheLogEvenWithNoNewItems() {
    Acked acked = new Acked();

    SubmitPlan plan =
        TestPlans.plan(
            acked.skills,
            skills("attack", 100),
            acked.quests,
            states("COOKS_ASSISTANT", "FINISHED"),
            acked.diaries,
            states("VARROCK_EASY", "COMPLETE"),
            acked.log,
            new java.util.HashSet<>(Arrays.asList(1, 2)),
            new CombatAchievementBaseline(),
            null,
            new AccountTypeBaseline(),
            null,
            true);

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesCollectionLog());
    assertTrue(plan.includesFullEnumeration());
  }

  /** The pending signal cannot create a block for an account with no collection log. */
  @Test
  public void aPendingEnumerationNeverCarriesAnEmptyLog() {
    Acked acked = new Acked();

    SubmitPlan plan =
        TestPlans.plan(
            acked.skills,
            skills("attack", 200),
            acked.quests,
            states("COOKS_ASSISTANT", "FINISHED"),
            acked.diaries,
            states("VARROCK_EASY", "COMPLETE"),
            new CollectionLogBaseline(),
            NO_LOG,
            new CombatAchievementBaseline(),
            null,
            new AccountTypeBaseline(),
            null,
            true);

    assertFalse(plan.includesCollectionLog());
    assertFalse(plan.includesFullEnumeration());
  }

  @Test
  public void anOrdinaryLogChangeNeverClaimsFullEnumeration() {
    Acked acked = new Acked();

    SubmitPlan plan =
        TestPlans.plan(
            acked.skills,
            skills("attack", 100),
            acked.quests,
            states("COOKS_ASSISTANT", "FINISHED"),
            acked.diaries,
            states("VARROCK_EASY", "COMPLETE"),
            acked.log,
            new java.util.HashSet<>(Arrays.asList(1, 2, 3)),
            new CombatAchievementBaseline(),
            null,
            new AccountTypeBaseline(),
            null,
            false);

    assertTrue(plan.includesCollectionLog());
    assertFalse(plan.includesFullEnumeration());
  }

  @Test
  public void theShorterOverloadNeverClaimsFullEnumeration() {
    Acked acked = new Acked();

    SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2, 3)));

    assertTrue(plan.includesCollectionLog());
    assertFalse(plan.includesFullEnumeration());
  }
}

