package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.EnumSet;
import java.util.Map;
import org.junit.Test;

/** Which capabilities count as synced this cycle, for the panel's sync times and activity. */
public class SyncedCapabilitiesThisCycleTest {

  private static Map<String, String> synced(
      boolean skillsAdvanced,
      boolean skillsChanged,
      boolean questsAdvanced,
      boolean diariesAdvanced,
      boolean collectionLogAdvanced,
      boolean combatAchievementsAdvanced,
      boolean accountTypeAdvanced) {
    EnumSet<Capability> advanced = EnumSet.noneOf(Capability.class);
    add(advanced, Capability.SKILLS, skillsAdvanced);
    add(advanced, Capability.QUESTS, questsAdvanced);
    add(advanced, Capability.DIARIES, diariesAdvanced);
    add(advanced, Capability.COLLECTION_LOG, collectionLogAdvanced);
    add(advanced, Capability.COMBAT_ACHIEVEMENTS, combatAchievementsAdvanced);
    add(advanced, Capability.ACCOUNT_TYPE, accountTypeAdvanced);
    return BankstandPlugin.syncedCapabilitiesThisCycle(advanced, skillsChanged);
  }

  private static void add(EnumSet<Capability> set, Capability capability, boolean on) {
    if (on) {
      set.add(capability);
    }
  }

  @Test
  public void nothingAdvancedMeansNothingSynced() {
    assertTrue(synced(false, false, false, false, false, false, false).isEmpty());
  }

  /** Skills ride along on every submission, so a stored skills block alone is not "synced". */
  @Test
  public void skillsAdvancedWithNoActualChangeIsNotReportedAsSynced() {
    Map<String, String> result = synced(true, false, false, false, false, false, false);

    assertFalse(result.containsKey("skills"));
  }

  @Test
  public void skillsAdvancedWithARealChangeIsReportedWithItsOwnLine() {
    Map<String, String> result = synced(true, true, false, false, false, false, false);

    assertEquals("Skills synced", result.get("skills"));
  }

  /** A non-null quests, diaries or accountType value already means that capability changed. */
  @Test
  public void questsDiariesAndAccountTypeEachGetTheirOwnLineWhenAdvanced() {
    Map<String, String> result = synced(false, false, true, true, false, false, true);

    assertEquals("Quests synced", result.get("quests"));
    assertEquals("Diaries synced", result.get("diaries"));
    assertEquals("Account type synced", result.get("accountType"));
  }

  /** The collection log and combat achievements log their own more specific lines. */
  @Test
  public void collectionLogAndCombatAchievementsGetATimeButNoLine() {
    Map<String, String> result = synced(false, false, false, false, true, true, false);

    assertTrue(result.containsKey("collectionLog"));
    assertNull(result.get("collectionLog"));
    assertTrue(result.containsKey("combatAchievements"));
    assertNull(result.get("combatAchievements"));
  }

  @Test
  public void everythingAdvancingReportsAllSixCapabilities() {
    Map<String, String> result = synced(true, true, true, true, true, true, true);

    assertEquals(6, result.size());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.bankstand.http.HttpResponse;
import java.time.Instant;
import java.util.Collections;
import net.runelite.api.GameState;
import net.runelite.client.game.ItemStack;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** What the plugin does after the server says slow down, or cannot route a batch yet. */
public class ThrottlingTest {

  private static final String RATE_LIMITED = "{\"error\":\"rate limited\"}";
  private static final long TWO_MINUTES = 120_000L;

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private PluginHarness h;
  private CollectionLogUnlockCapture unlocks;

  @Before
  public void setUp() throws Exception {
    h = new PluginHarness(folder.getRoot());
    // Presence has its own test below; here it would add requests to every count.
    h.toggles.put("collectSessions", false);
    unlocks =
        new CollectionLogUnlockCapture(h.eventOutbox, () -> true, () -> PluginHarness.MAIN);
    h.logIn();
    h.executor.runAll();
  }

  private void unlock(String item) {
    unlocks.handleMessage("New item added to your collection log: " + item);
  }

  private void drain() {
    h.plugin.drainEventOutbox();
    h.executor.runAll();
  }

  private EventSendPacer eventPacer() throws Exception {
    return (EventSendPacer) h.get("eventPacer");
  }

  @Test
  public void anEvents429PausesTheDrainAndKeepsTheEvents() throws Exception {
    h.transport.byPath.put("/events", body -> new HttpResponse(429, RATE_LIMITED, "120"));
    unlock("Pet snakeling");
    drain();
    assertEquals("a 429 is never retried in place", 1, h.transport.count("/events"));
    assertEquals(1, h.eventOutbox.pending().size());

    drain();
    assertEquals("paused for the Retry-After", 1, h.transport.count("/events"));
    long now = System.currentTimeMillis();
    assertFalse(eventPacer().maySend(PluginHarness.MAIN, now + TWO_MINUTES - 5_000L));
    assertTrue(eventPacer().maySend(PluginHarness.MAIN, now + TWO_MINUTES + 1_000L));
  }

  @Test
  public void anUnroutedBatchWaitsHalfAnHourThenSendsAgain() throws Exception {
    h.transport.byPath.put(
        "/events", body -> new HttpResponse(200, "{\"routed\":false,\"acks\":[]}"));
    unlock("Pet snakeling");
    drain();
    drain();
    assertEquals(1, h.transport.count("/events"));
    assertEquals("kept for when the character is linked", 1, h.eventOutbox.pending().size());
    long now = System.currentTimeMillis();
    assertFalse(eventPacer().maySend(PluginHarness.MAIN, now + 29 * 60_000L));
    assertTrue(eventPacer().maySend(PluginHarness.MAIN, now + 31 * 60_000L));
  }

  @Test
  public void aRelogRetriesAnUnroutedBatchAtOnce() throws Exception {
    h.transport.byPath.put(
        "/events", body -> new HttpResponse(200, "{\"routed\":false,\"acks\":[]}"));
    unlock("Pet snakeling");
    drain();
    h.state(GameState.LOGIN_SCREEN);
    h.hash = 77L;
    h.logIn();
    h.state(GameState.LOGIN_SCREEN);
    h.hash = PluginHarness.MAIN;
    h.logIn();
    drain();
    assertEquals(2, h.transport.count("/events"));
  }

  @Test
  public void aRePairRetriesAnUnroutedAccountAtOnce() throws Exception {
    h.transport.byPath.put(
        "/events", body -> new HttpResponse(200, "{\"routed\":false,\"acks\":[]}"));
    h.transport.byPath.put(
        "/pair", body -> new HttpResponse(200, "{\"deviceToken\":\"tok-b\",\"deviceId\":\"d\"}"));
    unlock("Pet snakeling");
    drain();
    h.call("pair", "BBBB-BBBB");
    h.executor.runAll();
    // The re-pair dropped the old queue; a fresh capture goes out under the new pairing.
    unlock("Abyssal orphan");
    drain();
    assertEquals(2, h.transport.count("/events"));
  }


  @Test
  public void aReplyToAReplacedPairingNeitherHoldsNorPauses() throws Exception {
    unlock("Pet snakeling");
    // The pairing is replaced while the request is out; then its reply lands.
    h.transport.byPath.put(
        "/events", body -> repairedThen(new HttpResponse(200, "{\"routed\":false,\"acks\":[]}")));
    drain();
    assertEquals("the old reply arrived", 1, h.transport.count("/events"));
    assertTrue("no unrouted hold", eventPacer().maySend(PluginHarness.MAIN, System.currentTimeMillis()));

    unlock("Abyssal orphan");
    h.transport.byPath.put(
        "/events", body -> repairedThen(new HttpResponse(429, RATE_LIMITED, "120")));
    drain();
    assertEquals(2, h.transport.count("/events"));
    assertTrue("no pause", eventPacer().maySend(PluginHarness.MAIN, System.currentTimeMillis()));
  }

  private int repairs;

  /** Swaps in a new token, keeping the pairing tag so queued items still belong. */
  private HttpResponse repairedThen(HttpResponse reply) {
    DeviceCredentials current = h.deviceStore.load();
    DeviceCredentials next = DeviceCredentials.none();
    next.setToken("tok-" + (++repairs));
    next.setServerUrl(current.getServerUrl());
    next.setPairingId(current.getPairingId());
    h.deviceStore.save(next);
    return reply;
  }


  @Test
  public void aLoot429PausesLootSends() throws Exception {
    h.transport.byPath.put("/loot", body -> new HttpResponse(429, RATE_LIMITED, "120"));
    LootCapture loot =
        new LootCapture(
            () -> true,
            () -> PluginHarness.MAIN,
            new LootCapture.Items() {
              @Override
              public int canonical(int itemId) {
                return itemId;
              }

              @Override
              public boolean isNotable(int itemId, int quantity) {
                return false;
              }
            },
            (LootLedger) h.get("lootLedger"),
            h.lootOutbox,
            () -> {},
            Instant::now);
    loot.handleKill(2, "Goblin", Collections.singletonList(new ItemStack(526, 1)));
    h.state(GameState.LOGIN_SCREEN);
    h.executor.runAll();
    assertEquals(1, h.transport.count("/loot"));
    drain();
    assertEquals("paused for the Retry-After", 1, h.transport.count("/loot"));
    assertEquals(1, h.lootOutbox.pending().size());
    LootSendPacer pacer = (LootSendPacer) h.get("lootPacer");
    assertTrue(pacer.mayDrain(System.currentTimeMillis() + TWO_MINUTES + 1_000L));
  }

  @Test
  public void aPresence429PausesPresenceSends() throws Exception {
    h.toggles.put("collectSessions", true);
    h.transport.byPath.put("/presence", body -> new HttpResponse(429, RATE_LIMITED, "120"));
    h.call("pulsePresence");
    h.executor.runAll();
    assertEquals(1, h.transport.count("/presence"));

    // The next minute's mark and the queued retry both wait out the Retry-After.
    h.call("pulsePresence");
    drain();
    assertEquals(1, h.transport.count("/presence"));
  }

  @Test
  public void aRejectedTokenStopsPresenceUntilPairedAgain() throws Exception {
    h.toggles.put("collectSessions", true);
    h.transport.byPath.put("/presence", body -> new HttpResponse(401, ""));
    h.call("pulsePresence");
    h.executor.runAll();
    assertEquals(1, h.transport.count("/presence"));
    h.call("pulsePresence");
    drain();
    assertEquals("no heartbeat under a rejected token", 1, h.transport.count("/presence"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.junit.Test;

/** The plugin needs a live client to run, so where it reads the token is pinned on the source. */
public class TokenOriginWiringTest {

  private static String plugin() throws IOException {
    return new String(
        Files.readAllBytes(
            Paths.get("src", "main", "java", "com", "bankstand", "BankstandPlugin.java")),
        StandardCharsets.UTF_8);
  }

  @Test
  public void everySendTakesTheTokenForTheConfiguredServer() throws IOException {
    String source = plugin();
    int raw = source.split("getToken\\(\\)", -1).length - 1;
    // Disconnect and a new pairing revoke the old token, at the server it was paired with.
    assertEquals("only the two revokes may read the raw token", 2, raw);
    assertTrue(source.contains("paired.pairedServerUrl(), paired.getToken()"));
    assertTrue(source.contains("previous.pairedServerUrl(), previous.getToken()"));
    assertTrue(source.contains("return deviceStore.load().tokenFor(savedServerUrl()) != null;"));
  }

  @Test
  public void aNewPairingRecordsTheServerItWasMadeWith() throws IOException {
    String source = plugin();
    assertTrue(source.contains("storeToken(res, url, ticket, api)"));
    assertTrue(source.contains("deviceStore.save(DeviceCredentials.of(res, url))"));
  }

  private static String body(String source, String signature) {
    int start = source.indexOf(signature);
    assertTrue(signature, start >= 0);
    return source.substring(start, source.indexOf("\n  }\n", start));
  }

  @Test
  public void everyQueuedSendReadsItsTokenAndQueueAsOneStepWhenItRuns() throws IOException {
    String source = plugin();
    String[][] sends = {
      {"public void drainEventOutbox() {", "eventOutbox.pending()"},
      {"private void runPresenceSends() {", "presenceQueue.peek()"},
      {"private void sendLoot() {", "lootOutbox.pending()"},
    };
    for (String[] send : sends) {
      String body = body(source, send[0]);
      int lock = body.indexOf("synchronized (pairingQueues) {");
      int end = body.indexOf("}", lock);
      int token = body.indexOf("deviceStore.load().tokenFor(url)", lock);
      int queue = body.indexOf(send[1], lock);
      assertTrue(send[0] + " reads the token under the pairing lock", lock >= 0 && token < end);
      assertTrue(send[0] + " reads the queue under the pairing lock", queue > lock && queue < end);
    }
    assertTrue(body(source, "private void sendPresence() {").contains("this::runPresenceSends"));
  }

  @Test
  public void aReplacedTokensAuthFailureNeverHaltsTheNewPairing() throws IOException {
    String source = plugin();
    String snapshot = body(source, "private void submitSnapshot(");
    int skip = snapshot.indexOf("if (isReplaced(url, token)) {");
    assertTrue(skip >= 0 && skip < snapshot.indexOf("haltIfCurrent(url, token)"));
    String identity = body(source, "private void submitIdentity(");
    int skipIdentity = identity.indexOf("if (isReplaced(url, token)) {");
    assertTrue(skipIdentity >= 0 && skipIdentity < identity.indexOf("identityFailureNotice("));
  }

  @Test
  public void aCooldownRetryIsDroppedWhenThePairingChanged() throws IOException {
    String snapshot = body(plugin(), "private void submitSnapshot(");
    int retry = snapshot.indexOf("executor.schedule(");
    int check = snapshot.indexOf("|| isReplaced(url, token)) {", retry);
    assertTrue(retry >= 0 && check > retry && check < snapshot.indexOf("submitSnapshot(", retry));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.util.UUID;
import org.junit.Test;

public class UuidV7Test {
  @Test
  public void generatesACanonicalVersion7Uuid() {
    String s = UuidV7.generate();
    UUID parsed = UUID.fromString(s);
    assertEquals("36 chars", 36, s.length());
    assertEquals("version 7", 7, parsed.version());
    assertEquals("RFC variant", 2, parsed.variant());
    assertEquals("lowercase", s, s.toLowerCase());
  }

  @Test
  public void generatesDistinctValues() {
    assertNotEquals(UuidV7.generate(), UuidV7.generate());
  }

  @Test
  public void isTimeOrderedAcrossAShortDelay() throws Exception {
    String a = UuidV7.generate();
    Thread.sleep(2);
    String b = UuidV7.generate();
    // UUIDv7 leads with a millisecond timestamp, so lexical order tracks time.
    assertTrue("later uuid sorts after earlier", b.compareTo(a) > 0);
  }
}

